window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch06"]={"id":"ch06","title":"第四章 细胞骨架 · 第一节 微管","sub":"翟中和《细胞生物学》第4版 · 教师课件逐页详解","sub2":"微管结构 · 装配 · 马达蛋白 · 功能","modules":[{"i":0,"name":"第一节 微管 · 绪论 · 概览","slides":[{"i":0,"sec":"","title":"第四章 细胞骨架(cytoskeleton)与细胞运动","notes":"细胞骨架是由蛋白质亚基组成的纤维网架体系，参与维持细胞形态、细胞运动、物质运输和细胞分裂。真核细胞狭义的细胞骨架由微管、微丝和中间纤维三类纤维构成，此外核纤层也属于中间纤维。原核细胞中也存在与真核骨架类似的蛋白，如FtsZ、BtubA/B（与微管蛋白同源），MreB、ParM（与肌动蛋白同源），crescentin（与中间纤维蛋白同源），提示细胞骨架在进化上高度保守。本部分学习要求：①细胞骨架的组成与功能；②掌握骨架组装、解聚的动态特点与条件；③掌握马达蛋白(myosin、kinesin、dynein)的种类与作用原理。","page":1,"level":"掌握","img":"assets/img/ch06/p001.jpg","anim":null,"fig":null,"points":["真核细胞中的蛋白纤维网架体系"],"check":{"q":"细胞骨架是由蛋白纤维构成的网架体系，下列哪组属于细胞骨架的主要成分？","o":["A. 微管、微丝、核纤层","B. 微管、微丝、中间纤维","C. 微管、核糖体、中间纤维","D. 微丝、中心体、染色质"],"a":"B","e":"狭义的细胞骨架由微管、微丝和中间纤维构成，是由蛋白质亚基组成的动态网架体系。","oe":["核纤层是中间纤维的一种，不能与三类并列。","狭义细胞骨架由微管、微丝和中间纤维构成。","核糖体不是细胞骨架的组成成分。","中心体与染色质不属于细胞骨架三类纤维。"]},"cards":null,"mem":"骨架三考点：成分功能、动态组装、马达蛋白","big":"assets/img/ch06/big/p001.jpg","terms":[{"t":"马达蛋白","en":"motor protein","d":"具ATPase活性、水解ATP沿微管或微丝行走而产生力的蛋白。"},{"t":"动力蛋白","en":"dynein","d":"向微管负端(−)运动的马达蛋白。"}],"summary":"细胞骨架是由蛋白质亚基组成的纤维网架体系，参与维持细胞形态、细胞运动、物质运输和细胞分裂","goal":"学完应能掌握并运用「第四章 细胞骨架(cytoskeleton)与细胞运动」的核心内容，能解释其机制、比较相关概念。","intuition":"细胞骨架像细胞的“骨骼+肌肉+轨道”：微管、微丝、中间纤维各司其职。"},{"i":1,"sec":"","title":"什么维持了细胞形态各异的形状?","notes":"细胞形态各异，是由细胞骨架维持和支撑的。图为神经细胞正在伸长的轴突（红色荧光显示其骨架成分之一——微管）、小肠上皮细胞的微绒毛突起以及人血红细胞的电镜扫描照片。轴突、微绒毛等特化突起都由细胞骨架支撑，说明细胞骨架不仅维持细胞形态，还参与形成并维持细胞的特殊结构。","page":2,"level":"掌握","img":"assets/img/ch06/p002.jpg","anim":null,"fig":null,"points":["细胞骨架"],"check":{"q":"维持细胞形态并支撑轴突、微绒毛等特化突起的主要结构是？","o":["A. 细胞外被","B. 细胞骨架","C. 核被膜","D. 中心体"],"a":"B","e":"细胞骨架中的微管、微丝等维持细胞形态并支撑轴突、微绒毛等特化结构。","oe":["细胞外被主要起保护与识别作用，非支撑形态。","细胞骨架维持细胞形态并支撑轴突、微绒毛等。","核被膜包围细胞核，不决定细胞整体形态。","中心体是微管组织中心，不直接维持突起形态。"]},"cards":null,"mem":"细胞形态各异靠细胞骨架(微管等)","big":"assets/img/ch06/big/p002.jpg","summary":"细胞形态各异，是由细胞骨架维持和支撑的","goal":"学完应能掌握并运用「什么维持了细胞形态各异的形状?」的核心内容，能解释其机制、比较相关概念。","intuition":"细胞形态各异靠骨架支撑：轴突、微绒毛、红细胞形状都由骨架维持。"}],"mcq":[{"id":"ch06_mcq_6","mod":"绪论 · 概览","modI":0,"q":"凝胶与溶胶的互变与（       ）的变化有关。","o":["A．微丝","B．微管","C．中间丝","D．胶原纤维"],"a":"A","e":"微丝与细胞伪足的形成与迁移运动有关。","kp":"ch06_s0_0","oe":["正确。凝胶与溶胶的互变与微丝的解聚和聚合有关。","错误。微管主要参与运输和染色体运动，与此无直接关系。","错误。中间丝主要起机械支撑作用，不参与溶胶凝胶互变。","错误。胶原纤维是细胞外基质成分，与胞质胶凝无关。"]}],"judge":[{"id":"ch06_judge_6","modI":0,"q":"肌肉的收缩是细肌丝收缩的结果。              （      ）","a":"错","e":"肌肉的收缩是粗肌丝和细肌丝相对滑动的结果。","kp":"ch06_s0_0","oe":["若判对则误认为是细肌丝本身收缩，其实是粗细肌丝相对滑动。","肌肉收缩是粗肌丝与细肌丝相对滑动的结果，并非细肌丝自身收缩。"]}],"fill":[{"id":"ch06_fill_10","modI":0,"q":"广义的核骨架成分包括______、______和______。","a":"核基质核纤层；核孔复合体；染色体骨架","kp":"ch06_s0_1","oe":["核基质（含核纤层）是核内非染色质的纤维网络，为核骨架主体。","核孔复合体镶嵌于核膜，是核质之间物质运输的通道。","染色体骨架是维持染色体形态的非组蛋白支架结构。"]},{"id":"ch06_fill_16","modI":0,"q":"细胞骨架是指存在于真核细胞中的蛋白纤维网架体系，狭义的骨架系统主要是指细胞质 骨架，包括 ______、______和______。","a":"微丝；微管；中间纤维","kp":"ch06_s0_0","oe":["由肌动蛋白组成的细丝，直径约7nm，参与收缩和形态维持。","由微管蛋白组成的管状结构，参与运输、支持和纺锤体形成。","由角蛋白、结蛋白等组成的纤维，起机械支撑和抗张力作用。"]}],"short":[{"id":"ch06_short_4","modI":0,"q":"如何用荧光显微镜研究细胞骨架?其基本原理是什么？","a":"用荧光显微镜研究细胞骨架主要是基于两方面的原理。 （1）组成细胞骨架的蛋白亚基能够同小分子的荧光染料共价结合，使细胞骨架带上荧光标 记，发出荧光。 （2）可以制备细胞骨架的荧光抗体，然后用荧光抗体进行细胞骨架的研究。借助于这两方 面原理，可用荧光显微镜研究细胞骨架的动力学。例如，用小分子的荧光染料标记细胞骨架 的蛋白亚基，就可以追踪细胞骨架蛋白在细胞活动中的作用，包括组装、去组装、物质运输 等。这种方法还有一个好处，就是在活细胞时就可以观察。 可用荧光抗体研究以很低浓度存在的蛋白质在细胞内的位置，因为标记的荧光抗体同特异的 蛋白质具有很高的亲和性，只要有相应的蛋白质存在，就一定会有反应。这种反应是特异的， 通过荧光显微镜观察就可确定。荧光抗体既可以直接注射活细胞进行反应，也可以加到固定 的细胞或组织切片中进行反应和分析。用这种方法可对微管、肌动蛋白纤维、中间纤维进行 定位。","kp":"ch06_s0_1"},{"id":"ch06_short_12","modI":0,"q":"何谓细胞骨架？如何理解细胞骨架是细胞内的一种动态结构？","a":"（1）细胞骨架的概念 细胞骨架是指由细胞内蛋白质成分组成的一个复合的网架系统，包括微管、微丝和中间丝。 与其他细胞结构相比，细胞骨架在形态结构上具有弥散性、整体性和变动性等特点，这些都 是与它们的功能相适应的。细胞骨架为真核细胞所特有，它不仅是活细胞的支撑结构，决定 了细胞的形状并赋予其强度，而且在细胞多种多样的生理活动（如细胞运动、膜泡运输和细 胞分裂等）中发挥着重要作用。 （2）细胞骨架是一种动态结构的理解 由于细胞骨架与细胞运动有关，在不同的功能状态、不同的细胞周期，细胞骨架是不断地组 装或去组装，因此细胞骨架是细胞内的一种动态结构。","kp":"ch06_s0_1"},{"id":"ch06_short_14","modI":0,"q":"通过本章的学习，你对生命体的自组装原则有何认识？","a":"我对生命体自组装原则的认识如下： （1）细胞内的复杂结构可由简单的分子组装而成，其组装过程受到细胞本身的调节，这样 便于细胞在不同生理状态下调节细胞结构的组织形式，执行特定的功能。 （2）多种结构相互联系，共同完成细胞的生命活动。 （3）生命体在装配过程中受到多种因素影响。如影响微管组装的因素有秋水仙素、紫杉醇、 长春花碱；影响微丝组装的因素有细胞松弛素、鬼笔环肽。 （4）生命体自组装具有高度的时空顺序性。","kp":"ch06_s0_0"}],"calc":[{"id":"ch06_calc_1","modI":0,"q":"什么是分子马达？举例说明（至少 3 个）。","a":"分子马达（molecular motor），主要是指依赖于微管的驱动蛋白、动力蛋白和依赖于微 丝的肌球蛋白这三类蛋白超家族的成员。它们既能与微管或者微丝结合，又能与一些细胞器 或膜状小泡特异性结合，并利用水解 ATP 所产生的能量有规则地沿微管或微丝等细胞骨架 纤维运输所携带的“货物”。 （1）肌球蛋白是与微丝相关的一类分子马达。其共同特征是都含有一个作为马达结构域的 头部。其马达结构域包含一个微丝结合位点和一个具有 ATP 酶活性的 ATP 结合位点。 ①Ⅱ型肌球蛋白存在于多种细胞，包含 2 条重链和 4 条轻链。头部即马达结构域，尾部主要 起结构作用。Ⅱ型肌球蛋白尾尾相接所构成的双极纤维能介导相邻的微丝相互滑动。 ②Ⅰ型肌球蛋白头部亦为马达结构域，在 ATP 存在时可沿微丝运动。其尾部结构域具有多 样性，能与多种细胞组分结合，通过头部驱动或细胞质膜作相对于微丝的运动。V 型肌球蛋 白是二聚体马达蛋白，具有两个头部，交替与微丝结合可以确保整个分子以及所运载的“货 物”始终不与微丝脱离。 （2）驱动蛋白是一类蛋白质超家族，与微管相关。通常由 2 条重链和 2 条轻链组成，它们 共有保守的“马达”域，内有 ATP 结合位点和微管结合位点。马达结构域在重链的 N 端，介 导物质向微管的正极运动；而另一些少数驱动蛋白的马达结构域在重链的 C 端，介导物质 向微管的负极运动。 驱动蛋白的马达结构域具有两个重要的功能位点： ①ATP 结合位点； ②微管结合位点。 有关驱动蛋白沿微管运动的分子模型有两种：步行模型和尺蠖爬行模型。大多数学者承认步 行模型：驱动蛋白的两个球状头部交替向前，每水解一分子 ATP，落在后面的那个马达结 构域将移动两部的距离，即 16nm，并循环该过程。 （3）动力蛋白是马达蛋白中最大、移动速度最快的成员： ①轴丝动力蛋白，在纤毛与鞭毛中发现，与纤毛和鞭毛的运动相关； ②胞质动力蛋白，在真核细胞胞质内发现，与细胞内介导微管从正极向负极端的膜泡运输以 及有丝分裂动粒和纺锤体的共定位有关。 动力蛋白由 2 条或 3 条重链，多条轻链及中间链组成。其马达结构域位于重链 C 端，轴丝 动力蛋白有 3 个马达结构域，胞质动力蛋白有 2 个马达结构域。","kp":"ch06_s0_0"},{"id":"ch06_calc_4","modI":0,"q":"细胞中同时存在几种骨架体系有什么意义？是否是物质和能量的一种浪费？","a":"（1）细胞骨架是指细胞内以蛋白质纤维为主要成分的网络结构，细胞中同时存在的骨 架体系为微丝、微管和中间丝，这三种细胞骨架的意义在于它们在细胞的生命活动中各自的 功能。 ①微丝的功能主要有：肌细胞中参与肌原纤维收缩；非肌细胞中参与胞质分裂、胞质环流、 吞噬作用、细胞变形运动、膜泡运输、细胞黏着与连接（黏着带与黏着斑）、微绒毛的支撑 结构等。 ②微管的功能主要包括：支架作用，维持细胞形态、定位细胞器，作为细胞内物质运输通道， 作为纤毛、鞭毛的运动元件，构成纺锤体参与细胞分裂等。 ③中间丝的功能有：为细胞提供机械强度支持，参与细胞连接（桥粒与半桥粒），维持核膜 稳定等。 （2）三种骨架成分在细胞中同时存在不是物质和能量的一种浪费，理由如下： 三种骨架成分在细胞中同时存在，自成系统，但又互相联系，互不重合。微丝分布在靠近细 胞膜的部位，微管、中间丝从细胞核向细胞周缘放射状延伸。它们在功能上相互配合、相互 协调，缺乏任何一种骨架成分都会引起细胞生命活动的异常。因此细胞中同时存在几种骨架 体系并不是物质和能量的浪费。","kp":"ch06_s0_0"}],"term":[]},{"i":1,"name":"第一节 微管 · I 细胞骨架的基本组成及其结构","slides":[{"i":2,"sec":"","title":"I 细胞骨架的基本组成及其结构","notes":"真核细胞狭义的细胞骨架由三类纤维构成：①微管(microtubule, MT)——中空管状、最粗，外径约24nm，有极性（正极、负极）；②微丝(microfilament, MF)——实心丝状、最细，直径约7nm，有极性；③中间纤维(intermediate filament, IF)——实心线状、粗细居中，直径约10nm，无极性。三者的组成蛋白、直径与极性是常考的对比点。","page":3,"level":"掌握","img":"assets/img/ch06/p003.jpg","anim":null,"fig":null,"points":["三类细胞骨架：微管MT、微丝MF、中间纤维IF","微管24nm中空管、有极；微丝7nm实心、有极；中间纤维10nm实心、无极性"],"check":{"q":"关于细胞骨架三大纤维的结构特点，正确的是？","o":["A. 微管实心、微丝中空，二者均无极性","B. 微丝最粗（24nm），中间纤维有极性","C. 微管中空最粗（24nm）有极性，中间纤维无极性","D. 三者均为中空管状且都有极性"],"a":"C","e":"微管为中空管状、最粗（外径24nm）且有极性；微丝最细（7nm）有极性；中间纤维直径约10nm、无极性。","oe":["微管中空、微丝实心，且均有极性，故错误。","最粗的是微管，中间纤维无极性，故错误。","正确，微管中空最粗有极性，中间纤维无极性。","微丝与中间纤维为实心，中间纤维无极性。"]},"cards":null,"mem":"微管24nm有极、微丝7nm有极、中间纤维10nm无极","big":"assets/img/ch06/big/p003.jpg","terms":[{"t":"微丝","en":"microfilament, MF","d":"由肌动蛋白(actin)组成、直径约7nm的骨架纤维，有极性。"},{"t":"中间纤维","en":"intermediate filament, IF","d":"直径约10nm、无极性、具组织特异性的骨架纤维。"}],"summary":"真核细胞狭义的细胞骨架由三类纤维构成：①微管(microtubule, MT)——中空管状、最粗，外径约24nm，有极性（正极、负极）；②微丝(microfilament, MF)","goal":"学完应能掌握并运用「I 细胞骨架的基本组成及其结构」的核心内容，能解释其机制、比较相关概念。","intuition":"三类骨架对比：微管 24nm 中空有极、微丝 7nm 实心有极、中间纤维 10nm 实心无极。"},{"i":3,"sec":"","title":"三类细胞骨架纤维由各自特定亚基组装","notes":"reversible process.\nBottom panels show localization of the 3 filament systems in the\nsame cultured cell.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · I 细胞骨架的基本组成及其结构 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页讲细胞骨架的三大纤维系统均由各自特定的亚基（subunit）通过可逆的组装与去组装过程装配而成，且这三类纤维可在同一培养细胞中同时存在。下图用不同荧光标记展现了微丝、微管和中间纤维在同一细胞内的定位（localization）差异。考点：三大骨架组分的基本组成与自组装可逆性，对应翟中和《细胞生物学》第4版第十章细胞骨架总论。","page":4,"level":"掌握","img":"assets/img/ch06/p004.jpg","anim":null,"fig":null,"points":["三类纤维由各自的亚基可逆组装","同一细胞中三套纤维系统共存并各有定位"],"check":{"q":"细胞骨架三大纤维系统的共同特点是？","o":["A. 由特定亚基通过可逆的组装与去组装过程装配","B. 由各自特定亚基以不可逆方式聚合而成","C. 由同一种蛋白亚基组成，无差异","D. 一旦形成便固定不变，不进行更新"],"a":"A","e":"三类骨架纤维均由各自特定的亚基（subunit）通过可逆的组装与去组装过程装配而成，并可在同一细胞中同时存在。","oe":["正确，由特定亚基可逆组装与去组装。","组装是可逆过程而非不可逆，故错误。","三类纤维组成蛋白不同，非同一亚基。","骨架是动态的、不断更新，故错误。"]},"cards":null,"mem":"三纤维均由亚基可逆组装，同细胞共存","big":"assets/img/ch06/big/p004.jpg","summary":"考点：第一节 微管 · I 细胞骨架的基本组成及其结构 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「三类细胞骨架纤维由各自特定亚基组装」的核心内容，能解释其机制、比较相关概念。","intuition":"三类纤维由各自亚基组装，同一细胞内三套系统并存、各有定位。"},{"i":4,"sec":"","title":"微丝                     微管骨架","notes":"The cytoskeleton filament in a cultured liver cell (2006)\n中间纤维\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · I 细胞骨架的基本组成及其结构 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 细胞骨架（cytoskeleton）：是细胞内蛋白质成分组成的一个复合网架系统，包括微管、微丝和中间丝。\n\n【本页英文讲解】\n本页以2006年培养的肝细胞（liver cell）为例，展示细胞骨架（cytoskeleton）三种纤维在同一细胞中的分布：微丝（microfilament, MF）、微管（microtubule, MT）以及中间纤维（intermediate filament, IF）。三种纤维相互交织、各成网络，共同维持细胞形态与结构。记忆要点是三大组分的中英名称及它们在细胞内的不同空间排布，为第十章细胞骨架的学习打基础。","page":5,"level":"掌握","img":"assets/img/ch06/p005.jpg","anim":null,"fig":null,"points":["培养肝细胞中含三类细胞骨架纤维","即微丝MF、微管MT、中间纤维IF"],"check":{"q":"细胞骨架的三类纤维是？","o":["A. 微丝、微管、中间纤维","B. 微丝、核纤层、胶原纤维","C. 微管、肌动蛋白、中心体","D. 中间纤维、纺锤体、质膜"],"a":"A","e":"细胞骨架包括微管、微丝和中间丝；在培养肝细胞中三类纤维相互交织、各成网络，共同维持细胞形态与结构。","oe":["正确，三类纤维为微丝、微管、中间纤维。","胶原纤维属细胞外基质，非骨架纤维。","肌动蛋白是微丝成分、中心体是MTOC。","纺锤体由微管构成、质膜非骨架纤维。"]},"cards":null,"mem":"肝细胞三骨架：微丝MF、微管MT、中间纤维IF","big":"assets/img/ch06/big/p005.jpg","summary":"考点：第一节 微管 · I 细胞骨架的基本组成及其结构 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「微丝                     微管骨架」的核心内容，能解释其机制、比较相关概念。","intuition":"本页以图对比三类骨架纤维的组成蛋白：微管=tubulin、微丝=actin、IF=多种蛋白。"},{"i":5,"sec":"","title":"细胞骨架的超微结构及其模式图","notes":"微管(MT)        微丝(MF)   中间纤维(IF)\n组成蛋白tubulin   组成蛋白actin 组成蛋白多种\n\n【读图讲解】\n本图展示细胞骨架三大组分的超微结构与模式图。左侧为微管(MT)，呈中空管状，由α、β微管蛋白(tubulin)二聚体螺旋排列组成，旁附电镜照片；中间为微丝(MF)，由肌动蛋白(actin)单体聚合成的双螺旋结构；右侧为中间纤维(IF)，其组成蛋白种类多样，并绘出组装流程：单体(Monomer)→二聚体(Dimer)→四聚体(Tetramer)→原纤维(Protofilament)→中间纤维(Filament)，标注N端、C端。要点：牢记三类骨架的管状/纤维形态、组成蛋白及IF的逐级组装方式，注意IF无极性、由四聚体为基本单位。","page":6,"level":"掌握","img":"assets/img/ch06/p006.jpg","anim":null,"fig":null,"points":["微管组成蛋白为tubulin，微丝为actin，中间纤维为多种蛋白","中间纤维组装无极性"],"check":{"q":"关于中间纤维(IF)的组装，下列叙述正确的是？","o":["A. 由肌动蛋白单体直接聚合为纤维","B. 由α、β微管蛋白二聚体螺旋排列呈中空管状","C. 组装依赖极性，两端分别为正负极","D. 经单体→二聚体→四聚体→原纤维逐级组装，以四聚体为基本单位"],"a":"D","e":"中间纤维由多种蛋白组成，经单体、二聚体、四聚体、原纤维逐级组装，以四聚体为基本单位且无极性。","oe":["错：肌动蛋白构成微丝，不符合本页所学概念","错：描述的是微管而非中间纤维，不符合本页所学概念","错：中间纤维没有极性，不分正负极","对：符合笔记IF逐级组装描述，与笔记原文相符"],"basis":"单体→二聚体→四聚体→原纤维→中间纤维…以四聚体为基本单位"},"cards":null,"mem":"MT管状tubulin、MF双螺旋actin、IF多蛋白无极性","big":"assets/img/ch06/big/p006.jpg","terms":[{"t":"微管蛋白","en":"tubulin","d":"由α、β两个亚基组成的异二聚体，是微管的组成单位。"},{"t":"二聚体","en":"dimer","d":"由α-、β-tubulin结合成的异二聚体，是微管装配的基本单元。"},{"t":"原纤维","en":"protofilament","d":"微管蛋白二聚体首尾相连成的纵向长链，13条围成一根微管。"}],"summary":"微管(MT)        微丝(MF)   中间纤维(IF)","goal":"学完应能掌握并运用「细胞骨架的超微结构及其模式图」的核心内容，能解释其机制、比较相关概念。","intuition":"超微结构模式图帮你看清三类纤维的粗细、极性与组成。"}],"mcq":[],"judge":[],"fill":[{"id":"ch06_fill_17","modI":1,"q":"广义细胞骨架包括_________、_________、_________及_________，它们一起构成了高 等动物的纤维网络结构。","a":"细胞核骨架；细胞质骨架；细胞膜骨架；细胞外基质","kp":"ch06_s1_5","oe":["核内以核纤层、核基质为主的纤维网络体系。","由微丝、微管和中间纤维组成的细胞质网架系统。","膜下由血影蛋白、肌动蛋白等构成的支撑网络。","细胞分泌的糖蛋白、蛋白聚糖等构成的胞外网络。"]}],"short":[{"id":"ch06_short_7","modI":1,"q":"如何证明染色体骨架的真实性？","a":"（1）银染法能选择性地显示染色体轴结构；（2）DNA 酶和 RNA 酶处理或用 0.4mol ／LH2sO4 处理去除组蛋白，对染色体轴没有影响，用胰蛋白酶消化则染色体轴破坏，说明 染色体轴是非组蛋白性的；（3）染色体骨架／放射环模型在分子水平上得到两个直接证据。","kp":"ch06_s1_5"},{"id":"ch06_short_15","modI":1,"q":"除支持作用和运动功能外，细胞骨架还有什么功能？怎样理解“骨架”的概念？","a":"（1）细胞骨架的其他功能 为物质运输提供轨道、参与肌肉收缩和细胞分化、介导染色体的移动和动物细胞胞质分裂、 形成细胞的特化结构等。 （2）“骨架”的理解 ①骨架是指真核细胞内一个复杂的由特异蛋白质组成的纤维网架结构，具有支持功能，在细 胞形态维持、膜性细胞器定位和移动过程中具有重要的作用。 ②理解骨架概念时的注意事项： a．细胞骨架是一种动态平衡的结构； b．具有多种功能； c．由蛋白质组装而成，组装的过程受到信号的调节。","kp":"ch06_s1_5"}],"calc":[{"id":"ch06_calc_2","modI":1,"q":"试述三种胞质细胞骨架的主要成分、形态结构、功能及特异性药物。","a":"细胞骨架（cytoskeleton）是指真核细胞中复杂的蛋白纤维网架体系。广义的细胞骨架包 括细胞核骨架，细胞质骨架，细胞膜骨架和细胞外基质。狭义的细胞骨架是指细胞质骨架， 包括微丝（microfilament，MF）、微管（microtubule，MT）、中间纤维（inter- mediated filament， IF）。 （1）微管的形态结构：中空圆柱状，直径 15nm，一般长几微米，微管蛋白是与肌动蛋白相 似的一种酸性蛋白质，常常以二聚体存在（αβ-微管蛋白）。 微管的功能：①支架作用：维持细胞形态、固定细胞器。②细胞收缩，伪足运动；如纤毛、 鞭毛。③细胞器位移、染色体分裂与位移。④胞质内物质运输。 特异性药物：紫杉酚：抗肿瘤药物，研究表明它对微管的作用与传统的抗癌药长春花碱和秋 水仙碱等相反，它能促进微管的聚合、抑制微管的解聚。是微管的特异性稳定剂。 （2）微丝的形态结构：微丝存在很普遍，具有可变结构，直径 6 μm，由肌动蛋白组成，与 微管共同构成细胞支架。 微丝的功能：①与微管共同形成细胞支架，以维持细胞形状。②具有运动功能，与细胞质的 运动紧密相关。③与细胞器关系密切。④细胞内信号传递、蛋白质合成支架。 特异性药物：鬼笔环肽：特异性与微丝侧面结合，增强其稳定性，抑制微丝解聚，对微丝具 有稳定作用。荧光标记的鬼笔环肽可特异性的显示微丝。是微丝的特异性稳定剂。 细胞松弛素：可以切断微丝，并结合在微丝正极阻抑肌动蛋白聚合，因而可以破坏微丝的三 维网络，特异性的抑制微丝的装配。是微丝的特异性抑制剂。 （3）中间纤维：大小介于微管和微丝之间，结构复杂。中间纤维具有严格的组织特异性， 不同类型细胞含有不同 IF。按其组织来源及免疫原性可分为 5 类：①角蛋白纤维：为上皮 细胞特有，具有α和β两类，β角蛋白存在于体表、体腔的上皮细胞中，α角蛋白形成头发、 指甲等坚韧结构；②波形纤维：存在于间充质细胞及中胚层来源的细胞中；③神经胶质纤维： 存在于星形神经胶质细胞；④结蛋白纤维：存在于肌肉细胞；⑤神经元纤维：存在于神经元 中。 此外细胞核中的核纤层蛋白（lamin）也是一种中间纤维。 肿瘤细胞转移后仍保留源细胞的 IF，因此可用 IF 抗体来鉴定肿瘤的来源。如乳腺癌和胃肠 道癌，含有角蛋白，因此可断定它来源于上皮组织。而且大多数细胞中只含有一种中间纤维 （少数细胞含有两种以上，如骨骼肌细胞含有结蛋白和波形蛋白）。中间纤维这种严格的组 织特异性，就被应用于肿瘤临床鉴别诊断，以鉴别肿瘤细胞。 至今尚未发信中间纤维的特异性药物。","kp":"ch06_s1_5"}],"term":[]},{"i":2,"name":"第一节 微管 · 一、微管","slides":[{"i":6,"sec":"1.1 微管(microtubule, ","title":"一、微管","notes":"一、微管\n1.1 微管(microtubule, MT)的装配\n• 微管蛋白异二聚体(α,β-tubulin)是微管(MT)装配的基本单位。\n• α-tubulin 上有 1 个 GTP 结合位点：不可逆结合、不能水解（N-site，不可交换位点）。\n• 第 2 个 GTP 结合位点在 β-tubulin 上：可逆结合、可水解 GTP（E-site，可交换位点）。\n• α-tubulin + GTP-β-tubulin → α,β-tubulin 二聚体。\n• 装配：二聚体先装配成原纤维(protofilaments) → 侧面增加扩展为片层(sheet) → 13 根原纤维合拢形成中空微管；新的游离 GTP-α,β-tubulin 不断加到两端使微管延长。\n【读图讲解·考点】\nα/β 异二聚体是微管装配的基本单位；两个 GTP 位点不同——α 上的 N-site 不可交换/不水解，β 上的 E-site 可交换并可水解（GTP→GDP）。β 位点 GTP 水解是微管动态不稳定性的分子基础（GTP 帽维持正端聚合，GDP 化促解聚）。","page":7,"level":"掌握","img":"assets/img/ch06/p007.jpg","anim":null,"fig":null,"points":["α,β-tubulin 异二聚体是微管装配基本单位","α 上 N-site：不可交换、不水解；β 上 E-site：可交换、可水解 GTP","GTP→GDP 水解是动态不稳定性基础"],"check":{"q":"关于微管蛋白上的两个GTP结合位点，下列叙述正确的是？","o":["A. α、β亚基的GTP位点均可水解GTP","B. β-tubulin上的E-site可交换并可水解GTP","C. E-site位于α-tubulin且不可交换","D. α-tubulin上的N-site可交换且可水解GTP"],"a":"B","e":"α-tubulin的N-site不可交换、不水解；β-tubulin的E-site可交换并可水解GTP，其水解是动态不稳定性基础。","oe":["仅β亚基的E-site可水解GTP，α的N-site不可。","β-tubulin的E-site可逆结合并可水解GTP。","E-site位于β-tubulin，且可交换。","α-tubulin的N-site不可交换也不能水解GTP。"]},"cards":null,"mem":"微管单位αβ异二聚体；αN位不水解，βE位可水解GTP","big":"assets/img/ch06/big/p007.jpg","summary":"微管蛋白异二聚体(α,β-tubulin)是微管(MT)装配的基本单位","goal":"学完应能掌握并运用「一、微管」的核心内容，能解释其机制、比较相关概念。","intuition":"微管像“13 根原纤维围成的空心管”：由 αβ-tubulin 二聚体聚合而成。"},{"i":7,"sec":"1.1 微管(microtubule, ","title":"（本页为图片/无文字层）","notes":"【读图讲解】\n结构示意+电镜。α/β-微管蛋白组成异二聚体（β上含GTP结合位点），二聚体串成原纤维(protofilament)，多条围成中空微管，标注 plus/minus end、lumen。考点：异二聚体是微管基本亚基；微管有极性、中空。","page":8,"level":"掌握","img":"assets/img/ch06/p008.jpg","anim":null,"fig":null,"points":["β-tubulin","GTP","tubulinheterodimer","（=microtubule subunit)","(E)","10nm","protofilament","lumen"],"check":{"q":"微管的基本亚基及其聚合方式是？","o":["A. 肌动蛋白单体双螺旋排列成中空管","B. α、β-微管蛋白异二聚体串成原纤维，多条围成中空微管","C. 由单一α微管蛋白聚合而成","D. 由中间纤维四聚体围成中空管"],"a":"B","e":"α/β-微管蛋白组成异二聚体（β上含GTP结合位点），二聚体串成原纤维，多条原纤维围成中空微管，并具plus/minus端。","oe":["肌动蛋白构成微丝，非微管的亚基。","正确，α/β异二聚体构成原纤维并围成中空微管。","微管由α、β两种微管蛋白组成，非单一α。","四聚体是中间纤维的基本单位，非微管。"]},"cards":null,"mem":"αβ二聚体串成原纤维，多条围成中空有极微管","big":"assets/img/ch06/big/p008.jpg","summary":"α/β-微管蛋白组成异二聚体（β上含GTP结合位点），二聚体串成原纤维(protofilament)，多条围成中空微管，标注 plus/minus end、lumen","goal":"学完应能掌握并运用「（本页为图片/无文字层）」的核心内容，能解释其机制、比较相关概念。","intuition":"本页以图展示微管由二聚体串成原纤维、再围成管。"},{"i":8,"sec":"1.1 微管(microtubule, ","title":"微管的结构和类型 ●形态","notes":"微管类型\n●组成分为：单管、二联体微管、三联体微管\n细胞中大部分微管是单体微管，13根原纤维构成;\n鞭毛、纤毛中，二联体；\n中心体和基体(basal body)中，三联体\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 一、微管 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体","page":9,"level":"掌握","img":"assets/img/ch06/p009.jpg","anim":"mt_assembly","fig":null,"points":["Microtubules are hollow, tubular structures","outer diameter of 24 nm, inner diameter of 14 nm","wall thickness of approximately 4 nm","微管的长度变化不定"],"check":{"q":"关于微管的形态与类型，下列叙述正确的是？","o":["A. 细胞中大部分为单管，由13根原纤维围成中空结构","B. 微管外径约7nm，由9根原纤维构成","C. 鞭毛、纤毛中的微管为三联体","D. 中心体和基体中的微管为二联体"],"a":"A","e":"微管为13根原纤维纵向排列的中空结构；鞭毛纤毛中为二联体，中心体与基体中为三联体。","oe":["大部分微管为单管，13根原纤维形成中空管。","微管外径约24nm，且由13根原纤维构成。","鞭毛、纤毛中为二联体微管而非三联体。","中心体和基体中的微管为三联体，非二联体。"]},"cards":null,"mem":"单管13原纤维；纤毛鞭毛二联体；中心体基体三联体","big":"assets/img/ch06/big/p009.jpg","summary":"组成分为：单管、二联体微管、三联体微管","goal":"学完应能掌握并运用「微管的结构和类型 ●形态」的核心内容，能解释其机制、比较相关概念。","intuition":"微管分单管、二联体、三联体等类型，见于胞质、中心粒、鞭毛纤毛。"},{"i":9,"sec":"1.1 微管(microtubule, ","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• Figure 6.24 Structure of a flagellum or motile cilium. —— 图6.24 鞭毛或能动纤毛的结构\n• Microtubules —— 微管\n• Plasma membrane —— 质膜\n• Basal body —— 基体\n• 0.5 μm / 0.1 μm —— 0.5 / 0.1 微米（标尺）\n• (a) A longitudinal section of a motile cilium shows microtubules running the length of the membrane-sheathed structure (TEM). —— (a) 能动纤毛纵切面：微管沿被质膜包裹的结构全长延伸（透射电镜 TEM）\n• (b) A cross section through a motile cilium shows the \"9 + 2\" arrangement of microtubules (TEM). The outer microtubule doublets are held together with the two central microtubules by flexible cross-linking proteins (blue in art), including the radial spokes. The doublets also have attached motor proteins called dyneins (red in art). —— (b) 能动纤毛横切面：微管呈“9+2”排列（TEM）；外侧二联体与两根中央微管由柔性交联蛋白（图中蓝色，含径向辐条）相连；二联体上附着马达蛋白——动力蛋白（图中红色）\n• (c) Basal body: The nine outer doublets of a cilium or flagellum extend into the basal body, where each doublet joins another microtubule to form a ring of nine triplets. Each triplet is connected to the next by nontubulin proteins. This is a \"9 + 0\" arrangement: The two central microtubules are not present because they terminate above the basal body (TEM). —— (c) 基体：纤毛/鞭毛的 9 个外侧二联体伸入基体，各与另 1 根微管结合，形成 9 个三联体的环；相邻三联体由非微管蛋白相连。此为“9+0”排列：两根中央微管在基体上方终止，故基体中不存在（TEM）\n• Outer microtubule doublet —— 外侧微管二联体\n• Central microtubule —— 中央微管\n• Motor proteins (dyneins) —— 马达蛋白（动力蛋白 dynein）\n• Radial spoke —— 径向辐条\n• Cross-linking protein between outer doublets —— 外侧二联体之间的交联蛋白\n• Triplet —— 三联体\n• Cross section of basal body —— 基体横切面\n【读图讲解】\n电镜+模式图。运动纤毛/鞭毛横切为“9+2”：9对外周二联体微管+2根中央微管，二联体带动力蛋白臂(dynein)、辐条(radial spoke)与连接蛋白；基体为“9+0”三联体、无中央微管。考点：9+2 轴丝结构、动力蛋白驱动。","page":10,"level":"掌握","img":"assets/img/ch06/p010.jpg","anim":null,"fig":null,"points":["0.1 μm","Outermicrotubule","Plasma","doublet","membrane","Motorproteins","(dyneins)","Central"],"check":{"q":"能动纤毛/鞭毛横切面微管的排列及附着蛋白是？","o":["A. 9+0排列，二联体上无马达蛋白","B. 13根原纤维平行排列，无中央微管","C. 9+2排列，二联体上附着马达蛋白动力蛋白","D. 9+2排列，中央两根微管上附着动力蛋白"],"a":"C","e":"能动纤毛横切面微管呈“9+2”排列，外侧二联体与两根中央微管由交联蛋白相连，二联体上附着马达蛋白——动力蛋白。","oe":["能动纤毛为9+2且有动力蛋白，故错误。","13根原纤维平行排列描述的是单根微管。","正确，9+2排列且二联体附动力蛋白。","动力蛋白附着于外侧二联体而非中央微管。"]},"cards":null,"mem":"纤毛轴丝9+2：外二联体+中央对，动力蛋白臂","big":"assets/img/ch06/big/p010.jpg","summary":"Figure 6.24 Structure of a flagellum or motile cilium. —— 图6.24 鞭毛或能动纤毛的结构","goal":"学完应能掌握并运用「（本页为图片/无文字层）」的核心内容，能解释其机制、比较相关概念。","intuition":"本页以图展示二联体、动力蛋白臂、放射辐等轴丝结构。"},{"i":10,"sec":"1.1 微管(microtubule, ","title":"●根据稳定性分为：","notes":"神经元细胞内微管\n\n【读图讲解】\n本图讲细胞骨架(微管)根据稳定性的分类。左侧文字指出：②根据稳定性分为不稳定微管，如纺锤体微管；稳定微管，如鞭毛、纤毛微管及神经元细胞内微管。图(A)显示可溶性小亚基与丝状多聚体之间的双向聚合/解聚平衡。图(B)以细胞示意图表现动态变化：受营养等信号刺激后，已组装的纤维解聚，亚基快速扩散，随后在新的部位重新组装。要点：理解微管动态不稳定性/踏车行为，区分不稳定与稳定微管，明确稳定微管存在于纤毛、鞭毛和神经元突起中。","page":11,"level":"掌握","img":"assets/img/ch06/p011.jpg","anim":"mt_stability","fig":null,"points":["不稳定微管，如纺锤体微管","稳定微管， 如鞭毛、纤毛微管;"],"check":{"q":"按稳定性划分，下列微管属于稳定微管的是？","o":["A. 成膜体微管","B. 纺锤体微管","C. 鞭毛、纤毛微管及神经元细胞内微管","D. 早前期带微管"],"a":"C","e":"不稳定微管如纺锤体微管，稳定微管如鞭毛、纤毛微管及神经元细胞内微管。","oe":["成膜体微管为暂时性结构，属不稳定微管。","纺锤体微管随分裂周期解聚聚合，属不稳定微管。","鞭毛、纤毛及神经元微管属于稳定微管。","早前期带微管随周期变化，属不稳定微管。"]},"cards":null,"mem":"不稳定微管如纺锤体；稳定微管如鞭毛纤毛神经元","big":"assets/img/ch06/big/p011.jpg","summary":"神经元细胞内微管","goal":"学完应能掌握并运用「●根据稳定性分为：」的核心内容，能解释其机制、比较相关概念。","intuition":"微管按稳定性分：动态的胞质微管 vs 稳定的轴丝微管（永久性）。"},{"i":11,"sec":"1.1 微管(microtubule, ","title":"微管的动态不稳定性 (Microtubule dynamic instability)","notes":"【读图讲解】\n体外实验：游离 tubulin（αβ 异二聚体）浓度高于临界浓度、并满足 pH6.9、Mg²⁺、37℃、GTP 供能时，聚合为微管；低于临界浓度，且有 Ca²⁺ 或 0℃ 低温时，微管解聚为 tubulin。临界浓度=聚合与解聚达动态平衡所需的最低游离 tubulin 浓度。微管末端在生长与缩短间随机切换即为动态不稳定性；右侧荧光延时图像直接记录活细胞中微管的动态变化。\n\n【本页英文讲解】\n本页主题是微管的动态不稳定性（microtubule dynamic instability），即微管末端在聚合与解聚间随机切换。体外（in vitro）实验显示：当微管蛋白（tubulin）浓度高于临界浓度、pH6.9、有Mg²⁺、GTP及37℃时，αβ-tubulin异二聚体聚合成聚合态微管；而tubulin低于临界浓度、有Ca²⁺或0℃低温时微管解聚。原文还提到在活细胞中直接观察到了微管的动态不稳定性。这是本章核心考点。","page":12,"level":"掌握","img":"assets/img/ch06/p012.jpg","anim":null,"fig":null,"points":["体外聚合：tubulin>临界浓度、pH6.9、Mg²⁺、37℃、GTP","体外解聚：tubulin<临界浓度、Ca²⁺、0℃低温","临界浓度=聚合与解聚达动态平衡的最低游离tubulin浓度"],"check":{"q":"关于微管的动态不稳定性，下列叙述正确的是？","o":["A. 微管一旦聚合就不再解聚，长度固定","B. 低温可促进微管聚合","C. 微管末端在生长与缩短间随机切换","D. 临界浓度是微管蛋白浓度无上限的指标"],"a":"C","e":"微管末端在聚合（生长）与解聚（缩短）之间随机切换即为动态不稳定性；聚合需高于临界浓度及pH6.9、Mg²⁺、37℃、GTP等条件。","oe":["微管可解聚，如低浓度、Ca²⁺或0℃时。","0℃低温促微管解聚而非聚合，故错误。","正确，末端在生长与缩短间随机切换。","临界浓度是聚合解聚平衡所需最低浓度。"]},"cards":null,"mem":"动态不稳定：Mg²⁺37℃GTP聚合，Ca²⁺/0℃解聚","big":"assets/img/ch06/big/p012.jpg","summary":"体外实验：游离 tubulin（αβ 异二聚体）浓度高于临界浓度、并满足 pH6.9、Mg²⁺、37℃、GTP 供能时，聚合为微管；低于临界浓度，且有 Ca²⁺ 或 0℃ 低温时，","goal":"学完应能掌握并运用「微管的动态不稳定性 (Microtubule dynamic instabili」的核心内容，能解释其机制、比较相关概念。","intuition":"微管末端像“喝醉的跑步机”：一会儿加亚基猛长，一会儿又解聚骤缩、随机切换，这就是动态不稳定性。它让细胞能快速“搜索—捕获”目标（如染色体），需要时几秒内重建或拆掉整条轨道。临界浓度是“盈亏平衡点”：高于它净聚合，低于它净解聚。","derive":"【临界浓度的由来】设正端聚合速率 = kon·[tubulin]、解聚速率 = koff。当两端净速率为 0 时达到动态平衡，此时的游离 tubulin 浓度即为临界浓度 Cc：Cc = koff / kon。高于 Cc 净聚合、低于 Cc 净解聚——这是微管/微丝装配的共同规律。"},{"i":12,"sec":"1.1 微管(microtubule, ","title":"●脚踏车运动 (Microtubule treadmilling)","notes":"【结合课本/笔记】微管相关蛋白是一类可与微管结合并与微管蛋白共同组成微管系统的蛋白，主要功能是调节微管的特异性并将微管连接到特异性的细胞器上。踏车现象：微管蛋白、GTP 浓度达到一定浓度时，在正端结合上去的微管蛋白与负端释放出来的速度相同时，出现的现象。微管组织中心(microtubule organizing center, MTOC)：微管在生理状态或实验处理解聚后重新装配的发生处。功能（功能控制位点）：在细胞质微管装配过程的成核步骤起重要作用(提供核心，两种作用)。如中心体、有丝分裂纺锤体极、基体微管的功能：1 支架作用 2 细胞内运输 3 鞭毛、纤毛运动 4.有丝分裂 5. 物质运输微丝（microvilli、contractile bund\n\n【本页英文讲解】\n本页介绍微管的脚踏车运动（microtubule treadmilling）。它指在同一根微管上，一端不断添加tubulin亚基而另一端不断脱落，整体长度不变但亚基像踏车一样从一端“流向”另一端。这是微管动态性的一种表现形式，与动态不稳定性（dynamic instability）相区别。考研中常以名词解释或与动态不稳定性对比的形式考查，注意区分二者定义与末端行为差异。","page":13,"level":"掌握","img":"assets/img/ch06/p013.jpg","anim":"mt_treadmilling","fig":null,"points":["微管踏车运动：正端聚合、负端解聚，速度相等时长度不变"],"check":{"q":"微管的脚踏车运动（treadmilling）指的是？","o":["A. 微管在生长与缩短间随机切换","B. 正端添加与负端释放微管蛋白的速度相同，整体长度不变","C. 微管两端同时快速解聚，长度迅速缩短","D. 微管蛋白在管内沿轴向快速滑动"],"a":"B","e":"脚踏车运动指在同一根微管上正端不断添加tubulin、负端不断释放，当二者速度相同时整体长度不变，亚基像踏车般从一端“流向”另一端。","oe":["生长与缩短随机切换是动态不稳定性。","正确，正端添加与负端释放速度相同、长度不变。","两端同时解聚会使微管消失，非踏车运动。","踏车是端部加与减而非轴向滑动，故错误。"]},"cards":null,"mem":"踏车：正端加、负端减，速度相同长度不变","big":"assets/img/ch06/big/p013.jpg","terms":[{"t":"脚踏车运动","en":"treadmilling","d":"微管正端不断聚合、负端不断解聚，整体长度不变的现象。"},{"t":"动态不稳定性","en":"dynamic instability","d":"微管末端在生长与快速解聚之间随机切换的行为。"}],"summary":"微管相关蛋白是一类可与微管结合并与微管蛋白共同组成微管系统的蛋白，主要功能是调节微管的特异性并将微管连接到特异性的细胞器上","goal":"学完应能掌握并运用「●脚踏车运动 (Microtubule treadmilling)」的核心内容，能解释其机制、比较相关概念。","intuition":"踏车像“传送带原地跑”：正端不断有人在加、负端不断有人在减，两端速度相等时整条微管长度不变，但分子却像流水一样从正端流入、负端流出。于是微管看似静止，物质却在定向移动。"},{"i":13,"sec":"1.1 微管(microtubule, ","title":"微管(microtubule) ● 微管蛋白(α,β-tubulin)","notes":"GTP/α,β-tubulin   GDP/α,β-tubulin    解聚\nGTP水解发生在聚合之后。\n微丝、微管的聚合、解聚都是在端部进行的。\n【结合课本/笔记】（三）、细胞骨架、细胞核（3 个英文选择）细胞骨架定义：指真核细胞中的蛋白纤维交织而成的立体网络体系，是细胞的重要组成部分。广义：膜骨架、细胞质骨架、核纤层、核骨架、细胞外基质，构成细胞内外的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维","page":14,"level":"掌握","img":"assets/img/ch06/p014.jpg","anim":null,"fig":null,"points":["α,β-微管蛋白结合GTP/GDP，GTP水解发生在聚合之后","微丝与微管的聚合、解聚都在端部进行"],"check":{"q":"关于微管蛋白与GTP的关系，正确的是？","o":["A. 微管蛋白结合ATP，水解发生在聚合之前","B. GTP水解发生在微管解聚之后","C. α、β微管蛋白不结合任何核苷酸","D. 微管蛋白结合GTP，GTP水解发生在聚合之后"],"a":"D","e":"微管蛋白（α、β-tubulin）结合GTP，可水解为GDP；GTP水解发生在聚合之后，微丝、微管的聚合解聚都在端部进行。","oe":["微管蛋白结合GTP而非ATP，故错误。","GTP水解发生在聚合之后而非解聚之后。","α、β微管蛋白均结合GTP，故错误。","正确，结合GTP且水解发生在聚合之后。"]},"cards":null,"mem":"微管聚合后水解GTP；聚合解聚均在端部","big":"assets/img/ch06/big/p014.jpg","summary":"GTP水解发生在聚合之后","goal":"学完应能掌握并运用「微管(microtubule) ● 微管蛋白(α,β-tubulin)」的核心内容，能解释其机制、比较相关概念。","intuition":"微管蛋白二聚体头尾相接形成极性：正极加得快、负极加得慢，GTP 水解在聚合之后。"},{"i":14,"sec":"1.1 微管(microtubule, ","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\nE-site（可交换位点，位于 β-tubulin）\nN-site（不可交换位点，位于 α-tubulin）\nα-tubulin（α-微管蛋白）\nβ-tubulin（β-微管蛋白）\nGTP（三磷酸鸟苷，结合/供能）\nGDP（二磷酸鸟苷，GTP 水解产物）\nGTP cap（GTP 帽，维持正端稳定、继续聚合）\nGTP hydrolysis（GTP 水解→GDP，促解聚）\nGTP-contacting region（GTP 接触区，二聚体界面）\nPlus end of a MT（微管正端 (+) 端）\nprotofilament（原纤维，约 13 条围成中空微管）\n【读图讲解】\n模式图示微管正端 GTP 帽：α/β-微管蛋白异二聚体，β-tubulin 具 E-site/N-site，GTP 结合于二聚体界面，聚合后水解为 GDP。考点：GTP 帽维持正端稳定；GDP 化导致解聚，是动态不稳定性的分子基础。","page":15,"level":"掌握","img":"assets/img/ch06/p015.jpg","anim":null,"fig":null,"points":["E-site","GTP","N-site","β-tubulin","GTP-","GTP","a-tubulin","contacting"],"check":{"q":"关于微管正端的GTP帽，下列叙述正确的是？","o":["A. GTP帽维持正端稳定、促进继续聚合；GTP水解为GDP促解聚","B. GDP帽维持正端稳定，GTP水解促进聚合","C. E-site位于α-tubulin，N-site位于β-tubulin","D. GTP帽与微管动态性无关"],"a":"A","e":"GTP帽维持微管正端稳定、利于继续聚合，GTP水解为GDP则促进解聚，是动态不稳定性的分子基础；E-site位于β-tubulin，N-site位于α-tubulin。","oe":["正确，GTP帽稳定正端促聚合，GDP化促解聚。","维持稳定的是GTP帽，且GTP水解促解聚。","E-site在β、N-site在α，选项定位颠倒。","GTP帽是动态不稳定性的分子基础，故错误。"]},"cards":null,"mem":"GTP帽稳正端；GDP化促解聚","big":"assets/img/ch06/big/p015.jpg","summary":"N-site（不可交换位点，位于 α-tubulin）","goal":"学完应能掌握并运用「（本页为图片/无文字层）」的核心内容，能解释其机制、比较相关概念。","intuition":"本页以图展示微管蛋白二聚体与极性。"},{"i":15,"sec":"1.1 微管(microtubule, ","title":"微管动态不稳定性——GTP帽理论","notes":"微管两端结合GTP。当微管末端为GTP-α,β-tubulin时，形成“GTP帽”，微管处于聚合生长状态，GTP帽对微管起稳定作用。当聚合速率小于GTP水解速率时，末端的GTP被水解为GDP，“GTP帽”丢失、变为“GDP帽”，微管趋于解聚。微丝的动态特性有类似的“ATP帽”理论。","page":16,"level":"掌握","img":"assets/img/ch06/p016.jpg","anim":"mt_dynamic_instability","fig":null,"points":["两端是GTP-α,β-tubulin时，即形成所谓的微管GTP帽","当聚合速率小于核苷酸水解速率时，两端的GTP帽会"],"check":{"q":"关于微管GTP帽理论，下列叙述正确的是？","o":["A. 聚合速率大于核苷酸水解速率时微管立即解聚","B. 微管稳定性与GTP/GDP状态无关","C. GDP帽维持微管稳定并促进聚合","D. 两端为GTP-α,β-tubulin时形成GTP帽，微管继续组装"],"a":"D","e":"两端为GTP-微管蛋白时形成GTP帽，维持聚合生长；聚合速率小于水解速率致GTP帽丢失，微管趋于解聚。","oe":["聚合速率大于水解速率时GTP帽维持，微管生长。","微管稳定性取决于两端GTP/GDP状态。","GDP帽使微管趋于解聚，而非稳定。","两端为GTP-微管蛋白时形成GTP帽，微管继续组装。"]},"cards":null,"mem":"GTP帽稳定微管；丢失成GDP帽则趋于解聚","big":"assets/img/ch06/big/p016.jpg","summary":"当微管末端为GTP-α,β-tubulin时，形成“GTP帽”，微管处于聚合生长状态，GTP帽对微管起稳定作用","goal":"学完应能掌握并运用「微管动态不稳定性——GTP帽理论」的核心内容，能解释其机制、比较相关概念。","intuition":"微管像“一会儿长一会儿缩的轨道”：末端在生长与骤缩间随机切换，靠 GTP 帽稳定。"},{"i":16,"sec":"1.1 微管(microtubule, ","title":"Prebleach             漂白","notes":"The study of cytoskeleton using FRAP\nGFP-tubulin\n漂白后300秒              漂白后500秒\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 一、微管 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 细胞骨架（cytoskeleton）：是细胞内蛋白质成分组成的一个复合网架系统，包括微管、微丝和中间丝。\n\n【本页英文讲解】\n本页展示用荧光漂白恢复技术（fluorescence recovery after photobleaching, FRAP）研究细胞骨架。实验用绿色荧光蛋白标记的微管蛋白（GFP-tubulin），先对局部区域漂白（prebleach/漂白），再在不同时间（漂白后300秒、500秒）观察荧光恢复。荧光恢复说明漂白区外的tubulin亚基不断进入并掺入微管，证明微管处于动态更新之中。FRAP是研究骨架动态性的经典方法，需掌握其原理。","page":17,"level":"掌握","img":"assets/img/ch06/p017.jpg","anim":null,"fig":null,"points":["FRAP(荧光漂白恢复)用GFP-tubulin研究微管动态","漂白区荧光恢复说明微管亚基在动态交换"],"check":{"q":"用FRAP研究细胞骨架时，漂白区荧光恢复说明？","o":["A. 微管是静态结构，荧光不会恢复","B. 荧光恢复是因为GFP自身发光","C. 荧光恢复与微管组装无关","D. 漂白区外的tubulin亚基不断进入并掺入微管，说明微管处于动态更新"],"a":"D","e":"FRAP实验中GFP-tubulin标记微管，漂白后荧光恢复说明漂白区外的tubulin亚基不断进入并掺入微管，证明微管处于动态更新之中。","oe":["荧光可恢复，说明微管是动态而非静态。","荧光来自GFP标记而非GFP自发发光，故错误。","荧光恢复正是微管组装更新的证据。","正确，荧光恢复反映tubulin掺入、微管动态更新。"]},"cards":null,"mem":"FRAP+GFP-tubulin：荧光恢复证微管动态更新","big":"assets/img/ch06/big/p017.jpg","terms":[{"t":"GFP-tubulin","en":"GFP-tubulin","d":"用绿色荧光蛋白标记的微管蛋白，用于在活细胞中观察微管动态。"}],"summary":"漂白后300秒              漂白后500秒","goal":"学完应能掌握并运用「Prebleach             漂白」的核心内容，能解释其机制、比较相关概念。","intuition":"FRAP 像“漂白一小段看荧光多久补回”：用来测微管的动态交换速度。"},{"i":17,"sec":"1.1 微管(microtubule, ","title":"Microtubule","notes":"dynamics in\nliving cells\nThe cultured fibroblast was injected with a small volume of\ntubulin-biotin (fluorescent anti-biotin antibodies.)\nApproximately 1min following injection, the cell was fixed.\n→during periods as short as 1min, tubulin subunits are widely\nincorporated at the growing ends of cytoskeletal microtubules.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 一、微管 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 微管在生理状态或实验处理解聚后重新装配的发生处称为微管组织中心(microtubule organizingcenter, MTOC)。常见微管组织中心◆间期细胞MTOC：●      中心体(动态微管)\n\n【本页英文讲解】\n本页讲活细胞内微管的动态（dynamics in living cells）。实验向培养的成纤维细胞（fibroblast）注射少量生物素标记的微管蛋白（tubulin-biotin），再用荧光抗生物素抗体检测，注射约1分钟后固定细胞。结果显示，短短1分钟内tubulin亚基已广泛掺入到细胞骨架微管的生长端（growing ends）。这直接证明了微管在活细胞中快速、持续地组装与更新，是动态性的有力证据。","page":18,"level":"掌握","img":"assets/img/ch06/p018.jpg","anim":null,"fig":null,"points":["向培养成纤维细胞注射生物素标记的微管蛋白，约1min后固定","可观察到标记微管蛋白掺入微管生长端"],"check":{"q":"向培养成纤维细胞注射生物素标记的微管蛋白，约1分钟后固定，结果说明？","o":["A. 微管在1分钟内无组装活动","B. 注射的tubulin仅停留于细胞质不进入微管","C. 微管组装只发生在细胞核内","D. tubulin亚基在短时间内广泛掺入微管的生长端，微管快速更新"],"a":"D","e":"注射tubulin-biotin约1分钟后固定观察，可见短短1分钟内tubulin亚基已广泛掺入细胞骨架微管的生长端，证明活细胞中微管快速、持续地组装与更新。","oe":["结果恰显示1分钟内即有广泛掺入，故错误。","注射的tubulin掺入微管生长端，故错误。","微管组装在细胞质中进行，非核内。","正确，短时间即广泛掺入生长端，微管快速更新。"]},"cards":null,"mem":"注射tubulin-biotin 1min即掺入微管生长端","big":"assets/img/ch06/big/p018.jpg","summary":"考点：第一节 微管 · 一、微管 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「Microtubule」的核心内容，能解释其机制、比较相关概念。","intuition":"活细胞内微管像“不断翻新的脚手架”：注射标记 tubulin 可见微管持续生长与解聚。"}],"mcq":[{"id":"ch06_mcq_2","mod":"一、微管","modI":2,"q":"具有稳定微管的结构特异性药物是（            ）。","o":["A．秋水仙素","B．细胞松弛素","C．鬼笔环肽","D．紫杉酚"],"a":"D","e":"紫杉酚能促进微管的装配，并使已形成的微管稳定，但这种稳定性的增加对细胞是 有害的。","kp":"ch06_s2_15","oe":["错误。秋水仙素抑制微管聚合，是解聚剂而非稳定剂。","错误。细胞松弛素破坏微丝，不是微管的稳定药物。","错误。鬼笔环肽稳定微丝，与微管无关。","正确。紫杉酚促进微管装配并使已形成的微管稳定。"]},{"id":"ch06_mcq_3","mod":"一、微管","modI":2,"q":"微管蛋白在一定条件下，能装配成微管，其管壁由几根原纤维构成？（           ）","o":["A．9","B．11","C．13","D．15"],"a":"C","e":"在微管装配的过程中，αβ二聚体形成后，再形成原纤维（protofilament），经过侧 面增加而扩展为片层，至 13 根原纤维时，即合拢形成一段微管。","kp":"ch06_s2_13","oe":["错误。9不是微管管壁原纤维数，9为纤毛二联体等结构数目。","错误。11不是微管管壁的原纤维数目。","正确。13根原纤维合拢形成微管，构成其管壁。","错误。15不是微管管壁的原纤维数目。"]},{"id":"ch06_mcq_7","mod":"一、微管","modI":2,"q":"微管蛋白的异二聚体上具有哪种核苷酸的结合位点？（             ）","o":["A．GDP","B．ADP","C．GTP","D．ATP"],"a":"C","e":"在α/β-微管蛋白二聚体中，α-微管蛋白上有一个 GTP 结合位点，结合在该位点上的 GTP 通常不会被水解，被称为不可交换位点；β-微管蛋白上也有一个 GTP 结合位点，该 GTP 在微管蛋白二聚体参与组装成微管后即被水解成 GDP，因此β-微管蛋白上的 GTP 结合位点 是可交换位点。","kp":"ch06_s2_6","oe":["GDP是β亚基GTP水解后的产物，并非微管蛋白结合位点直接结合的核苷酸。","ADP是腺嘌呤核苷酸，微管蛋白上不存在ADP的结合位点。","正确——α、β微管蛋白各有一个GTP结合位点，故异二聚体含GTP位点。","ATP是肌动蛋白结合的核苷酸，微管蛋白不结合ATP。"]}],"judge":[{"id":"ch06_judge_9","modI":2,"q":"中心粒和基体均不具有自我复制性质。（                       ）","a":"错","e":"中心体与基体都有自我复制能力，新的中心粒是由原来的中心粒在 S 期复制而来， 而基体则可由中心体衍生而来。","kp":"ch06_s2_8","oe":["若判对则误认为二者无复制能力，实则中心粒和基体均可自我复制。","中心粒和基体均有自我复制能力，中心粒于S期复制，基体可由中心体衍生。"]}],"fill":[{"id":"ch06_fill_1","modI":2,"q":"组成细肌丝主要的三种蛋白质是：______、______、______。组成粗肌丝的主要蛋白成 分是：______。构成微管的蛋白有两类：______和______。","a":"肌动蛋白；原肌球蛋白；肌钙蛋白；肌球蛋白；α-微管蛋白；β-微管蛋白","kp":"ch06_s2_13","oe":["细肌丝主要由肌动蛋白构成，是肌肉收缩的重要成分。","原肌球蛋白沿肌动蛋白螺旋排列，属细肌丝的调节蛋白。","肌钙蛋白结合原肌球蛋白并感受Ca2+，属细肌丝调节蛋白。","粗肌丝的主要成分是肌球蛋白，其头部具ATP酶活性。","微管由α和β微管蛋白异二聚体组装，α为其中一亚基。","β微管蛋白是微管蛋白异二聚体的另一亚基，故为答案。"]},{"id":"ch06_fill_4","modI":2,"q":"细胞质骨架包括______、______和______。","a":"微丝；微管；中间丝","kp":"ch06_s2_13","oe":["微丝由肌动蛋白构成，参与细胞运动与收缩，是骨架之一。","微管由微管蛋白构成，参与支持、运输和纺锤体形成。","中间丝由中间丝蛋白构成，为细胞提供机械强度。"]},{"id":"ch06_fill_14","modI":2,"q":"组成细肌丝主要的三种蛋白质是：______、______、______。组成粗肌丝的主要蛋白质 成分是：______ 。构成微管的蛋白有两类：______和 ______。","a":"肌动蛋白；原肌球蛋白；肌钙蛋白；肌球蛋白；α微管蛋白；β微管蛋白","kp":"ch06_s2_13","oe":["细肌丝主体，由球形肌动蛋白单体聚合成的双螺旋纤维。","缠绕于肌动蛋白双螺旋沟中的长条状调节蛋白。","结合在原肌球蛋白上的调节蛋白，可结合钙离子触发收缩。","粗肌丝的主要成分，头部具ATP酶活性，属分子马达。","微管蛋白异二聚体的一类亚基，与β亚基组成基本单元。","与α微管蛋白组成异二聚体，其GTP水解与微管动态相关。"]},{"id":"ch06_fill_15","modI":2,"q":"细胞内具有分子马达（引擎蛋白）作用的蛋白分子有______、______、______、______ 等。","a":"肌球蛋白；动力蛋白；驱动蛋白；ATP 合成酶","kp":"ch06_s2_10","oe":["沿微丝运动，参与肌肉收缩和胞质分裂。","沿微管向负极运动，介导轴突逆行运输和纤毛摆动。","沿微管向正极运动，介导轴突顺行运输和纺锤体形成。","利用质子梯度旋转合成ATP，具有旋转分子马达特性。"]}],"short":[{"id":"ch06_short_3","modI":2,"q":"叙述什么是微管的 GTP 帽和 GDP 帽，其对微管的动态性质有什么影响。","a":"微管的 GTP 或 GDP 帽就是微管正端αβ微管蛋白二聚体结合 GTP 或 GDP 的状态。 （1）如果微管正端结合的是由结合 GTP 的微管蛋白二聚体组成的 GTP 帽结构，微管就趋 于生长； （2）如果微管的正端结合的是由结合 GDP 的微管蛋白二聚体组成的 GDP 帽结构，这种微 管就趋于缩短。 决定微管正端是 GTP 帽还是 GDP 帽，又受两种因素影响：一是结合 GTP 的游离微管蛋白 二聚体的浓度；二是 GTP 帽中 GTP 水解的速度。当（＋）端形成 GTP 帽，而游离微管蛋 白二聚体的浓度又很高时，微管趋向于生长。由于结合 GTP 的游离微管蛋白二聚体的浓度 降低，使得微管延长的速度下降，随着 GTP 水解的不断进行最后 GTP 帽结构转变成 GDP， 逐渐使微管变得不稳定，趋于解聚。细胞内微管的这两种状态是不断发生的，因为细胞内不 断有微管解聚，又不断地有新微管的组装。","kp":"ch06_s2_15"},{"id":"ch06_short_5","modI":2,"q":"比较胞质骨架三种组分。","a":"胞质骨架三种组分比较如下： 表 10-1","kp":"ch06_s2_13"}],"calc":[{"id":"ch06_calc_3","modI":2,"q":"动态不稳定性造成微管迅速伸长或缩短。设想一条单一的处于缩短状态的微管： （1）如果要停止缩短并进入伸长状态，其末端必须发生什么变化？ （2）发生这一转换后微管蛋白的浓度有什么变化？ （3）如果溶液中只有 GDP 而没有 GTP，将会发生什么情况？ （4）如果溶液中存在不能被水解的 GTP 类似物，将会发生什么情况？","a":"（1）由于失去了 GTP 帽，即末端的微管蛋白亚基都以结合 GDP 的形式存在，微管因 而缩短。溶液中带有 GTP 的微管蛋白亚基仍会添加到末端，但是寿命很短，因为 GTP 可能 被水解，或者围绕着的微管解体使其脱落下来。但是如果足够的带有 GTP 的亚基以足够快 的速度添加上去并覆盖了微管末端带有 GDP 的微管蛋白亚基，   这时可产生一个新的 GTP 帽， 微管就可重新开始生长。 （2）当微管蛋白浓度较高时，GTP 亚基的添加速率会比较高，因而缩短微管转变为增长微 管的频率也会随微管蛋白浓度的升高而增加。这种调节机制使该系统达到自主平衡：较多微 管的缩短可造成高浓度的游离微管蛋白，转为增长的微管也就增多；反之，增长的微管多了， 游离微管蛋白浓度下降从而 GTP-亚基的添加速率也下降，在某些部位 GTP 水解的速率会超 过添加速率，造成 GTP 帽破坏，微管又开始进入缩短状态。 （3）如果只有 GDP 存在，微管会持续短缩，并最终消失，因为结合有 GDP 的微管蛋白二 聚体之间的亲和力十分低，不可能被稳定地添加到微管上。 （4）如果有 GTP 存在但不能被水解，那么微管将持续增长，直到所有游离的微管蛋白亚基 被消耗完为止。","kp":"ch06_s2_15"}],"term":[{"id":"ch06_term_4","modI":2,"term":"微管蛋白流（tubulin flow）。","def":"微管踏车学说认为微管组装过程中，在 GTP、 Mg2 等条件下，微管蛋白异二聚体不断 ＋   地在微管正极端聚合使微管延长，而微管的负极端则因微管蛋白的解聚缩短。微管蛋白从负 极端解聚下来，又到正极端聚合的流动称为微管蛋白流，但 GTP 不存在时，微管蛋白流就 不会发生。","kps":"","kp":"ch06_s2_6"},{"id":"ch06_term_5","modI":2,"term":"微管相关蛋白（MAP）","def":"微管相关蛋白（MAP）即微管结合蛋白，是指一些与微管密切联系，附着于微管多聚 体上，参与微管装配并能增加微管稳定性的蛋白，包括 MAP1，MAP2，MAP3，tau 蛋白等。 微管相关蛋白多分布于神经元的树突和轴突中，一般认为与骨架纤维间的连接有关，可能决 定了轴突和树突的不同形态。","kps":"","kp":"ch06_s2_10"}]},{"i":3,"name":"第一节 微管 · 1.2 微管极性:","slides":[{"i":18,"sec":"1.2 微管极性:","title":"1.2 微管极性:","notes":"●αβ→αβ→αβ重复排列, 头尾相接, 构成微管\n结构上的极性；\n●组装、生长速度：两个末端在结构上不是\n等同的→ tubulin二聚体加上/释放优先在微管\n的一端进行，称正极(MT assembly and\ndisassembly occur preferentially at the + end),\n通常正极的聚合速率(the rate of\npolymerization)比负极快。\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.2 微管极性: ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体","page":19,"level":"掌握","img":"assets/img/ch06/p019.jpg","anim":"mt_polarity","fig":null,"points":["αβ二聚体头尾相接排列，微管结构上有极性","二聚体优先在正极组装，正极聚合速率比负极快"],"check":{"q":"关于微管的极性，下列叙述正确的是？","o":["A. αβ二聚体头对头相接，两端完全等同","B. αβ二聚体头尾相接构成结构极性，正极聚合速率通常比负极快","C. 负极聚合速率比正极快","D. 微管无极性，两端聚合速率相同"],"a":"B","e":"αβ二聚体头尾相接重复排列构成微管的结构极性；tubulin二聚体加上与释放优先在正端进行，通常正极的聚合速率比负极快。","oe":["二聚体头尾相接而非头对头，两端不等同。","正确，头尾相接构成极性，正极聚合更快。","通常正极聚合速率比负极快，故错误。","微管有极性，两端聚合速率不同。"]},"cards":null,"mem":"微管有极性，正极聚合快于负极","big":"assets/img/ch06/big/p019.jpg","summary":"αβ→αβ→αβ重复排列, 头尾相接, 构成微管","goal":"学完应能掌握并运用「1.2 微管极性:」的核心内容，能解释其机制、比较相关概念。","intuition":"微管像“有方向的轨道”：极性决定生长端和锚定端，马达蛋白据此认方向。"},{"i":19,"sec":"1.2 微管极性:","title":"Microtubules grow","notes":"preferentially at the\n(+) end\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.2 微管极性: ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 微管在生理状态或实验处理解聚后重新装配的发生处称为微管组织中心(microtubule organizingcenter, MTOC)。常见微管组织中心◆间期细胞MTOC：●      中心体(动态微管)\n\n【本页英文讲解】\n本页指出微管（microtubules）主要在正端（plus end, (+) end）优先生长，即tubulin亚基更倾向于加到微管的正端，使微管沿正极方向延伸。由于微管具有极性，正端动力学更活跃（聚合解聚都快），负端相对稳定并常锚定在微管组织中心（MTOC）。这一极性是马达蛋白定向运输和纺锤体组装的基础，属于高频考点。","page":20,"level":"掌握","img":"assets/img/ch06/p020.jpg","anim":null,"fig":null,"points":["微管优先在正极(+)端生长","负端通常锚定在微管组织中心"],"check":{"q":"微管生长的主要特点及负端状态是？","o":["A. tubulin亚基优先加到负端，正端锚定MTOC","B. tubulin亚基优先加到正端，负端相对稳定并常锚定在MTOC","C. 两端同时等速生长，无优先端","D. 正端稳定不动，负端最活跃"],"a":"B","e":"微管主要在正端（plus end）优先生长；正端动力学更活跃，负端相对稳定并常锚定在微管组织中心（MTOC）。","oe":["优先生长端是正端，锚定MTOC的是负端。","正确，亚基优先加于正端，负端锚定MTOC。","微管生长有优先端，非两端等速。","活跃的是正端，稳定锚定的是负端。"]},"cards":null,"mem":"微管优先在(+)端正向生长，负端锚MTOC","big":"assets/img/ch06/big/p020.jpg","summary":"考点：第一节 微管 · 1.2 微管极性: ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「Microtubules grow」的核心内容，能解释其机制、比较相关概念。","intuition":"微管主要在正端(+)生长，负端常锚在 MTOC、相对稳定。"}],"mcq":[],"judge":[{"id":"ch06_ajudge_2","modI":3,"q":"●αβ→αβ→αβ重复排列, 头尾相接, 构成微管","a":"对","e":"本页要点：●αβ→αβ→αβ重复排列, 头尾相接, 构成微管","kp":"ch06_s3_18","oe":["αβ微管蛋白二聚体头尾相接重复排列，构成微管的原纤维。","误判为错者或不知微管由αβ二聚体头尾相接重复排列而成。"]}],"fill":[],"short":[],"calc":[],"term":[]},{"i":4,"name":"第一节 微管 · 1.3 MTOC and orienta","slides":[{"i":20,"sec":"1.3 MTOC and orienta","title":"微管组织中心(MTOC):存在于细胞中决定微管","notes":"1.3 MTOC and orientation of cellular MTs\n在生理状态或实验处理 解聚后，重新装配的结\n构称~。\nMTOC：\n●为微管提供生长的起点\n●决定细胞内微管的方向性, 靠近MTOC的一\n端为(-)端； 远离MTOC一端的微管生长快，为\n(+)极。","page":21,"level":"掌握","img":"assets/img/ch06/p021.jpg","anim":null,"fig":null,"points":["MTOC为微管提供生长起点并决定其方向性","靠近MTOC一端为(−)端，远离一端为(+)极、生长快"],"check":{"q":"关于微管组织中心（MTOC），下列叙述正确的是？","o":["A. 靠近MTOC的一端为(+)端，远离端为(-)端","B. MTOC与微管极性无关，仅提供能量","C. 为微管提供生长起点，靠近MTOC的一端为(-)端，远离端生长快为(+)极","D. MTOC位于细胞膜上，决定微管数量"],"a":"C","e":"MTOC是微管解聚后重新装配的发生处，为微管提供生长起点并决定其方向性；靠近MTOC的一端为(-)端，远离MTOC一端的微管生长快，为(+)极。","oe":["极性颠倒，近MTOC端为(-)端。","MTOC决定微管方向性，非仅提供能量。","正确，MTOC供起点，近端(-)、远端(+)且生长快。","MTOC位置多样（如中心体），非均在细胞膜。"]},"cards":null,"mem":"MTOC供生长起点定方向：近端(-)，远端(+)快","big":"assets/img/ch06/big/p021.jpg","summary":"在生理状态或实验处理 解聚后，重新装配的结","goal":"学完应能掌握并运用「微管组织中心(MTOC):存在于细胞中决定微管」的核心内容，能解释其机制、比较相关概念。","intuition":"MTOC 像微管的“插座”：微管的负端插在这里固定，正端朝外自由生长；它决定微管从哪儿长、朝哪个方向长。动物细胞的中心体就是主要 MTOC。"},{"i":21,"sec":"1.3 MTOC and orienta","title":"微管组织中心（MTOC）","notes":"microtubule organization center\n细胞间期位于细胞核附近；有丝分裂时位于纺\n锤体的两极。\n细胞核旁/核膜？\ncentrosome\n【结合课本/笔记】肌肉收缩系统中的有关蛋白①肌球蛋白(myosin)—所有actin-dependent motor proteins都属于该家族，其头部具ATP酶活力,沿微丝从负极到正极进行运动。·Myosin Ⅱ主要分布于肌细胞，有两个球形头部结构域(具有ATPase活性)和尾部链,多个Myosin尾部相互缠绕，形成myosin filament,即粗肌丝。②原肌球蛋白(tropomyosin, Tm)由两条平行的多肽链形成α-螺旋构型,位于肌动蛋白螺旋沟内,结合于细丝, 调节肌动蛋白与肌球蛋白头部的结合。③肌钙蛋白 (Troponin, Tn)为复合物，包括三个亚基：TnC(Ca2+敏感性蛋白)能特异与Ca2+结合; TnT(与原肌球蛋白结合)","page":22,"level":"掌握","img":"assets/img/ch06/p022.jpg","anim":null,"fig":null,"points":["动物细胞中心体(Centrosome)/中心粒(Centriole)","纤毛、鞭毛的基体(basal body)","真菌细胞中的纺锤体极体","植物细胞？","微管组织中心的γ-tubulin"],"check":{"q":"关于微管组织中心(MTOC)，下列叙述正确的是？","o":["A. 间期位于核附近，分裂时位于纺锤体两极，含γ-微管蛋白","B. 只存在于植物细胞中","C. 是微丝组装的起始位点","D. 位于细胞膜外侧"],"a":"A","e":"MTOC是微管组装的起点，间期位于核附近，分裂时位于纺锤体两极，其核心成分含γ-微管蛋白。","oe":["对：与笔记MTOC位置及γ-tubulin一致","错：动物细胞普遍具有MTOC，不符合本页所学概念","错：MTOC组织微管而非微丝，不符合本页所学概念","错：MTOC位于细胞内部，不符合本页所学概念"],"basis":"间期位于细胞核附近；有丝分裂时位于纺锤体两极…γ-tubulin"},"cards":null,"mem":"MTOC：间期核旁、分裂纺锤体两极，含γ-tubulin","big":"assets/img/ch06/big/p022.jpg","terms":[{"t":"微管组织中心","en":"MTOC","d":"为微管提供生长起点、决定微管方向性的结构。"},{"t":"中心粒","en":"centriole","d":"中心体内由9组三联体微管组成的桶状结构。"}],"summary":"细胞间期位于细胞核附近；有丝分裂时位于纺","goal":"学完应能掌握并运用「微管组织中心（MTOC）」的核心内容，能解释其机制、比较相关概念。","intuition":"MTOC 像“微管插座”：为微管提供起点、决定方向，动物细胞主要 MTOC 是中心体。"},{"i":22,"sec":"1.3 MTOC and orienta","title":"中心体","notes":"纤毛、鞭毛的基体\n常见的动物细胞微管组织中心\n\n【读图讲解】\n本图归纳常见的动物细胞微管组织中心(MTOC)。左上为中心体(Centrosome)：位于核旁，微管以其为起点向四周辐射，游离端为(+)极。右上为神经元，MTOC位于细胞体，微管伸入树突与轴突(Axon)，标出(+)、(-)极性。左下为纺锤体，两极(Spindle poles)发出微管连接染色体。右下为纤毛/鞭毛，其基体(Basal body)作为组织中心。要点：各MTOC均从(-)极发生、向(+)极延伸，中心体与基体同源，掌握四类微管组织中心及极性。","page":23,"level":"掌握","img":"assets/img/ch06/p023.jpg","anim":"centrosome","fig":null,"points":["中心体与纤毛、鞭毛的基体均属常见动物细胞的微管组织中心"],"check":{"q":"下列均属于常见动物细胞微管组织中心的一组是？","o":["A. 核糖体、溶酶体、高尔基体","B. 中心体、纤毛和鞭毛的基体、纺锤体两极","C. 微丝、中间纤维、肌动蛋白","D. 线粒体、叶绿体、过氧化物酶体"],"a":"B","e":"常见的动物细胞MTOC包括中心体、纤毛与鞭毛的基体以及纺锤体两极，微管均由(-)极发生向(+)极延伸。","oe":["错：这些属细胞器而非MTOC，不符合本页所学概念","对：均为笔记所列常见MTOC，与笔记原文相符","错：三者属于细胞骨架的组成成分","错：三者属于膜性的细胞器，不符合本页所学概念"],"basis":"中心体…纤毛、鞭毛的基体…纺锤体两极"},"cards":null,"mem":"MTOC四例：中心体、神经元、纺锤体极、基体","big":"assets/img/ch06/big/p023.jpg","summary":"常见的动物细胞微管组织中心","goal":"学完应能掌握并运用「中心体」的核心内容，能解释其机制、比较相关概念。","intuition":"中心体像“微管插排”：含一对中心粒和周围基质，负责成核微管、组织纺锤体。"},{"i":23,"sec":"1.3 MTOC and orienta","title":"中心体的微管组织中心作用","notes":"【结合课本/笔记】微管相关蛋白是一类可与微管结合并与微管蛋白共同组成微管系统的蛋白，主要功能是调节微管的特异性并将微管连接到特异性的细胞器上。踏车现象：微管蛋白、GTP 浓度达到一定浓度时，在正端结合上去的微管蛋白与负端释放出来的速度相同时，出现的现象。微管组织中心(microtubule organizing center, MTOC)：微管在生理状态或实验处理解聚后重新装配的发生处。功能（功能控制位点）：在细胞质微管装配过程的成核步骤起重要作用(提供核心，两种作用)。如中心体、有丝分裂纺锤体极、基体微管的功能：1 支架作用 2 细胞内运输 3 鞭毛、纤毛运动 4.有丝分裂 5. 物质运输微丝（microvilli、contractile bund","page":24,"level":"掌握","img":"assets/img/ch06/p024.jpg","anim":null,"fig":null,"points":["MTOC在微管装配中的主要作用是成核，为微管提供组装起点"],"check":{"q":"微管组织中心（MTOC）在微管装配过程中的主要作用是？","o":["A. 在微管装配的成核步骤起重要作用，为微管提供核心","B. 直接催化微管蛋白的水解并提供ATP","C. 只起机械固定作用，与成核无关","D. 负责微管的解聚，抑制其组装"],"a":"A","e":"微管组织中心在细胞质微管装配过程的成核步骤起重要作用，为微管装配提供核心（两种作用），如中心体、有丝分裂纺锤体极、基体等。","oe":["正确，MTOC在成核步骤提供核心。","MTOC不催化tubulin水解，也非ATP来源。","MTOC主要参与成核，非仅机械固定。","MTOC促进成核组装而非抑制，故错误。"]},"cards":null,"mem":"MTOC为成核核心：中心体、纺锤极、基体","big":"assets/img/ch06/big/p024.jpg","summary":"微管相关蛋白是一类可与微管结合并与微管蛋白共同组成微管系统的蛋白，主要功能是调节微管的特异性并将微管连接到特异性的细胞器上","goal":"学完应能掌握并运用「中心体的微管组织中心作用」的核心内容，能解释其机制、比较相关概念。","intuition":"MTOC 的主要作用是“成核”——给微管一个生长起点。"},{"i":24,"sec":"1.3 MTOC and orienta","title":"植物细胞的MTOC","notes":"The same cell that has been\nMTs of a Haemanthus\nstained with an antibody\nendosperm cell during\ninterphase              against purified calf\ncentrosomes.\n【结合课本/笔记】特异的细胞周期特异的细胞周期是指那些特殊的细胞所具有的与标准的细胞周期相比有着鲜明特点的细胞周期。◆爪蟾早期胚胎细胞的细胞周期◆酵母细胞的细胞周期◆植物细胞的细胞周期◆细菌的细胞周期爪蟾早期胚胎细胞的细胞周期·细胞分裂快,无G1期, G2期非常短,S期也短(所有复制子都激活), 以至认为仅含有S期和M期·无需临时合成其它物质·子细胞在G1、G2期并不生长，越分裂体积越小·细胞周期调控因子和调节机制与一般体细胞标准的细胞周期基本是一致的\n\n【本页英文讲解】\n本页讲植物细胞的微管组织中心（microtubule organizing center, MTOC）。图中展示的是一株待宵草（Haemanthus）胚乳细胞（endosperm cell）间期（interphase）的微管，右侧同一细胞用抗纯化小牛中心体（centrosome）的抗体染色。要点是：植物细胞虽有MTOC功能，却没有动物细胞那种含中心粒的中心体，其微管组织中心较为分散。常与动物MTOC对比考查。","page":25,"level":"掌握","img":"assets/img/ch06/p025.jpg","anim":null,"fig":null,"points":["植物细胞无中心体","其微管组织中心为分散的微管成核位点"],"check":{"q":"与动物细胞相比，植物细胞的微管组织中心（MTOC）特点是？","o":["A. 具有含中心粒的典型中心体","B. 有MTOC功能，但没有动物细胞那种含中心粒的中心体，较为分散","C. 完全没有微管组织中心","D. 由鞭毛基体充当MTOC"],"a":"B","e":"植物细胞虽有微管组织中心功能，却没有动物细胞那种含中心粒的中心体，其微管组织中心较为分散。","oe":["植物细胞无含中心粒的典型中心体，故错误。","正确，有MTOC功能但无中心粒中心体且分散。","植物细胞仍有MTOC功能，非完全没有。","植物细胞无鞭毛基体充当MTOC，故错误。"]},"cards":null,"mem":"植物无中心体，MTOC分散（成膜体等）","big":"assets/img/ch06/big/p025.jpg","summary":"特异的细胞周期特异的细胞周期是指那些特殊的细胞所具有的与标准的细胞周期相比有着鲜明特点的细胞周期","goal":"学完应能掌握并运用「植物细胞的MTOC」的核心内容，能解释其机制、比较相关概念。","intuition":"植物细胞没有中心体，其微管组织中心是分散的成核位点（如成膜体）。"},{"i":25,"sec":"1.3 MTOC and orienta","title":"γ-tubulin与微管组织中心(MTOC)","notes":"γ-tubulin 与微管组织中心(MTOC)\n• 动物细胞中心体（微管组织中心）上有由 γ-tubulin 组成的诸多环状结构，每个 γ-tubulin 环都是微管生长的起点（成核部位）。\n• αβ-tubulin 二聚体以一定方向添加到环上，结果长出的微管负极埋在中心体内、正极朝外。\n【考点】γ-tubulin 通常位于 MTOC，在微管组装（成核）中有重要作用；γ-TuRC（γ-微管蛋白环复合体）成核微管并决定其极性方向。","page":26,"level":"掌握","img":"assets/img/ch06/p026.jpg","anim":"mtoc_nucleation","fig":null,"points":["中心体上有γ-tubulin组成的环状结构，是微管生长的成核部位","αβ二聚体定向添加，长出微管负端埋在中心体内、正端朝外"],"check":{"q":"关于γ-tubulin与微管组织中心，正确的是？","o":["A. γ-tubulin环使微管正极埋在中心体内","B. γ-tubulin与微管成核无关","C. γ-tubulin位于微管正极并维持其稳定","D. 中心体上有γ-tubulin环，是微管生长的成核起点，长出的微管负极在内、正极朝外"],"a":"D","e":"动物细胞中心体上有由γ-tubulin组成的环状结构，每个γ-tubulin环都是微管生长的起点（成核部位）；αβ-tubulin二聚体定向添加，长出的微管负极埋在中心体内、正极朝外。","oe":["埋在中心体内的是负极，不是正极。","γ-tubulin在微管成核中有重要作用。","γ-tubulin位于MTOC，不在微管正极。","正确，γ-tubulin环为成核起点，负内正外。"]},"cards":null,"mem":"γ-tubulin环为成核点，负端埋内正端朝外","big":"assets/img/ch06/big/p026.jpg","summary":"动物细胞中心体（微管组织中心）上有由 γ-tubulin 组成的诸多环状结构，每个 γ-tubulin 环都是微管生长的起点（成核部位）","goal":"学完应能掌握并运用「γ-tubulin与微管组织中心(MTOC)」的核心内容，能解释其机制、比较相关概念。","intuition":"γ-tubulin 环像“成核模具”：微管由此长出，负端埋在中心体内、正端朝外。","experiment":"【体外实验】用含 γ-tubulin 的中心体/γ-TuRC 在体外加入 tubulin 与 GTP，可见微管从 γ-tubulin 环处成核生长——证明 MTOC 的成核作用。"},{"i":26,"sec":"1.3 MTOC and orienta","title":"微管由含γ-tubulin的复合体成核","notes":"γ-tubulin, and MT was extended from γ-tubulin of\nMTOC\nThe centrosome is the major MTOC of animal cells\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.3 MTOC and orienta ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页说明微管（MT）由含有γ-微管蛋白（γ-tubulin）的蛋白复合物成核（nucleated），微管从微管组织中心（MTOC）中的γ-tubulin处延伸生长。中心体（centrosome）是动物细胞最主要的MTOC。核心机制是γ-tubulin作为成核核心，决定微管的数量、极性及成核位置。γ-tubulin环状复合物如何启动微管装配，是本章重要考点。","page":27,"level":"掌握","img":"assets/img/ch06/p027.jpg","anim":null,"fig":null,"points":["微管由含γ-tubulin的蛋白复合体成核","中心体是动物细胞的主要微管组织中心"],"check":{"q":"动物细胞中微管的成核及主要MTOC是？","o":["A. 由α-tubulin独立成核，无MTOC参与","B. 由肌动蛋白复合物成核，基体是主要MTOC","C. 由中间纤维成核，纺锤体是主要MTOC","D. 由含γ-tubulin的蛋白复合物成核，中心体是主要MTOC"],"a":"D","e":"微管由含有γ-tubulin的蛋白复合物成核，从MTOC中的γ-tubulin处延伸生长；中心体是动物细胞最主要的MTOC。","oe":["成核依赖γ-tubulin及MTOC，非α-tubulin独立。","成核因子是γ-tubulin，非肌动蛋白。","成核核心是γ-tubulin，非中间纤维。","正确，γ-tubulin复合物成核，中心体为主要MTOC。"]},"cards":null,"mem":"γ-tubulin成核微管，中心体是动物主MTOC","big":"assets/img/ch06/big/p027.jpg","summary":"考点：第一节 微管 · 1.3 MTOC and orienta ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「微管由含γ-tubulin的复合体成核」的核心内容，能解释其机制、比较相关概念。","intuition":"微管由含 γ-tubulin 的复合体成核；中心体是动物细胞主要 MTOC。"},{"i":27,"sec":"1.3 MTOC and orienta","title":"New MTs are nucleated at the sites of γ-tubulin","notes":"present on the surface of an existing microtubule.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.3 MTOC and orienta ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页讲新的微管（MTs）可在已有微管表面的γ-微管蛋白（γ-tubulin）位点处成核（nucleated）。也就是说，除了中心体，细胞中小型成核位点可依附于现有微管，从γ-tubulin处发出新的微管，形成分支式的微管网络。这解释了植物细胞等缺乏典型中心体的细胞如何生成微管，也体现了γ-tubulin作为通用成核因子的作用。","page":28,"level":"掌握","img":"assets/img/ch06/p028.jpg","anim":null,"fig":null,"points":["新微管在γ-tubulin位点成核","也可在已有微管表面成核"],"check":{"q":"关于新的微管成核位点，下列叙述正确的是？","o":["A. 新微管只能在中心体内成核，别无他处","B. 新微管成核不依赖γ-tubulin","C. 新微管可在已有微管表面的γ-tubulin位点处成核，形成分支式网络","D. 新微管由高尔基体直接成核"],"a":"C","e":"新微管可在已有微管表面的γ-tubulin位点处成核，从γ-tubulin处发出新的微管形成分支式网络，这解释了缺乏典型中心体的细胞如何生成微管。","oe":["除中心体外，已有微管表面也可成核。","该成核依赖γ-tubulin作为通用成核因子。","正确，可在已有微管表面γ-tubulin处成核分支。","新微管从γ-tubulin处成核，与高尔基体无关。"]},"cards":null,"mem":"新微管在旧管γ位点成核分支","big":"assets/img/ch06/big/p028.jpg","summary":"考点：第一节 微管 · 1.3 MTOC and orienta ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「New MTs are nucleated at the sites of γ-」的核心内容，能解释其机制、比较相关概念。","intuition":"新微管在 γ-tubulin 位点成核，也可在已有微管表面成核。"},{"i":28,"sec":"1.3 MTOC and orienta","title":"γ-tubulin ring complex (from J.M.Kollman et al. Nature 2010)","notes":"(a) two copies of γ-tubulin associate a pair of accessory proteins\nto form the γ-tubulin small complex(γ-TuSC).\n(b) 7 copies of the γ-TuSC form a spiral structure\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.3 MTOC and orienta ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 微管在生理状态或实验处理解聚后重新装配的发生处称为微管组织中心(microtubule organizingcenter, MTOC)。常见微管组织中心◆间期细胞MTOC：●      中心体(动态微管)\n\n【本页英文讲解】\n本页介绍γ-微管蛋白环状复合物（γ-tubulin ring complex, γ-TuRC），图像取自Kollman等2010年发表在《Nature》上的研究。图中说明：两个γ-tubulin拷贝与一对辅助蛋白（accessory proteins）结合，形成γ-微管蛋白小复合物（γ-tubulin small complex, γ-TuSC）；再由7个γ-TuSC形成一个螺旋状结构（spiral structure），即γ-TuRC。它模拟微管正端的构型，为微管成核提供模板。","page":29,"level":"掌握","img":"assets/img/ch06/p029.jpg","anim":null,"fig":null,"points":["2个γ-tubulin与一对附属蛋白形成γ-微管蛋白小复合物(γ-TuSC)","7个γ-TuSC形成螺旋结构，即γ-微管蛋白环状复合物(γ-TuRC)"],"check":{"q":"关于γ-微管蛋白环状复合物(γ-TuRC)的组成，下列叙述正确的是？","o":["A. 7个γ-tubulin单体直接围成单环，不含任何辅助蛋白","B. 两个γ-tubulin与一对辅助蛋白结合成γ-TuSC，7个γ-TuSC螺旋排列构成γ-TuRC","C. 13个α/β-tubulin异二聚体首尾相连构成γ-TuRC","D. 2个γ-TuSC与1个中心体蛋白组成，共含14个γ-tubulin"],"a":"B","e":"γ-TuRC由γ-TuSC组装而成：2个γ-tubulin与辅助蛋白组成1个γ-TuSC，7个γ-TuSC螺旋排列构成γ-TuRC，作为微管成核模板。","oe":["忽略了辅助蛋白及γ-TuSC的成对结构。","与图示一致，γ-TuSC组装成螺旋状γ-TuRC。","13根原纤维是微管壁的结构，不是γ-TuRC。","数目与复合物层级均与原文不符。"]},"cards":null,"mem":"2γ+辅助蛋白=TuSC，7个螺旋成环","big":"assets/img/ch06/big/p029.jpg","summary":"考点：第一节 微管 · 1.3 MTOC and orienta ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「γ-tubulin ring complex (from J.M.Kollman」的核心内容，能解释其机制、比较相关概念。","intuition":"γ-TuRC 像“螺旋排列的模板”：2 个 γ-tubulin + 附属蛋白成小复合物，7 个小复合物拼成环。"},{"i":29,"sec":"1.3 MTOC and orienta","title":"微管在植物细胞中的排列方式","notes":"Spindle\nMTs\nCortical MTs\n周质微管                                       Phragmoplast\n成膜体微管\n早前期带\n●植物细胞：Four major arrays of MTs present during the cell\ncycle of a Plant Cell\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.3 MTOC and orienta ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页讲微管在植物细胞中的排列方式。植物细胞周期中出现四种主要微管阵列（arrays）：周质微管（cortical MTs）、早前期带（对应未来分裂面 future division plane）、纺锤体微管（spindle MTs）和成膜体微管（phragmoplast）。它们分别参与细胞形态维持、分裂面定位、染色体分离和胞质分裂。原文强调这是植物细胞周期中四类主要微管阵列，属常考的结构—功能对应关系。","page":30,"level":"掌握","img":"assets/img/ch06/p030.jpg","anim":null,"fig":null,"points":["cell wall","future division plane"],"check":{"q":"植物细胞周期中出现四种主要微管阵列，下列不属于其中的是？","o":["A. 周质微管(cortical MTs)","B. 早前期带","C. 成膜体微管(phragmoplast)","D. 应力纤维(stress fiber)"],"a":"D","e":"植物细胞周期中的四类微管阵列为周质微管、早前期带、纺锤体微管和成膜体微管；应力纤维由肌动蛋白构成，属微丝结构。","oe":["周质微管是四类微管阵列之一，参与维持细胞形态。","早前期带是四类阵列之一，对应未来分裂面。","成膜体微管是四类阵列之一，参与胞质分裂。","应力纤维由肌动蛋白构成，属微丝而非微管阵列。"],"basis":"植物细胞周期中出现四种主要微管阵列"},"cards":null,"mem":"皮质带、纺锤体、成膜体：植物微管阵","big":"assets/img/ch06/big/p030.jpg","terms":[{"t":"成膜体","en":"phragmoplast","d":"植物细胞胞质分裂中引导细胞板形成的微管阵列。"},{"t":"细胞板","en":"cell plate","d":"植物细胞分裂时由囊泡融合形成、最终发育为新细胞壁的结构。"}],"summary":"考点：第一节 微管 · 1.3 MTOC and orienta ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「微管在植物细胞中的排列方式」的核心内容，能解释其机制、比较相关概念。","intuition":"植物细胞在周期中出现四种微管阵列：皮层、早前期带、纺锤体、成膜体。"},{"i":30,"sec":"1.3 MTOC and orienta","title":"胞质分裂及植物细胞壁的形成","notes":"有丝分裂后期细胞质一分为二\n动物细胞：微丝及相关的马达蛋白actin/myosin形成收缩环\n(contractile ring)，通过相互滑动使收缩环紧缩完成。\n植物细胞：胞质分裂靠细胞内新细胞壁的形成完成。携带细胞壁\n前体物质的膜泡沿着成膜体微管运到细胞中间，相互融合成膜包\n裹的盘状结构-初级细胞板(cell plate)后向两侧扩大延伸，与原有\n的细胞质膜结合，同时将细胞质分成两半。","page":31,"level":"掌握","img":"assets/img/ch06/p031.jpg","anim":null,"fig":null,"points":["与合成细胞板的物质运输有关"],"check":{"q":"关于植物细胞胞质分裂的完成方式，下列叙述正确的是？","o":["A. 携带细胞壁前体物质的膜泡沿成膜体微管运输，融合形成细胞板","B. 由中间纤维收缩将细胞一分为二","C. 通过细胞膜内陷形成分裂沟完成","D. 由微丝和肌球蛋白形成收缩环缢缩完成"],"a":"A","e":"动物细胞靠actin/myosin收缩环缢缩；植物细胞靠成膜体微管运输膜泡形成初级细胞板并扩展完成胞质分裂。","oe":["植物细胞靠成膜体微管运输膜泡形成细胞板。","中间纤维不参与胞质分裂的缢缩。","细胞膜内陷成分裂沟是动物细胞特征。","收缩环缢缩是动物细胞胞质分裂的方式。"]},"cards":null,"mem":"动物靠收缩环，植物靠成膜体成细胞板","big":"assets/img/ch06/big/p031.jpg","summary":"有丝分裂后期细胞质一分为二","goal":"学完应能掌握并运用「胞质分裂及植物细胞壁的形成」的核心内容，能解释其机制、比较相关概念。","intuition":"植物胞质分裂靠成膜体引导，囊泡聚成细胞板，最终变成新细胞壁。"},{"i":31,"sec":"1.3 MTOC and orienta","title":"植物成膜体微管作用","notes":"The phragmoplast guides cytokinesis in higher plants.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.3 MTOC and orienta ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页讲植物成膜体微管（phragmoplast）的作用：成膜体引导高等植物的胞质分裂（cytokinesis）。成膜体由反向平行的微管和微丝构成，位于分裂细胞赤道面，指导含细胞壁物质的囊泡向中央运输并融合，逐步形成细胞板（cell plate），最终分隔成两个子细胞。与动物细胞的收缩环分裂方式不同，是植物细胞分裂的特征结构，属高频考点。","page":32,"level":"掌握","img":"assets/img/ch06/p032.jpg","anim":"plant_phragmoplast","fig":null,"points":["高等植物胞质分裂中，成膜体(phragmoplast)引导细胞板形成与胞质分裂"],"check":{"q":"高等植物细胞胞质分裂中，成膜体(phragmoplast)的主要作用是？","o":["A. 由反向平行微管和微丝构成，引导囊泡运输并逐步形成细胞板","B. 由中心体发出的星体微管牵引染色体移向两极","C. 由纺锤体极性微管相互滑动，使两极分离","D. 由收缩环的肌动蛋白-肌球蛋白驱动，形成卵裂沟"],"a":"A","e":"植物细胞胞质分裂依赖成膜体，它由反向平行的微管和微丝构成，引导含壁物质囊泡向赤道面运输并融合形成细胞板。","oe":["成膜体指导高等植物胞质分裂，形成细胞板。","染色体运动属纺锤体功能，且植物无典型星体。","极性微管滑动介导后期B两极分离，非成膜体作用。","收缩环是动物细胞胞质分裂的方式。"]},"cards":null,"mem":"成膜体导胞质分裂，囊泡聚成细胞板","big":"assets/img/ch06/big/p032.jpg","summary":"考点：第一节 微管 · 1.3 MTOC and orienta ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「植物成膜体微管作用」的核心内容，能解释其机制、比较相关概念。","intuition":"成膜体像“修墙的脚手架”：引导囊泡聚成细胞板、把两个子细胞分开。"}],"mcq":[{"id":"ch06_mcq_1","mod":"1.3 MTOC and orienta","modI":4,"q":"由微管组成的细胞表面特化结构是（            ）。","o":["A．鞭毛","B．微绒毛","C．伪足","D．桥粒与半桥粒"],"a":"A","e":"纤毛和鞭毛是细胞表面的特化结构，具有运动功能。纤毛和鞭毛的轴心有一束“9 ＋2”排列的平行微管。","kp":"ch06_s4_22","oe":["正确。鞭毛由微管组成，轴心为9+2排列的平行微管束。","错误。微绒毛由微丝构成，不是由微管组成。","错误。伪足由微丝构成，参与细胞的变形运动。","错误。桥粒与半桥粒是细胞连接，非微管组成的结构。"]},{"id":"ch06_mcq_5","mod":"1.3 MTOC and orienta","modI":4,"q":"纤毛、鞭毛的基体由下列哪种微管构成（         ）。","o":["A．二联管","B．三联管","C．单管","D．四联管"],"a":"A","e":"中心粒是三联管。","kp":"ch06_s4_22","oe":["正确。纤毛、鞭毛的轴心为9+2排列，其组成微管是二联管。","错误。三联管是中心粒(及基体)的结构，不同于二联管。","错误。单管是细胞质中的普通微管，不是纤毛鞭毛的微管。","错误。细胞内并不存在四联管这样的微管结构。"]}],"judge":[{"id":"ch06_judge_1","modI":4,"q":"通常微管的负端埋在中心体中，而正端只能加长，不能缩短，所以能保证微管的稳定。 （   ）","a":"错","e":"微管的负端埋在中心体中，但正端是可以加长的。","kp":"ch06_s4_25","oe":["若判对则误认为正端不能解聚，实际微管正端既可加长也可缩短。","微管具动态不稳定性，正端既能加长也能缩短，并非只加长而稳定。"]},{"id":"ch06_judge_2","modI":4,"q":"在动物细胞中，中心体是主要的微管组织中心。（            ）","a":"对","e":"纺锤体微管和胞质微管由中心体基质囊多个γ管蛋白形成的环状核心放射出来。","kp":"ch06_s4_22","oe":["动物细胞中中心体是主要微管组织中心，γ管蛋白环形核心向外发出微管。","误判为错者或否定中心体作用，其实纺锤体与胞质微管多由中心体发出。"]},{"id":"ch06_judge_3","modI":4,"q":"微管存在于所有真核生物细胞中。（                 ）","a":"错","e":"人的红细胞中没有微管，另外，原核生物中没有微管。","kp":"ch06_s4_22","oe":["若判对则忽视了人成熟红细胞无微管，且原核生物根本不存在微管。","微管并非存在于所有真核细胞，如哺乳动物成熟红细胞中就没有微管。"]},{"id":"ch06_judge_5","modI":4,"q":"在所有动力动物细胞中，中心体是主要的微管组织中心。（                   ）","a":"错","e":"在动物细胞中，微管组织中心还包括纤毛、鞭毛的基体。","kp":"ch06_s4_22","oe":["若判对则忽略纤毛、鞭毛基体等也可作为微管组织中心。","动物细胞中微管组织中心除中心体外，还包括纤毛和鞭毛的基体等。"]},{"id":"ch06_judge_8","modI":4,"q":"加入秋水仙碱可抑制绿藻细胞中的胞质环流运动。（                        ）","a":"对","e":"秋水仙碱是微管组装的阻断剂，用它处理细胞会导致细胞内微管系统的解体，从而 抑制胞质环流运动。","kp":"ch06_s4_29","oe":["秋水仙碱是微管组装阻断剂，使微管解体从而抑制依赖微管的胞质环流。","误判为错者或以为胞质环流与微管无关，其实该运动依赖微管系统。"]}],"fill":[{"id":"ch06_fill_2","modI":4,"q":"______在细胞间期组织形成间期微管，在细胞分裂期组织形成______，因而被称为细胞 的微管组织中心。","a":"中心体；胞质分裂环","kp":"ch06_s4_22","oe":["间期微管由中心体即微管组织中心组织形成，故填中心体。","分裂期微管组织中心组织纺锤体，其星体微管定位胞质分裂环。"]},{"id":"ch06_fill_7","modI":4,"q":"肌丝成分中收缩蛋白有______和______，调节蛋白有______和______。","a":"肌动蛋白；肌球蛋白；原肌球蛋白；肌钙蛋白","kp":"ch06_s4_24","oe":["收缩蛋白包括肌动蛋白和肌球蛋白，二者相互作用产生收缩。","肌球蛋白是粗肌丝主要成分，其头部与肌动蛋白结合并水解ATP。","调节蛋白包括原肌球蛋白和肌钙蛋白，调控收缩的启动。","肌钙蛋白结合Ca2+后解除原肌球蛋白对肌动蛋白的阻挡。"]},{"id":"ch06_fill_8","modI":4,"q":"组成纤毛、鞭毛结构的 3 部分是______、______和______，其中______具有 MTOC 作 用。","a":"毛部；基体；根丝；基体","kp":"ch06_s4_22","oe":["纤毛鞭毛伸出细胞表面的主体，由9+2微管构成，可摆动。","位于毛部基部，由9组三联体微管组成，是微管的锚定结构。","基体下方伸入细胞质的微丝样结构，起固定和支持作用。","作为微管组织中心，是纤毛鞭毛微管装配的起始部位。"]},{"id":"ch06_fill_13","modI":4,"q":"微管在细胞中以三种形式存在，大部分细胞质微管是______不太稳定；构成纤毛、鞭毛 周围小管的是 ______，比较稳定；组成中心粒和基体的是______，十分稳定。","a":"单体；二联体；三联体","kp":"ch06_s4_22","oe":["细胞质微管多为13条原纤丝组成的单管，动态变化不稳定。","纤毛鞭毛周围小管由A、B两亚管并合而成，较为稳定。","中心粒和基体由A、B、C三个亚管组成，十分稳定。"]}],"short":[{"id":"ch06_short_1","modI":4,"q":"微管的主要功能有哪些？","a":"真核细胞内部是高度区域化的体系，微管与生物大分子、细胞器在细胞内的分布，以及 细胞形态的维持具有密切关系。 （1）支持细胞的功能，构成细胞内网状支架，维持细胞形状，固定与支持细胞器的位置。 （2）与细胞器位移和细胞运动有关，染色体的移动、纤毛、鞭毛的运动都是由微管聚合和 解聚产生的。 （3）参与运输，颗粒物质可沿微管移动。 （4）与某些信息的传递有关。","kp":"ch06_s4_23"},{"id":"ch06_short_2","modI":4,"q":"试述纤毛和鞭毛的结构与功能。","a":"纤毛（flagella）和鞭毛（cilia）是真核细胞表面的具有运动功能特化结构。 （1）纤毛和鞭毛的结构：是细胞质膜所包被的细长突起，内部由微管构成轴丝结构。由基 体和纤毛轴丝两部分组成。纤毛轴轴丝为“9＋2”排列微管，即外周 9 组二联体微管＋中央鞘 包围的 2 根中央单体微管。外周二联体微管由 A，B 亚纤维组成，A 亚纤维为完全微管，B 亚纤维仅由 10 个亚基构成。中央微管均为完全微管。基体的微管组成为“9＋0”，无中央微 管。 （2）纤毛和鞭毛的运动机相关的滑动学说被普遍认可：纤毛运动由轴丝介导的相邻二联体 间相互滑动所致。由一个二联体的 A 管伸出的动力蛋白臂的马达结构域在相邻的二联体的 B 管上“行走”。","kp":"ch06_s4_22"},{"id":"ch06_short_11","modI":4,"q":"用秋水仙素处理动物细胞，细胞内质网与高尔基体分布有什么改变，为什么？","a":"（1）秋水仙素处理动物细胞后内质网与高尔基体分布的改变 用秋水仙素处理动物细胞，内质网缩回到细胞核周围，高尔基体解体成小的膜泡样结构分散 在细胞质内，细胞内依赖于微管的物质运输系统全面瘫痪。 （2）发生改变的原因 真核细胞内部是高度区室化的结构，细胞中某些物质的合成部位与行使功能部位往往是不同 的。内膜系统把细胞质分割成一个个区室，将物质合成部位和功能行使部位分隔开，微管是 维持区室化的重要结构基础。秋水仙素是微管蛋白组装抑制剂，当用秋水仙素处理动物细胞 后，微管很快解聚，从而造成内质网和高尔基体凝聚化。","kp":"ch06_s4_22"}],"calc":[],"term":[{"id":"ch06_term_3","modI":4,"term":"微管组织中心（microtubule organizingcenter，MTOC）。","def":"微管组织中心（microtubule organizingcenter，MTOC）是指微管在生理状态或实验处理 解聚后重新装配的发生处。如鞭毛基体、动物细胞中的中心体。微管组织中心决定了细胞微 管的极性，微管的负极指向微管组织中心，正极背向微管组织中心。","kps":"","kp":"ch06_s4_23"},{"id":"ch06_term_7","modI":4,"term":"MTOC","def":"MTOC 的中文名称是微管组织中心。微管组织中心是指具有起始微管组装和延伸的细 胞结构，细胞内的微管组织中心包括中心体和位于纤毛和鞭毛基部的基体等。MTOC 不仅 为微管提供了生长的起点，而且还决定了微管的方向性。靠近 MTOC 的一端由于生长慢而 称为负端；远离 MTOC 一端的微管生长速度快，称为正端，所以正端指向细胞质基质，常 常靠近细胞质膜。","kps":"","kp":"ch06_s4_20"}]},{"i":5,"name":"第一节 微管 · 1.4 微管特异性药物","slides":[{"i":32,"sec":"1.4 微管特异性药物","title":"1.4 微管特异性药物","notes":"Microtubule specific drug\n◆紫杉醇(taxol)：存在于红豆杉属植物中的一种次生代谢产物,\n也是目前所了解的惟一一种可以促进微管聚合和稳定已聚合\n微管的药物。(facilitate the assemble of microtubule, enhance\nthe stability of microtubule； Binding to MTs, stabilize MTs)\n◆秋水仙素(colchicine)\n秋水仙素结合到游离的微管蛋白二聚体, 阻止微管聚合\n(Binding to tubulin dimers, prevent MTs polymerization) ……\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.4 微管特异性药物 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• ·动力学不稳定性产生的原因：微管两端具GTP帽(取决于微管蛋白浓度),微管将继续组装,反之,无GDP帽则解聚。微管特异性药物◆秋水仙素(colchicine)阻断微管蛋白组装成微管，可破坏纺锤体结构。◆紫杉酚(taxol)能促进微管的装配,","page":33,"level":"了解","img":"assets/img/ch06/p033.jpg","anim":null,"fig":null,"points":["长春花碱(vinblastine)、除草剂(植物细胞微管研究)"],"check":{"q":"关于微管特异性药物的作用，下列叙述正确的是？","o":["A. 紫杉醇促进微管聚合并稳定已聚合的微管","B. 秋水仙素促进微管聚合并稳定已聚合微管","C. 紫杉醇结合游离微管蛋白二聚体，阻止微管聚合","D. 秋水仙素与紫杉醇均能稳定微管"],"a":"A","e":"紫杉醇促进微管聚合、稳定已聚合微管；秋水仙素结合游离微管蛋白二聚体，阻止微管聚合。","oe":["紫杉醇促进微管聚合并稳定已聚合微管。","秋水仙素阻止微管聚合，不促进聚合。","结合游离二聚体、阻止聚合的是秋水仙素。","秋水仙素阻止聚合，不能稳定微管。"]},"cards":null,"mem":"紫杉醇稳定，秋水仙素阻聚，长春花碱","big":"assets/img/ch06/big/p033.jpg","terms":[{"t":"紫杉醇","en":"taxol","d":"促进微管聚合、抑制解聚而稳定微管的药物。"},{"t":"秋水仙素","en":"colchicine","d":"抑制微管聚合、引起微管解聚的药物。"},{"t":"长春花碱","en":"vinblastine","d":"抑制微管聚合的药物，用于抗肿瘤。"}],"summary":"◆紫杉醇(taxol)：存在于红豆杉属植物中的一种次生代谢产物,","goal":"学完应能了解「1.4 微管特异性药物」，能再认相关名词与实例。"},{"i":33,"sec":"1.4 微管特异性药物","title":"Effect of the drug taxol on microtubule organization","notes":"MT organization in a liver epithelial cell\nbefore and after taxol treatment.\ncontrol     taxol teatment\nThe natural source\nof taxol\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.4 微管特异性药物 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 微管在生理状态或实验处理解聚后重新装配的发生处称为微管组织中心(microtubule organizingcenter, MTOC)。常见微管组织中心◆间期细胞MTOC：●      中心体(动态微管)\n\n【本页英文讲解】\n本页展示药物紫杉醇（taxol）对微管组织（microtubule organization）的影响。图为肝上皮细胞（liver epithelial cell）在紫杉醇处理前（control）与处理后（taxol treatment）的微管组织对比。紫杉醇能与微管结合并稳定微管，抑制其解聚，从而打乱微管的正常动态与排布。原文还提到紫杉醇的天然来源（natural source）。紫杉醇稳定微管的机制及其抗癌应用是重点。","page":34,"level":"掌握","img":"assets/img/ch06/p034.jpg","anim":"mt_drugs","fig":null,"points":["紫杉醇(taxol)处理肝上皮细胞后微管组织被打乱","其机制是促进微管聚合、抑制解聚而稳定微管"],"check":{"q":"紫杉醇(taxol)处理肝上皮细胞后微管组织被打乱，其作用机制是？","o":["A. 与微管蛋白结合并促进微管解聚，使微管消失","B. 促进微管蛋白水解GTP，加速微管的踏车运动","C. 与微管结合并稳定微管，抑制其解聚，打乱微管的正常动态与排布","D. 抑制微管组织中心复制，使微管无法成核"],"a":"C","e":"紫杉醇与微管结合并稳定微管、抑制其解聚，使微管动态和排布紊乱，是常用的微管稳定剂。","oe":["促解聚的是秋水仙素、诺考达唑等。","紫杉醇并非通过影响GTP水解加速踏车。","紫杉醇稳定微管、抑制解聚，是低温稳定微管药物。","紫杉醇直接作用于微管，不抑制MTOC复制。"]},"cards":null,"mem":"紫杉醇绑定微管，打乱其正常动态","big":"assets/img/ch06/big/p034.jpg","summary":"考点：第一节 微管 · 1.4 微管特异性药物 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「Effect of the drug taxol on microtubule 」的核心内容，能解释其机制、比较相关概念。","intuition":"紫杉醇像“把微管焊死”：稳定微管、阻止解聚，分裂细胞被卡死，用于抗癌。"}],"mcq":[{"id":"ch06_mcq_4","mod":"1.4 微管特异性药物","modI":5,"q":"促进微管聚合的药物是（         ）。","o":["A．鬼臼素","B．长春花碱","C．紫杉酚","D．细胞松弛素"],"a":"C","e":"A 项，鬼臼素（peltatin）会抑制细胞 DNA 合成，使细胞处于分裂期。B 项，长春 花碱与秋水仙素的作用相似，能抑制微管的装配，是微管的特异性抑制剂。C 项，紫杉酚和 重水（D2O）可使微管稳定性增加并使细胞周期停止于有丝分裂期。D 项，细胞松弛素可以 切断微丝，并结合在微丝正极阻抑肌动蛋白聚合，而可以破坏微丝的三维网络，特异性的抑 制微丝的装配。","kp":"ch06_s5_32","oe":["错误。鬼臼素抑制DNA合成，使细胞处于分裂期，非促微管聚合。","错误。长春花碱抑制微管装配，为微管解聚剂。","正确。紫杉酚和重水使微管稳定性增加，促进微管聚合。","错误。细胞松弛素特异性抑制微丝的装配。"]}],"judge":[{"id":"ch06_judge_4","modI":5,"q":"紫杉酚能促进微管的装配，因此对细胞是有利的。（                    ）","a":"错","e":"紫杉酚能促进微管的装配，但这种稳定性的增加对细胞是有害的，使细胞周期停止 于有丝分裂期。","kp":"ch06_s5_32","oe":["若判对则只看其促进装配，忽视过度稳定会使细胞停滞于有丝分裂期。","紫杉酚虽促进微管装配并使之稳定，但导致细胞周期阻断于有丝分裂期。"]}],"fill":[{"id":"ch06_fill_6","modI":5,"q":"微管蛋白二聚体是由______和______组成的。","a":"α-微管蛋白；β微管蛋白","kp":"ch06_s5_32","oe":["微管蛋白异二聚体由α微管蛋白和β微管蛋白组成，α为其一。","β微管蛋白是异二聚体的另一亚基，具GTP结合位点。"]},{"id":"ch06_fill_12","modI":5,"q":"紫杉醇和长春花碱抗癌作用的机制分别是______。","a":"抑制微管解聚和抑制微管聚合","kp":"ch06_s5_32","oe":["紫杉醇稳定微管、抑制其解聚；长春花碱抑制微管聚合，均破坏纺锤体。"]}],"short":[],"calc":[],"term":[]},{"i":6,"name":"第一节 微管 · 1.5 微管结合蛋白","slides":[{"i":34,"sec":"1.5 微管结合蛋白","title":"1.5 微管结合蛋白","notes":"microtubule-associated proteins, MAPs:\nproteins that bind along the sides of microtubules\nare collectively called MAPs.\n能够结合单体以及多聚体状态的微管蛋白并调节微管\n功能的蛋白质。\n细胞骨架(微管、微丝、中间纤维)结合蛋白：细\n胞骨架功能的实现及其调节需要结合蛋白的参与；\n结合蛋白在组织细胞骨架排列、动态特性调节以及\n细胞骨架成分之间的相互联系上都有重要作用。","page":35,"level":"掌握","img":"assets/img/ch06/p035.jpg","anim":null,"fig":null,"points":["微管结合蛋白(MAPs)能与微管结合并调节微管功能","MAPs可结合单体及多聚体状态的微管蛋白"],"check":{"q":"微管结合蛋白(MAPs)是指？","o":["A. 位于微管组织中心、启动微管成核的γ-微管蛋白","B. 具有ATP酶活性、沿微管定向行走的马达蛋白","C. 能结合单体及多聚体状态的微管蛋白并调节微管功能的蛋白质","D. 构成微管壁的α/β微管蛋白异二聚体"],"a":"C","e":"MAPs是能结合单体及多聚体状态微管蛋白并调节微管功能的蛋白质，参与微管排列、动态调节与成分联系。","oe":["γ-微管蛋白是成核因子，属特殊类群。","这是马达蛋白(如kinesin、dynein)的特征。","MAPs定义即结合微管蛋白并调节其功能。","异二聚体是微管的组成亚基，不是MAPs。"]},"cards":null,"mem":"MAP结合微管侧，调稳定与成束","big":"assets/img/ch06/big/p035.jpg","summary":"能够结合单体以及多聚体状态的微管蛋白并调节微管","goal":"学完应能掌握并运用「1.5 微管结合蛋白」的核心内容，能解释其机制、比较相关概念。","intuition":"微管结合蛋白像“微管的配件”：结合微管、调节其稳定、成束与连接。"},{"i":35,"sec":"1.5 微管结合蛋白","title":"Mictrotubule-","notes":"associated proteins\n(MAPs) co-purify\nwith microtubules\nPhoto courtesy of\nLynne Cassimeris,\nLehigh University.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 肌球蛋白（myosin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部能结合肌动蛋白和 ATP。\n\n【本页英文讲解】\n本页介绍微管结合蛋白（microtubule-associated proteins, MAPs）。这类蛋白能与微管共纯化（co-purify），即随微管一起被分离出来，说明它们与微管紧密结合。MAPs可调节微管的稳定性、成束（bundling）及与其他细胞结构的连接。图片由美国Lehigh大学Lynne Cassimeris提供。掌握MAPs的定义与共纯化这一实验依据，是理解微管功能调控的入口。","page":36,"level":"掌握","img":"assets/img/ch06/p036.jpg","anim":null,"fig":null,"points":["微管结合蛋白(MAPs)可在实验上与微管共纯化(co-purify)"],"check":{"q":"实验中微管结合蛋白(MAPs)可与微管\"共纯化(co-purify)\"，这一现象最直接说明？","o":["A. MAPs可水解ATP驱动微管滑动","B. MAPs与微管紧密结合，可随微管一起被分离出来","C. MAPs只结合游离的微管蛋白单体","D. MAPs是微管的组成亚基，决定微管的直径"],"a":"B","e":"MAPs能与微管共纯化，说明其与微管紧密结合；这是鉴定MAPs的经典实验依据。","oe":["水解ATP驱动运动的是马达蛋白，与共纯化无关。","共纯化说明二者结合紧密，是MAPs的实验依据。","MAPs可结合单体与多聚体两种状态。","MAPs并非微管壁的组成亚基。"]},"cards":null,"mem":"MAP与微管共纯化，证明紧密结合","big":"assets/img/ch06/big/p036.jpg","terms":[{"t":"微管结合蛋白","en":"MAPs","d":"结合在微管侧面、调节微管稳定性/成束/与其他结构连接的蛋白。"}],"summary":"考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「Mictrotubule-」的核心内容，能解释其机制、比较相关概念。","intuition":"MAPs 在实验上能“与微管一起被纯化出来”，说明它紧贴微管。"},{"i":36,"sec":"1.5 微管结合蛋白","title":"（本页为图片/无文字层）","notes":"【读图讲解】\n汇总模式图：γ-TuRC 在中心体(centrosome)成核并结合微管负端；MAP 调控微管——stathmin 阻止组装、kinesin-13 促灾变、katanin 切断、XMAP215 与 τ/MAP-2 稳定或成束、+TIPs 随正端生长、plectin 连接中间纤维。考点：MAPs 与 γ-TuRC 调控微管组装、稳定与成束。","page":37,"level":"掌握","img":"assets/img/ch06/p037.jpg","anim":null,"fig":null,"points":["Y-TURC","nucleates assembly and","remalnsassoclatedwith","centrosome","the mlnus end","stathmin","+TIPS","binds subunits,"],"check":{"q":"下列微管结合蛋白与其功能对应正确的是？","o":["A. XMAP215促进微管解聚，tau促进微管切断","B. stathmin稳定微管，kinesin-13促进成核，katanin使微管成束","C. stathmin阻止微管组装，kinesin-13促进灾变，katanin切断微管","D. plectin切断微管，+TIPs结合微管负端"],"a":"C","e":"微管结合蛋白功能多样：stathmin阻止组装、kinesin-13促灾变、katanin切割、XMAP215与tau/MAP-2稳定成束、+TIPs追踪正端、plectin连接中间纤维。","oe":["XMAP215和tau均为稳定/成束因子。","stathmin为解聚因子，katanin是切割而非成束。","三者分别阻止组装、促解聚、切断，对应正确。","plectin连接中间纤维，+TIPs追踪正端。"]},"cards":null,"mem":"γ-TuRC成核，MAPs稳切束连","big":"assets/img/ch06/big/p037.jpg","summary":"汇总模式图：γ-TuRC 在中心体(centrosome)成核并结合微管负端；MAP 调控微管——stathmin 阻止组装、kinesin-13 促灾变、katanin 切断、X","goal":"学完应能掌握并运用「（本页为图片/无文字层）」的核心内容，能解释其机制、比较相关概念。","intuition":"本页以图展示 MAPs 在中心体等处的分布。"},{"i":37,"sec":"1.5 微管结合蛋白","title":"Effects of proteins that bind to microtubule ends.","notes":"【结合课本/笔记】（五）Signal Transduction           （问答英文）ReceptorsDefinition: Any protein that specifically binds to another molecules tomediate cell-cell signaling, adhesion, endocytosis or other cellularprocess. Mostly commonly denotes a protein located in the plasma membraneor cytoplasm that is activated by binding a specific extrace\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 信号转导（signal transduction）：指细胞外因子通过与受体（膜受体或核受体）结合，引起细胞内的一系列生物化学反应以及蛋白间相互作用，直至细胞生理反应所需基因开始表达、各种生物学效应形成的过程\n\n【本页英文讲解】\n本页标题为结合微管末端蛋白的作用（effects of proteins that bind to microtubule ends）。原文正文较为残缺，仅能判断该页讨论某些蛋白结合到微管两端后对微管动力学的影响：这类蛋白可改变微管末端的聚合或解聚速率，进而调控微管的伸长、缩短或稳定性。理解“末端结合蛋白可调节微管动态”这一核心即可，具体实验细节原文未完整给出。","page":38,"level":"掌握","img":"assets/img/ch06/p038.jpg","anim":null,"fig":null,"points":["结合到微管末端的蛋白可影响微管动力学(稳定或去稳定)"],"check":{"q":"结合到微管末端的蛋白对微管动力学的主要影响是？","o":["A. 改变微管末端的聚合或解聚速率，进而调控微管的伸长、缩短或稳定性","B. 直接构成微管壁，决定微管由13根原纤维组成","C. 作为马达蛋白，水解ATP沿微管行走运输囊泡","D. 与微管蛋白单体共价结合，使其不可逆失活"],"a":"A","e":"结合微管末端的蛋白通过改变末端的聚合或解聚速率来调控微管的伸长、缩短与稳定性。","oe":["末端结合蛋白通过影响加减速度调节动态。","微管壁由α/β微管蛋白构成，与末端蛋白无关。","运输囊泡是马达蛋白功能，非末端结合蛋白。","末端结合是可逆调控，并非共价灭活。"]},"cards":null,"mem":"末端结合蛋白：稳定或去稳定微管","big":"assets/img/ch06/big/p038.jpg","summary":"考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「Effects of proteins that bind to microtu」的核心内容，能解释其机制、比较相关概念。","intuition":"结合微管末端的蛋白像“帽/剪”：有的稳定末端，有的促进解聚。"},{"i":38,"sec":"1.5 微管结合蛋白","title":"● Organization of MTs bundles by MAPs.","notes":"Overexpressing MAP2        Overexpressing tau\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页讲微管结合蛋白（MAPs）对微管成束（bundles）的组织作用。图中分别展示过表达MAP2和过表达tau两种蛋白时微管的排列变化。MAP2和tau都是神经细胞中重要的MAPs，它们能交联相邻微管，使微管形成平行的束状结构，从而稳定和支持神经元突起。要点是不同MAPs介导不同形式的微管成束，tau异常与神经退行性疾病相关，属易考联系点。","page":39,"level":"掌握","img":"assets/img/ch06/p039.jpg","anim":"map_bundling","fig":null,"points":["过表达MAP2或tau交联相邻微管，使微管形成平行束状结构"],"check":{"q":"过表达MAP2或tau蛋白后，微管的排列发生的主要变化是？","o":["A. 微管相互垂直交叉，形成直角网络","B. MAP2和tau交联相邻微管，使微管形成平行的束状结构","C. 微管从中心体解聚，弥散分布于细胞质中","D. 微管被切割成大量短片段，数量明显增多"],"a":"B","e":"MAP2和tau是神经元中重要MAPs，可交联相邻微管使其成平行束，从而稳定和支持神经元突起。","oe":["直角交叉网由filamin交联微丝形成。","图示过表达两种MAPs均使微管成束。","MAPs作用为稳定成束，而非解聚。","切割是katanin的功能，与MAPs成束不同。"]},"cards":null,"mem":"MAP2/tau交联微管成平行束","big":"assets/img/ch06/big/p039.jpg","summary":"考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「● Organization of MTs bundles by MAPs.」的核心内容，能解释其机制、比较相关概念。","intuition":"过表达 MAP2/tau 会让微管“扎成束”，反映它们交联微管的功能。"},{"i":39,"sec":"1.5 微管结合蛋白","title":"tau主要分布          Localization of MAPs in axon(轴突)","notes":"在神经细胞            and dendrites(树突) of a neuron.\n轴突\n阿尔茨海默症(Alzheimer’s disease,\nAD)患者脑内tau蛋白结构和功能异\n常：\ntau过度磷酸化，易从微管上脱落，\n聚集形成神经元纤维缠结\nMAP2主要分              (neurofibrillary tangles, NFTs)\n布在神经细                                 →\n胞树突                  脑神经细胞内微管稳定性降低，结\n构破坏，依赖微管的物质及信息传\n递系统受损\nThe tistribution of tau (green) and 阻碍正常的神经递质传递，甚至神\nMAP2(orange) in a hippocampal\n经元死亡\nneuron(海马神经细胞) in culture.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体","page":40,"level":"掌握","img":"assets/img/ch06/p040.jpg","anim":null,"fig":null,"points":["tau主要分布在神经元轴突，MAP2主要分布在树突","阿尔茨海默症中tau过度磷酸化、从微管脱落，聚集形成神经纤维缠结"],"check":{"q":"关于tau和MAP2在神经元中的分布及神经退行性疾病，下列叙述正确的是？","o":["A. tau主要分布于轴突，其过度磷酸化易脱落并聚集形成神经元纤维缠结","B. tau过度磷酸化可增强微管稳定性，保护神经元","C. 神经元纤维缠结由MAP2聚集形成，与tau无关","D. MAP2主要分布于轴突，tau主要分布于树突"],"a":"A","e":"tau主要分布于轴突、MAP2主要分布于树突；tau过度磷酸化后从微管脱落并聚集形成神经元纤维缠结，与阿尔茨海默症相关。","oe":["tau在轴突，过度磷酸化与AD缠结相关。","过度磷酸化使tau脱落、微管稳定性降低。","缠结由异常tau聚集形成，与MAP2无关。","二者分布恰好相反：tau在轴突、MAP2在树突。"]},"cards":null,"mem":"tau在轴突，MAP2在树突；tau过磷酸化致AD","big":"assets/img/ch06/big/p040.jpg","terms":[{"t":"神经纤维缠结","en":"neurofibrillary tangles, NFTs","d":"阿尔茨海默症中过度磷酸化的tau从微管脱落后聚集形成的结构。"}],"summary":"AD)患者脑内tau蛋白结构和功能异","goal":"学完应能掌握并运用「tau主要分布          Localization of MAPs in」的核心内容，能解释其机制、比较相关概念。","intuition":"tau 主要在轴突、MAP2 主要在树突；tau 病变（过度磷酸化）与阿尔茨海默症相关。"},{"i":40,"sec":"1.5 微管结合蛋白","title":"微管切割蛋白katanin","notes":"katanin\nA : 30 seconds after the\naddition of katanin\nB : the same field 3 minutes\nafter the addition of katanin\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 微管在生理状态或实验处理解聚后重新装配的发生处称为微管组织中心(microtubule organizingcenter, MTOC)。常见微管组织中心◆间期细胞MTOC：●      中心体(动态微管)\n\n【本页英文讲解】\n本页讲微管切割蛋白（katanin）对微管的切断作用（microtubule severing）。图A显示加入katanin后30秒，图B显示同一视野加入katanin后3分钟的变化，可见微管被逐渐切短、数量增多。Katanin是一种依赖ATP的微管切割蛋白，通过切断微管产生新的末端，增加微管数量并促进其重组。这是微管结合蛋白调控微管的重要方式，需掌握切割的含义。","page":41,"level":"掌握","img":"assets/img/ch06/p041.jpg","anim":"katanin_severing","fig":null,"points":["微管切割蛋白katanin依赖ATP切断微管，产生新的末端","可增加微管数量并促进微管重组"],"check":{"q":"关于微管切割蛋白katanin的作用，下列叙述正确的是？","o":["A. 交联相邻微管，使其形成平行束状结构","B. 结合微管正端并阻止微管蛋白添加，抑制微管伸长","C. 促进微管成核，作用类似γ-微管蛋白环状复合物","D. 依赖ATP切断微管，产生新的末端，增加微管数量并促其重组"],"a":"D","e":"katanin是依赖ATP的微管切割蛋白，通过切断微管产生新末端，增加微管数量并促进其重组。","oe":["成束由MAP2、tau等交联蛋白完成。","这是加帽蛋白的作用，不是切割。","成核由γ-TuRC负责，katanin负责切断。","katanin依赖ATP切断微管，产生新末端。"]},"cards":null,"mem":"katanin耗ATP切微管，产生新末端","big":"assets/img/ch06/big/p041.jpg","summary":"考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「微管切割蛋白katanin」的核心内容，能解释其机制、比较相关概念。","intuition":"katanin 像“微管剪切刀”：耗 ATP 把微管切断，增加末端数、促重组。","experiment":"【体外实验】把纯化的 katanin 加入荧光标记的微管，可见微管被迅速切断、数目增多；去掉 ATP 则不能——证明 katanin 依赖 ATP 切割微管。"},{"i":41,"sec":"1.5 微管结合蛋白","title":"p208","notes":"Proteins that destabilize the ends of microtubules.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页（教材第208页）指出存在一类使微管末端去稳定的蛋白（proteins that destabilize the ends of microtubules）。这类蛋白结合在微管末端并促进解聚或抑制聚合，从而增加微管的不稳定性、缩短微管寿命。它们与稳定微管的MAPs作用相反，共同精细调控微管动态。原文文字较简略，重点掌握“末端去稳定蛋白”这一概念及其与微管动态稳定性的关系。","page":42,"level":"掌握","img":"assets/img/ch06/p042.jpg","anim":null,"fig":null,"points":["末端去稳定蛋白结合微管末端，促进解聚或抑制聚合，增加微管不稳定性"],"check":{"q":"使微管末端去稳定(destabilize)的蛋白，其作用特点是？","o":["A. 切断微管，产生新的正端和负端","B. 结合微管侧面，交联微管使其成束","C. 结合微管末端，促进解聚或抑制聚合，增加微管的不稳定性","D. 与微管蛋白单体结合，促进其聚合"],"a":"C","e":"末端去稳定蛋白结合微管末端，促进解聚或抑制聚合，从而降低微管稳定性，与稳定微管的MAPs共同精细调控动态。","oe":["切断是katanin等切割蛋白的功能。","侧面结合成束是MAPs的稳定作用。","末端去稳定蛋白促解聚、增不稳定性。","促聚合与之相反，会提高稳定性。"]},"cards":null,"mem":"末端去稳定蛋白：促解聚抑聚合","big":"assets/img/ch06/big/p042.jpg","summary":"考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「p208」的核心内容，能解释其机制、比较相关概念。","intuition":"去稳定蛋白像“催微管解聚的推手”：结合末端、促进解聚或抑制聚合。"},{"i":42,"sec":"1.5 微管结合蛋白","title":"●1.6 马达蛋白 Motor protein:","notes":"A special class of enzymes (ATPase) that use energy from ATP\nhydrolysis to walk or slide along a MF or a MT.\n与微管、微丝结合的一类蛋白，具有ATPase活性，\n水解ATP，将化学能转化成机械能，驱动沿与微管、\n微丝有关的细胞内物质运输或运动(细胞周期中染色体\n运动－微管、细胞变形运动－微丝等)。\n●驱动蛋白(kinesin superfamily): 380 kDa\nkinesin1-kinesin12 move along microtubules(+).\nkinesin13解聚微管；Kinesin14(-)\n●动力蛋白(dyneins): over 1000 kDa\nTo move along microtubules(-).\n●肌球蛋白家族(myosin superfamily): 520 kDa\nTo move along microfilaments(+), except mysoin VI (-)\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n• 肌球蛋白（myosin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部能结合肌动蛋白和 ATP。\n\n【本页英文讲解】\n本页介绍马达蛋白（motor protein）：一类具有ATP酶（ATPase）活性的酶，水解ATP将化学能转化为机械能，沿微丝（MF）或微管（MT）行走或滑动，驱动细胞内运输与运动。驱动蛋白超家族（kinesin）约380 kDa，kinesin1–12沿微管正端移动，kinesin13解聚微管，kinesin14向负端移动；动力蛋白（dynein）超1000 kDa，向微管负端移动；肌球蛋白（myosin）约520 kDa，沿微丝正端移动（myosin VI除外）。","page":43,"level":"掌握","img":"assets/img/ch06/p043.jpg","anim":null,"fig":null,"points":["马达蛋白具ATPase活性，水解ATP将化学能转化为机械能","沿微管或微丝行走/滑动，驱动胞内运输或运动"],"check":{"q":"关于马达蛋白(motor protein)，下列叙述正确的是？","o":["A. 是一类结构蛋白，直接组成微管和微丝的骨架","B. 具有ATPase活性，水解ATP将化学能转变为机械能，沿微管或微丝运动","C. 只存在于肌肉细胞，仅参与肌肉收缩","D. 通过水解GTP驱动自身沿微管或微丝定向移动"],"a":"B","e":"马达蛋白是一类具ATP酶活性的蛋白，水解ATP将化学能转化为机械能，沿微管或微丝行走或滑动。","oe":["组成骨架的是微管蛋白和肌动蛋白。","马达蛋白以ATP水解供能沿骨架运动。","马达蛋白普遍存在于各类细胞，功能多样，并非仅见于肌肉。","供能方式为ATP水解而非GTP。"]},"cards":null,"mem":"驱动蛋白(+)、动力蛋白(−)、肌球蛋白(+)","big":"assets/img/ch06/big/p043.jpg","terms":[{"t":"马达蛋白","en":"motor protein","d":"具ATPase活性、水解ATP将化学能转化为机械能，沿微管/微丝行走的蛋白。"}],"summary":"与微管、微丝结合的一类蛋白，具有ATPase活性，","goal":"学完应能掌握并运用「●1.6 马达蛋白 Motor protein:」的核心内容，能解释其机制、比较相关概念。","intuition":"马达蛋白像“会走路的搬运工”：它抓住微管/微丝，水解 ATP 换来一步步挪动，把货物（囊泡、细胞器）拖到目的地。myosin 走微丝，kinesin/dynein 走微管，且各有固定方向。"},{"i":43,"sec":"1.5 微管结合蛋白","title":"马达蛋白特点：","notes":"Cytoplasmic dynein mechanical energy\nmotor;\nF-actin (MFs) and MTs-tracks;\nATP-fuel\nthat uses intermediate filament\ntracks.\n马达蛋白在微管、微丝上的移动有一定的\n方向性，这对于控制细胞运输或运动的\n方向性非常重要。\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n• 肌球蛋白（myosin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部能结合肌动蛋白和 ATP。\n\n【本页英文讲解】\n本页归纳马达蛋白的特点：能将化学能转化为机械能；肌球蛋白（myosin）、驱动蛋白（kinesin）、动力蛋白（dynein）为马达，分别以肌动蛋白纤维（F-actin/MF）和微管（MT）为轨道，以ATP为燃料。原文特别指出，目前尚未发现以中间纤维（intermediate filament）为轨道的马达蛋白。此外，马达蛋白在微管、微丝上移动具有方向性，这对控制细胞运输和运动的方向至关重要。方向性为高频考点。","page":44,"level":"掌握","img":"assets/img/ch06/p044.jpg","anim":null,"fig":null,"points":["Convert chemical energy into","Myosin, kinesin, dynein-","No motor protein is known"],"check":{"q":"关于马达蛋白的特点，下列叙述正确的是？","o":["A. 以中间纤维为轨道进行运输","B. 马达蛋白沿轨道移动无方向性","C. 能将化学能转化为机械能，以ATP为燃料","D. 肌球蛋白以微管为轨道，驱动蛋白以微丝为轨道"],"a":"C","e":"马达蛋白将化学能转为机械能、以ATP为燃料；myosin走微丝，kinesin和dynein走微管，移动具方向性。","oe":["目前未发现以中间纤维为轨道的马达蛋白。","马达蛋白沿轨道移动具有方向性。","马达蛋白将化学能转为机械能，以ATP为燃料。","肌球蛋白走微丝，驱动蛋白和动力蛋白走微管。"]},"cards":null,"mem":"马达ATP为燃料，微丝微管为轨，无IF马达","big":"assets/img/ch06/big/p044.jpg","summary":"马达蛋白在微管、微丝上的移动有一定的","goal":"学完应能掌握并运用「马达蛋白特点：」的核心内容，能解释其机制、比较相关概念。","intuition":"马达蛋白像“会走路的酶”：有 ATPase 活性，沿微管/微丝行走产生力。"},{"i":44,"sec":"1.5 微管结合蛋白","title":"微管的马达蛋白(motor protein):","notes":"具有ATPase活性, 水解ATP, 化学能转化\n为机械能, 驱动与微管有关的物质运输\n(intracellular transport)。\n(1)驱动蛋白(kinesin, is a (+) end-directed\nmicrotuble motor protein);\nKinesin1-kinesin12均为正向马达蛋白。\n(2)动力蛋白(dynein, is a (-) end-directed\nMT motor protein)：有两种\n●细胞质动力蛋白(Cytoplasmic dynein)\n●鞭毛、纤毛中的轴丝动力蛋白\nAxonemal dynein\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.5 微管结合蛋白 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n\n【本页英文讲解】\n本页专讲微管的马达蛋白（motor protein）：具ATP酶活性，水解ATP把化学能转为机械能，驱动与微管有关的物质运输（intracellular transport）。一类是驱动蛋白（kinesin），是向微管正端（(+) end）移动的马达，kinesin1–12均为正向马达；另一类是动力蛋白（dynein），向微管负端（(−) end）移动，包括细胞质动力蛋白（cytoplasmic dynein）和鞭毛、纤毛中的轴丝动力蛋白（axonemal dynein）。正负端方向性是核心考点。","page":45,"level":"掌握","img":"assets/img/ch06/p045.jpg","anim":null,"fig":null,"points":["驱动蛋白(kinesin)是向微管正端(+)运动的马达蛋白","动力蛋白(dynein)是向微管负端(−)运动的马达蛋白"],"check":{"q":"关于微管马达蛋白的方向性，下列叙述正确的是？","o":["A. kinesin1-12向微管负端移动，dynein向微管正端移动","B. kinesin和dynein均向微管正端移动","C. kinesin向负端移动，dynein向正端移动","D. kinesin1-12向微管正端移动，dynein向微管负端移动"],"a":"D","e":"微管马达蛋白中，kinesin1-12为向微管正端移动的正向马达，dynein为向微管负端移动的负向马达。","oe":["kinesin与dynein的移动方向恰好相反，此选项将其颠倒。","dynein是负端马达，向微管正端移动的说法错误。","kinesin向负端、dynein向正端的说法与事实完全相反。","驱动蛋白多为正端马达，动力蛋白为负端马达。"]},"cards":null,"mem":"kinesin向正，dynein向负；胞质/轴丝两种","big":"assets/img/ch06/big/p045.jpg","terms":[{"t":"细胞质动力蛋白","en":"cytoplasmic dynein","d":"胞质中向微管负端运输货物的动力蛋白。"},{"t":"轴丝动力蛋白","en":"axonemal dynein","d":"鞭毛、纤毛轴丝中驱动相邻二联体滑动的动力蛋白。"}],"summary":"具有ATPase活性, 水解ATP, 化学能转化","goal":"学完应能掌握并运用「微管的马达蛋白(motor protein):」的核心内容，能解释其机制、比较相关概念。","intuition":"微管马达两种：kinesin 朝正端、dynein 朝负端，方向分工明确。"}],"mcq":[],"judge":[],"fill":[{"id":"ch06_fill_5","modI":6,"q":"胞质中微管动力蛋白分为两大类分别为：______（kinesin）和______（cytoplasmic dynein）。 驱动蛋白通常朝微管的______方向运动，动力蛋白朝微管的______运动。","a":"驱动蛋白；动力蛋白；正极；负极","kp":"ch06_s6_44","oe":["kinesin是朝微管正极移动的马达蛋白，故填驱动蛋白。","cytoplasmic dynein朝微管负极移动，故填动力蛋白。","驱动蛋白通常沿微管向正极运输，如运往细胞外周。","动力蛋白沿微管向负极运输，如运回细胞中心。"]}],"short":[],"calc":[],"term":[{"id":"ch06_term_6","modI":6,"term":"kinesin & cytoplasmatic dynein 相关试题：驱动蛋白与动力蛋白","def":"kinesin 的中文名称是驱动蛋白，cytoplasmatic dynein 的中文名称是细胞质动力蛋白。二 者均属于微管马达蛋白，主要负责为物质沿着微管运输提供能量。 二者的区别在于沿微管运动的方向不同。驱动蛋白从微管的（－）端移向微管的（＋）端， 是正端走向的微管发动机；细胞质动力蛋白是负端走向的微管发动机，担负小泡和各种膜结 合细胞器的运输任务，同时还是细胞分裂中染色体运动的动力来源。","kps":"","kp":"ch06_s6_44"}]},{"i":7,"name":"第一节 微管 · 1.6.1 驱动蛋白(kinesin)","slides":[{"i":45,"sec":"1.6.1 驱动蛋白(kinesin)","title":"1.6.1 驱动蛋白(kinesin)","notes":"驱动蛋白：两条重链、两条\n轻链构成，MW为380 kD 。\n两个球状头部，一个柄，一\n个尾组成。\ntail\nhead\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.6.1 驱动蛋白(kinesin) ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n\n【本页英文讲解】\n本页介绍驱动蛋白（kinesin）的结构：由两条重链、两条轻链构成，分子量约380 kD，具有两个球状头部（head）、一个柄（stalk）和一个尾部（tail）。核心功能关系是：产生力的头部（head）结合到微管（MT）上，而尾部（tail）结合被运输的货物（cargo）。因此驱动蛋白一头“抓轨道”、一头“拉货物”，沿微管定向运输。掌握头部与尾部的分工是理解其工作机制的关键。","page":46,"level":"掌握","img":"assets/img/ch06/p046.jpg","anim":"kinesin_walk","fig":null,"points":["The force-generating heads bind to the MTs；","the tail binds to the cargo being transported."],"check":{"q":"关于驱动蛋白(kinesin)的结构与功能，下列叙述正确的是？","o":["A. 尾部具有ATP酶活性并产生力","B. 球状头部结合被运输的货物","C. 球状头部结合微管，尾部结合被运输的货物","D. 由两条轻链构成，不含重链"],"a":"C","e":"驱动蛋白由两条重链和两条轻链构成，约380kD，球状头部结合微管产生力，尾部结合货物。","oe":["产生力的ATP酶活性在头部，不在尾部。","结合货物的是尾部，不是球状头部。","球状头部结合微管产力，尾部结合货物。","驱动蛋白由两条重链和两条轻链构成。"]},"cards":null,"mem":"驱动蛋白：头抓轨道，尾拉货物","big":"assets/img/ch06/big/p046.jpg","terms":[{"t":"驱动蛋白","en":"kinesin","d":"向微管正端(+)运动的马达蛋白，含两个球状头部、一个柄和一条尾部。"}],"summary":"驱动蛋白：两条重链、两条","goal":"学完应能掌握并运用「1.6.1 驱动蛋白(kinesin)」的核心内容，能解释其机制、比较相关概念。","intuition":"kinesin 像“朝正端的搬运工”：含两个头部、一个柄和尾部，尾部接货物。"},{"i":46,"sec":"1.6.1 驱动蛋白(kinesin)","title":"The movement of a labeled kinesin(GFP) molecules along","notes":"microtubules(Cy5). (2007)\nto move processively along a microtubule\nwhose + end is labeled with a red\nfluorescent dye named Cy5.\nrepresent separate micrographs.\n0.77 μm/second.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.6.1 驱动蛋白(kinesin) ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n\n【本页英文讲解】\n本页（2007年数据）展示荧光标记的驱动蛋白分子沿微管运动。实验将纯化的GFP-驱动蛋白（GFP-kinesin）与正端用红色荧光染料Cy5标记的微管一起观察，可见单个GFP-kinesin持续地（processively）沿微管行走，连续图像从左到右为不同时刻的显微照片，其平均速度约为0.77 μm/秒。该实验直观证明了驱动蛋白能沿微管定向、持续移动，是单分子运动研究的经典证据。","page":47,"level":"掌握","img":"assets/img/ch06/p047.jpg","anim":null,"fig":null,"points":["A purified GFP-kinesin molecule is seen","The successive images, from left to right,","Kinesin is moving at an average speed of"],"check":{"q":"GFP-驱动蛋白沿Cy5标记微管的单分子实验，直接说明驱动蛋白能够？","o":["A. 沿微丝持续移动","B. 沿微管持续定向移动","C. 促使微管解聚","D. 向微管负端运输物质"],"a":"B","e":"该实验用荧光标记观察，证明单个GFP-驱动蛋白能持续地(processively)沿微管行走，平均速度约0.77 μm/s。","oe":["驱动蛋白沿微管运动，并非沿微丝移动。","实验直接显示驱动蛋白持续沿微管定向移动。","该实验观察的是运动，未显示其促微管解聚。","驱动蛋白通常向微管正端运输，实验未支持向负端。"],"basis":"单个GFP-kinesin持续地沿微管行走"},"cards":null,"mem":"GFP-驱动蛋白持续行走，0.77μm/s","big":"assets/img/ch06/big/p047.jpg","terms":[{"t":"持续地","en":"processively","d":"马达蛋白沿轨道连续行走多步而不脱落。"}],"summary":"考点：第一节 微管 · 1.6.1 驱动蛋白(kinesin) ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「The movement of a labeled kinesin(GFP) m」的核心内容，能解释其机制、比较相关概念。","intuition":"kinesin 能“持续走”多步不脱落，像很稳的搬运工。"},{"i":47,"sec":"1.6.1 驱动蛋白(kinesin)","title":"驱动蛋白特点","notes":"The yeast Saccharomyces cerevisiae酿酒酵母 has 6 distinct\nkinesins, the nematode C. elegans has 20 kinesins, and humans\nhave 45.\nheavy chain and walk toward the + end of the microtubule\n(MT).\nterminus and walks toward the minus end of the MT.\ndepolymerization.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.6.1 驱动蛋白(kinesin) ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n\n【本页英文讲解】\n本页总结驱动蛋白（kinesin）的特点：酿酒酵母（S. cerevisiae）有6种，线虫（C. elegans）20种，人类多达45种。多数驱动蛋白的马达结构域位于重链N端，向微管正端行走；kinesin-5成员形成反向四聚体，在纺锤体两极微管间滑动；kinesin-14的马达域位于C端，向微管负端行走；kinesin-13则利用ATP水解促进微管解聚。注意各类驱动蛋白的方向与功能差异。","page":48,"level":"掌握","img":"assets/img/ch06/p048.jpg","anim":null,"fig":null,"points":["Most kinesins have the motor domain at the N-terminus of the","Kinesin-5成员形成反向四聚体，在纺锤体两极微管之间滑动。","One fimily（kinesin-14）has the motor domain at the C-","Kinesin-13 uses the energy of ATP hydrolysis to promote MTs"],"check":{"q":"关于不同驱动蛋白家族的特点，下列叙述正确的是？","o":["A. kinesin-14马达域位于N端，向微管正端行走","B. 大多数驱动蛋白马达域位于重链N端，向微管正端行走","C. kinesin-13促进微管聚合","D. kinesin-5成员以单体形式向微管负端行走"],"a":"B","e":"多数kinesin马达域在重链N端、向微管正端行走；kinesin-14在C端向负端行走，kinesin-13促解聚，kinesin-5形成反向四聚体滑动。","oe":["kinesin-14马达域位于C端，走向微管负端。","多数驱动蛋白马达域位于重链N端并走向正端。","kinesin-13利用ATP水解促进微管解聚。","kinesin-5形成反向四聚体，在两极微管间滑动。"]},"cards":null,"mem":"人45种；N端向+，kinesin13促解聚","big":"assets/img/ch06/big/p048.jpg","summary":"考点：第一节 微管 · 1.6.1 驱动蛋白(kinesin) ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「驱动蛋白特点」的核心内容，能解释其机制、比较相关概念。","intuition":"kinesin 从酵母到人都有同源物，说明它高度保守。"},{"i":48,"sec":"1.6.1 驱动蛋白(kinesin)","title":"kinesin5通过杆状区","notes":"Kinesin-1 was first\npurified from squid\nneurons, and\nsimilar to myosin II.\n域形成反向四聚体，\n在极性相反的两根相\n邻微管间滑动。如纺\n锤体两极微管。\nSelected members of the kinesin superfamily\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.6.1 驱动蛋白(kinesin) ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n• 肌球蛋白（myosin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部能结合肌动蛋白和 ATP。\n\n【本页英文讲解】\n本页介绍驱动蛋白超家族的成员。驱动蛋白-1（kinesin-1）最早从鱿鱼神经元中纯化得到，结构与肌球蛋白II（myosin II）相似。kinesin-5通过杆状区域形成反向四聚体，能在极性相反的两根相邻微管之间滑动，例如纺锤体两极的微管，从而推动纺锤体两极分离。要点是kinesin-5的反向四聚体结构与在纺锤体中的滑动功能，常与有丝分裂考点结合。","page":49,"level":"掌握","img":"assets/img/ch06/p049.jpg","anim":"kinesin5_slide","fig":null,"points":["kinesin-5通过杆状区形成反向四聚体","在极性相反的两根相邻微管间滑动，参与纺锤体两极分离"],"check":{"q":"关于kinesin-5的结构与功能，下列叙述正确的是？","o":["A. 沿微丝向正端移动，参与胞质分裂收缩环的形成","B. 通过切除微管促进纺锤体的解聚","C. 是单体马达蛋白，沿单根微管向正端运输囊泡","D. 通过杆状域形成反向四聚体，在极性相反的两根相邻微管间滑动，推动纺锤体两极分离"],"a":"D","e":"kinesin-5通过杆状域形成反向四聚体，能在极性相反的两根相邻微管间滑动，推动纺锤体两极分离。","oe":["沿微丝正端运动的是肌球蛋白，kinesin-5沿微管运动。","切割微管的是katanin，非kinesin-5。","kinesin-5为双极四聚体，不运输囊泡。","kinesin-5反向四聚体滑动分开纺锤体两极。"]},"cards":null,"mem":"kinesin5反向四聚，滑开纺锤两极","big":"assets/img/ch06/big/p049.jpg","summary":"域形成反向四聚体，","goal":"学完应能掌握并运用「kinesin5通过杆状区」的核心内容，能解释其机制、比较相关概念。","intuition":"kinesin-5 像“撑杆”：形成反向四聚体，在反向平行的微管间滑动，把纺锤体两极推开。"},{"i":49,"sec":"1.6.1 驱动蛋白(kinesin)","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• kinesin-1 —— 驱动蛋白-1\n• kinesin-5 —— 驱动蛋白-5\n• kinesin-13 —— 驱动蛋白-13\n• kinesin-14 —— 驱动蛋白-14\n• mRNA —— 信使RNA\n• KIF5/KIF3/KIF17/KIF1A/KIF4等 —— 驱动蛋白家族成员(KIF 系列)\n• Chromokinesin —— 染色体驱动蛋白\n• Eg5/KLP61F/BimC/Cin8/Kip1/Cut7 —— 双极驱动蛋白-5 同源物\n• KIF2A/2B/2C/KLP10A/KLP59C —— 驱动蛋白-13 家族(促微管解聚)\n• KIFC1/C2/C3 —— 驱动蛋白-14 家族(负端方向)\n【读图讲解】\n表格（驱动蛋白超家族）：kinesin-1 运输膜泡/细胞器/mRNA；kinesin-5 双极四聚体分开纺锤体极、确立极性；kinesin-13 纠正动粒微管错误；kinesin-14 组织纺锤体极。考点：驱动蛋白多数朝微管正端移动，结构决定功能。","page":50,"level":"掌握","img":"assets/img/ch06/p050.jpg","anim":null,"fig":null,"points":["表10-1驱动蛋白家族成员的结构与功能","驱动蛋白家族","分子结构模式图","亚基组成及主要成员","kinesin-1","膜泡、细胞器和mRNA","2条重链和2条轻链，如KIF5，KHC","运输"],"check":{"q":"关于驱动蛋白超家族成员的功能，下列对应正确的是？","o":["A. kinesin-14负责纺锤体极分离，kinesin-5向负端移动","B. kinesin-1运输膜泡、细胞器和mRNA，kinesin-13促微管解聚，kinesin-14向负端移动","C. kinesin-1促微管解聚，kinesin-13运输囊泡，kinesin-5向负端移动","D. 所有驱动蛋白都向微管负端移动运输货物"],"a":"B","e":"驱动蛋白家族成员分工不同：kinesin-1运输膜泡、细胞器和mRNA，kinesin-13促微管解聚，kinesin-14向负端移动并组织纺锤体极。","oe":["分离纺锤体极主要是kinesin-5。","各成员的功能与运动方向均与教材表10-1一致，故正确。","该选项把各驱动蛋白成员的功能相互错配，故错误。","多数驱动蛋白是正端马达，并非都向负端运输货物。"]},"cards":null,"mem":"1运货，5分极，13纠错，14聚极","big":"assets/img/ch06/big/p050.jpg","summary":"KIF5/KIF3/KIF17/KIF1A/KIF4等 —— 驱动蛋白家族成员(KIF 系列)","goal":"学完应能掌握并运用「（本页为图片/无文字层）」的核心内容，能解释其机制、比较相关概念。","intuition":"本页以图展示 kinesin 家族成员。"},{"i":50,"sec":"1.6.1 驱动蛋白(kinesin)","title":"Two kinesin heads (purple)","notes":"bound to MTs.\nKinesin-1 uses ATP to “walk”\ndown a microtubule.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.6.1 驱动蛋白(kinesin) ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n\n【本页英文讲解】\n本页图注说明：两个驱动蛋白头部（kinesin heads，图中紫色）结合在微管（MTs）上；驱动蛋白-1（kinesin-1）利用ATP水解供能，沿微管“行走”（walk）。这体现了驱动蛋白以两个头部交替结合与摆动、逐步移动的机制。理解“两个头部交替迈步、ATP驱动、沿微管定向行走”是本节的关键，属于马达蛋白工作机制的高频考点。","page":51,"level":"掌握","img":"assets/img/ch06/p051.jpg","anim":null,"fig":null,"points":["kinesin-1利用ATP水解供能，沿微管逐步“行走”"],"check":{"q":"驱动蛋白-1(kinesin-1)沿微管\"行走\"的机制是？","o":["A. 不需要能量，靠微管自身解聚推动","B. 整个分子一次性沿微管滚动前进","C. 尾部分解ATP，头部沿微管被动滑动","D. 两个头部交替结合微管并摆动，利用ATP水解供能逐步移动"],"a":"D","e":"kinesin-1的两个头部交替结合微管并摆动，利用ATP水解供能沿微管逐步行走。","oe":["kinesin行走必须水解ATP供能，不能依赖其他能量来源。","其运动是逐步交替迈步，而非整体滚动。","ATP酶活性位于头部，不是尾部。","两头部交替迈步、ATP驱动是其行走机制。"]},"cards":null,"mem":"双头交替，ATP驱动沿微管行走","big":"assets/img/ch06/big/p051.jpg","summary":"考点：第一节 微管 · 1.6.1 驱动蛋白(kinesin) ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「Two kinesin heads (purple)」的核心内容，能解释其机制、比较相关概念。","intuition":"kinesin-1 像“两条腿交替走”：水解 ATP，两头部交替吸附、沿微管迈步。"},{"i":51,"sec":"1.6.1 驱动蛋白(kinesin)","title":"轴","notes":"突\n内\n部\n的\n微\n管\n及\n马\n达\n蛋\n白\n\n【读图讲解】\n本图为电子显微镜照片，显示轴突内部的微管及马达蛋白。画面为黑白高倍放大像，可见神经轴突内密集排列的纤维与颗粒状结构，白色箭头指向沿微管分布、被运输的囊泡/细胞器样物质。轴突内微管平行成束、极性统一，驱动蛋白与胞质动力蛋白等马达蛋白可携载物质沿微管做双向运输。要点：掌握轴突内微管作为“轨道”、马达蛋白作为“搬运工”的轴突运输机制；读图时注意箭头标示的是被转运的物质，而非微管本身。","page":52,"level":"掌握","img":"assets/img/ch06/p052.jpg","anim":null,"fig":null,"points":["轴突内存在微管与马达蛋白，参与轴突内物质运输"],"check":{"q":"轴突内微管与马达蛋白的关系是？","o":["A. 微管平行成束、极性统一，作为轨道供马达蛋白双向运输物质","B. 轴突内只有微丝，没有微管和马达蛋白","C. 微管随机排列，马达蛋白不能定向运输","D. 微管本身收缩产生动力，推动囊泡移动"],"a":"A","e":"轴突内微管平行成束且极性统一，作为轨道供kinesin和dynein等马达蛋白双向运输物质。","oe":["轴突微管极性统一，作为双向运输轨道。","轴突内以微管及各类马达蛋白为主，并非只有微丝。","轴突内微管平行成束且极性统一，故能实现定向运输。","动力来自马达蛋白水解ATP，而非微管收缩。"]},"cards":null,"mem":"轴突微管作轨，马达双向搬运","big":"assets/img/ch06/big/p052.jpg","summary":"本图为电子显微镜照片，显示轴突内部的微管及马达蛋白","goal":"学完应能掌握并运用「轴」的核心内容，能解释其机制、比较相关概念。","intuition":"轴突内的微管与马达像“高速公路和车”：把物质沿长轴突来回运输。"},{"i":52,"sec":"1.6.1 驱动蛋白(kinesin)","title":"Dynein是已知马达蛋白中最大，移","notes":"动速度最快的一员。\n发现的第一个dynein是与鞭毛、纤\n毛运动有关的；\n后来从哺乳动物脑组织中分离到细\n胞质动力蛋白：分子量1.2MD 的多\n亚基蛋白巨大分子复合物。\nDyneins are the largest of the known\nmolecular motors, and they are also\namong the fastest: axonemal dyneins\nattached to a glass slide can move\nmicrotubules at the rate of 14 μm/sec.\n1.6.2 ●细胞质动力蛋白(Cytoplasmic dynein)\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.6.1 驱动蛋白(kinesin) ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n\n【本页英文讲解】\n本页介绍动力蛋白（dynein）：它是已知马达蛋白中最大、移动速度最快的一类。最早发现的dynein与鞭毛、纤毛运动有关；后来从哺乳动物脑组织中分离出细胞质动力蛋白（cytoplasmic dynein），是分子量约1.2 MD的多亚基巨大复合物。轴丝动力蛋白（axonemal dynein）固定在玻片上时能以约14 μm/秒的速率移动微管。掌握dynein的大小、速度与两类区分。","page":53,"level":"掌握","img":"assets/img/ch06/p053.jpg","anim":"dynein_transport","fig":null,"points":["动力蛋白(dynein)是已知最大的马达蛋白，移动速度也最快","最早发现与鞭毛、纤毛运动有关；胞质动力蛋白为1.2MD的巨大复合物"],"check":{"q":"关于动力蛋白(dynein)，下列叙述正确的是？","o":["A. 是分子量约380 kDa的单链蛋白","B. 仅存在于鞭毛、纤毛中，不分布于细胞质","C. 是分子量最小、移动速度最慢的马达蛋白","D. 是已知马达蛋白中最大、移动速度最快的，细胞质动力蛋白约1.2 MD"],"a":"D","e":"dynein是已知马达蛋白中最大、速度最快的一类，细胞质动力蛋白约1.2 MD，为多亚基巨大复合物。","oe":["380 kDa是kinesin，dynein为多亚基复合物。","还有细胞质动力蛋白分布于胞质。","dynein最大最快，该选项将其描述得最小最慢，与事实相反。","原文指出dynein最大最快，约1.2 MD。"]},"cards":null,"mem":"dynein最大最快，胞质者1.2MD","big":"assets/img/ch06/big/p053.jpg","summary":"动速度最快的一员","goal":"学完应能掌握并运用「Dynein是已知马达蛋白中最大，移」的核心内容，能解释其机制、比较相关概念。","intuition":"dynein 像“朝负端的搬运工”：是已知最大、最快的马达蛋白。"},{"i":53,"sec":"1.6.1 驱动蛋白(kinesin)","title":"轴丝动力蛋白(axonemal dynein)","notes":"主要在鞭毛运动中起作用。\ndynein\n3 heavy chains\n2 intermediate chains\nSeveral light chains\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.6.1 驱动蛋白(kinesin) ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n\n【本页英文讲解】\n本页讲鞭毛、纤毛中的轴丝动力蛋白（axonemal dynein），主要在鞭毛运动中起作用。其结构由3条重链（heavy chains）、2条中间链（intermediate chains）和若干条轻链（light chains）组成，是一种多亚基复合物。轴丝动力蛋白通过水解ATP使相邻二联体微管之间发生滑动，从而引起鞭毛、纤毛弯曲。掌握其亚基组成和驱动纤毛/鞭毛运动的功能。","page":54,"level":"掌握","img":"assets/img/ch06/p054.jpg","anim":null,"fig":null,"points":["轴丝动力蛋白(axonemal dynein)主要在鞭毛运动中起作用","含3条重链、2条中间链及若干轻链"],"check":{"q":"鞭毛、纤毛中轴丝动力蛋白(axonemal dynein)的亚基组成是？","o":["A. 2条重链、2条轻链，不含中间链","B. 1条重链、1条中间链、1条轻链","C. 3条重链、2条中间链和若干条轻链","D. 4条重链、2条中间链，不含轻链"],"a":"C","e":"轴丝动力蛋白由3条重链、2条中间链和若干轻链组成，主要在鞭毛运动中驱动相邻二联体滑动。","oe":["该选项遗漏了3条重链且缺少中间链，组成描述不完整。","轴丝动力蛋白的亚基种类与数目均与该选项描述不符。","原文给出3重链、2中间链及数条轻链。","其重链应为3条且含若干轻链，故该选项错误。"]},"cards":null,"mem":"轴丝dynein：3重链2中链多轻链","big":"assets/img/ch06/big/p054.jpg","summary":"主要在鞭毛运动中起作用","goal":"学完应能掌握并运用「轴丝动力蛋白(axonemal dynein)」的核心内容，能解释其机制、比较相关概念。","intuition":"轴丝动力蛋白主要在鞭毛运动中起作用，含重链、中间链和轻链。"},{"i":54,"sec":"1.6.1 驱动蛋白(kinesin)","title":"胞质动力蛋白","notes":"纤毛动力蛋白\n\n【读图讲解】\n本图介绍动力蛋白(dynein)。图(A)为负染电镜照片，分别显示胞质动力蛋白(cytoplasmic dynein)与纤毛动力蛋白(ciliary dynein)，标尺25 nm；纤毛动力蛋白可见两个头部。图(B)为分子模式图：重链(heavy chain)构成motor domain，含stalk，红圈标出MT-binding(微管结合位点)和ATPase(ATP水解酶活性位点)；另有中间链(intermediate chains)和轻链(light chains)。要点：动力蛋白是靠ATP供能、沿微管(-)极运输的马达蛋白，其头部结合微管、尾部结合货物。","page":55,"level":"掌握","img":"assets/img/ch06/p055.jpg","anim":null,"fig":null,"points":["动力蛋白包括胞质动力蛋白与纤毛(轴丝)动力蛋白"],"check":{"q":"关于动力蛋白(dynein)的结构与功能，下列叙述正确的是？","o":["A. 重链构成马达域，含微管结合位点和ATP酶活性位点，沿微管负端运输","B. 不含ATP酶活性，靠微管解聚被动移动","C. 重链构成轨道，轻链水解GTP提供运动动力","D. 头部结合ATP，尾部结合微管，向微管正端运输"],"a":"A","e":"dynein的重链构成马达域，含微管结合位点和ATP酶活性位点，靠ATP供能沿微管负端运输。","oe":["重链含MT结合和ATPase位点，向负端运动。","动力蛋白具ATP酶活性，主动运动。","轻链不水解GTP，供能靠ATP水解。","方向应为负端，且头部结合微管。"]},"cards":null,"mem":"dynein头结合微管，尾带货，向(−)极","big":"assets/img/ch06/big/p055.jpg","summary":"本图介绍动力蛋白(dynein)","goal":"学完应能掌握并运用「胞质动力蛋白」的核心内容，能解释其机制、比较相关概念。","intuition":"dynein 分两种：胞质 dynein 运货，纤毛 dynein 驱动鞭毛摆动。"}],"mcq":[],"judge":[],"fill":[{"id":"ch06_fill_3","modI":7,"q":"构成纺锤体的微管有三种：______、______和 ______ 。","a":"星体微管；动力微管；极性微管","kp":"ch06_s7_51","oe":["星体微管由中心体发出伸向细胞皮层，参与纺锤体定位。","动力微管即连接动粒的微管，牵引染色体向两极移动。","极性微管从两极发出并相互重叠，维持纺锤体的结构。"]},{"id":"ch06_fill_9","modI":7,"q":"纺锤体中与染色体连接的微管有______和______。","a":"染色体微管；中间微管","kp":"ch06_s7_51","oe":["染色体微管即动粒微管，一端附着染色体动粒，牵引其移向两极。","中间微管不直接连动粒，位于纺锤体中部连接两极，维持形态。"]},{"id":"ch06_fill_19","modI":7,"q":"在神经轴突物质转运过程中，有两种马达蛋白介导，一是_________介导运输小泡由轴突 顶端运向胞体；二是_________介导运输小泡由胞体运向轴突顶端。","a":"动力蛋白；驱动蛋白","kp":"ch06_s7_51","oe":["向微管负极运动，将运输小泡从轴突顶端运回胞体。","向微管正极运动，将运输小泡从胞体运向轴突顶端。"]}],"short":[{"id":"ch06_short_8","modI":7,"q":"比较细胞质动力蛋白与驱动蛋白。","a":"（1）两者都是将 ATP 的化学能转化为动能的大的发动机蛋白，都与微管结合在一起， 但只有动力蛋白存在于纤毛和鞭毛的微管之中。 （2）驱动蛋白是通过加末端方式来引导微管的运动，动力蛋白则通过减末端方式来引导微 管运动。 （3）虽然它们在功能上有相似之处，但不是同源蛋白，而且立体结构非常不同。它们并不 属于同一蛋白家族。","kp":"ch06_s7_54"}],"calc":[],"term":[{"id":"ch06_term_1","modI":7,"term":"基粒（basal body）。","def":"基粒（basal body）是指位于鞭毛和纤毛根部，类似于动物细胞中的中心体，呈圆柱状 的微管性结构，平均大小为 0.2～0.5μm。其壁由 9 组微管三联体组成，包括完全微管与不 完全微管。胞质动力蛋白。中心粒和基粒是同源的，在某些时候可以相互转变，且都具有自 我复制能力。","kps":"","kp":"ch06_s7_54"}]},{"i":8,"name":"第一节 微管 · 1.7 微管的功能","slides":[{"i":55,"sec":"1.7.2 细胞内物质运输 (micro","title":"1.7 微管的功能","notes":"1.7.1 维持细胞的形态及细胞器在细胞内的位置－支架\n1.7.2 细胞内物质运输 (microtuble&kinesin/dynein)\n微管可作为高尔基体和其他小泡及颗粒的运输轨道\n1.7.3 鞭毛、纤毛的运动\n1.7.4 纺锤体和染色体运动\n主要由微管和其结合蛋白构成。\n聚合&微管间的相对滑动","page":56,"level":"掌握","img":"assets/img/ch06/p056.jpg","anim":"mt_functions","fig":null,"points":["神经轴突中的蛋白和膜结构的转运;","鱼色素细胞中色素颗粒的运输;","鞭毛、纤毛结构基本相同，轴心含“9+2”排列的平行微管","运动机制: 相邻二联体微管间的相对滑动/dynein","纺锤体, 与细胞分裂和染色体运动直接相关的临时细胞器，","染色体向两极的运动依靠纺锤体微管(spindle MT)的解聚/"],"check":{"q":"关于微管的功能，下列叙述正确的是？","o":["A. 微管不能作为膜泡运输的轨道","B. 鞭毛、纤毛轴心为“9+2”排列，靠相邻二联体相对滑动运动","C. 微管不参与维持细胞形态","D. 染色体向两极运动与纺锤体微管无关"],"a":"B","e":"微管维持细胞形态、作为运输轨道、构成纺锤体并参与鞭毛纤毛运动；鞭毛纤毛轴心呈“9+2”排列。","oe":["微管可作为高尔基体和小泡的运输轨道。","鞭毛、纤毛轴心呈9+2排列，靠二联体滑动运动。","微管是维持细胞形态的重要骨架。","染色体向两极运动依靠纺锤体微管。"]},"cards":null,"mem":"微管四能：支架、运输、纤毛、纺锤","big":"assets/img/ch06/big/p056.jpg","summary":"维持细胞的形态及细胞器在细胞内的位置－支架","goal":"学完应能掌握并运用「1.7 微管的功能」的核心内容，能解释其机制、比较相关概念。","intuition":"微管三大功能：支撑形态、作为运输轨道、参与分裂时染色体运动。"}],"mcq":[],"judge":[{"id":"ch06_judge_7","modI":8,"q":"纤毛的运动是微管收缩的结果。（                ）","a":"错","e":"纤毛的运动是肌动蛋白运动的结果。","kp":"ch06_s8_55","oe":["若判对则误以为纤毛运动靠微管收缩，实际依靠微管滑动及动力蛋白。","纤毛运动源于轴丝二联体微管间的滑动，由动力蛋白臂驱动，非收缩。"]}],"fill":[{"id":"ch06_fill_18","modI":8,"q":"纤毛具有______结构，通过微管上结合的_________分解_______造成微管间的______。","a":"“9＋2”排列的平行微管；ATP 酶；ATP；二联管解聚","kp":"ch06_s8_55","oe":["纤毛轴心为9组二联体围绕2条中央单管，即9+2排列。","二联体A亚管结合有ATP酶（动力蛋白臂），可水解ATP。","动力蛋白臂分解ATP释放能量，为微管滑动提供动力。","相邻二联管相对滑动并部分解聚，使纤毛产生弯曲运动。"]}],"short":[{"id":"ch06_short_13","modI":8,"q":"试分析纤毛不动症发生机制，并以此为例叙述纤毛和鞭毛的运动机制。","a":"（1）纤毛不动症发生机制 纤毛不动症即原发性纤毛运动障碍（PCD），是指纤毛超微结构具有特异的、先天性遗传缺 陷导致的一组疾病。目前认为 PCD 的纤毛异常与内、外动力蛋白臂的缺失或纤毛动力蛋白 臂中 ATP 酶缺乏或代谢异常有关，以致微管滑行缺乏能量，使纤毛摆动受阻。 （2）纤毛和鞭毛的运动机制 纤毛和鞭毛的运动本质是轴丝动力蛋白介导的相邻二联体微管之间的相互滑动。纤毛和鞭毛 摆动的特征是从基体产生滑动，沿着轴丝将弯曲传递到尾部，因此，二联管之间的滑动必须 转换为弯曲运动。当轴丝上任意两点的滑动速率不等时，滑动即可转换为弯曲。 ①滑动速率的差异主要来自维持轴丝结构的连接蛋白，它们在一定程度上限制了二联管的自 由滑动； ②在某一时间某一位置，只有部分动力蛋白臂被激活，激活一半的动力蛋白臂使轴丝朝一边 弯曲，激活另一半则朝另一边弯曲。二条动力蛋白臂的作用不同，内臂产生滑动，导致轴丝 弯曲，而外臂可以加快滑动的速度。","kp":"ch06_s8_55"}],"calc":[],"term":[]},{"i":9,"name":"第一节 微管 · 1.7.1 植物细胞壁中纤维素的定向沉积-微管","slides":[{"i":56,"sec":"1.7.1 植物细胞壁中纤维素的定向沉积","title":"1.7.1 植物细胞壁中纤维素的定向沉积-微管","notes":"胞内微管的排列方向决定了新合成的细胞壁纤维素微纤丝的排列方向，从而影响细胞的生长及形态。","page":57,"level":"掌握","img":"assets/img/ch06/p057.jpg","anim":null,"fig":null,"points":["细胞内微管的排列方向决定新合成细胞壁纤维素微纤丝的排列方向","纤维素定向沉积影响细胞的生长与形态"],"check":{"q":"植物细胞壁中纤维素微纤丝的定向沉积，其排列方向主要由什么决定？","o":["A. 细胞核的朝向","B. 胞内微管的排列方向","C. 高尔基体的位置","D. 微丝的排列方向"],"a":"B","e":"植物细胞内微管的排列方向决定新合成细胞壁纤维素微纤丝的排列方向，进而影响细胞生长与形态。","oe":["细胞核朝向与纤维素沉积无直接因果。","胞内微管排列决定纤维素微纤丝沉积方向。","高尔基体参与壁物质加工，不决定排列方向。","微丝不直接决定纤维素沉积方向。"]},"cards":null,"mem":"皮层微管定纤维素方向，决定形态","big":"assets/img/ch06/big/p057.jpg","summary":"胞内微管的排列方向决定了新合成的细胞壁纤维素微纤丝的排列方向，从而影响细胞的生长及形态","goal":"学完应能掌握并运用「1.7.1 植物细胞壁中纤维素的定向沉积-微管」的核心内容，能解释其机制、比较相关概念。","intuition":"植物细胞壁的纤维素沉积像“照着微管方向铺钢条”：微管排列决定纤维素排列，进而影响细胞形态。"}],"mcq":[],"judge":[],"fill":[],"short":[],"calc":[],"term":[]},{"i":10,"name":"第一节 微管 · 1.7.1 维持细胞内膜性细胞器的空间分布：线粒体、","slides":[{"i":57,"sec":"1.7.1 维持细胞内膜性细胞器的空间分","title":"微管维持膜性细胞器的空间分布","notes":"高尔基体、核糖体等\nEffect of MTs (red) on the Golgi apparatus (green).\nA:对照 as long as the MTs remains intact, Golgi is localized near\nthe centrosome, close to the nucleus.\nB: After exposure to nocodazole, MTs depolymerized, the Golgi\napparatus fragments and is dispersed throughout the cell.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.1 维持细胞内膜性细胞器的空间分布：线粒体、 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页讲微管维持细胞内膜性细胞器的空间分布，如线粒体、高尔基体、核糖体等。图中红色为微管（MTs），绿色为高尔基体。对照（A）：只要微管保持完整，高尔基体就定位在中心体附近、紧靠细胞核；用诺考达唑（nocodazole）处理后（B），微管解聚，高尔基体碎裂并散布到整个细胞中。这证明微管对细胞器定位至关重要，诺考达唑解聚微管是常考实验证据。","page":58,"level":"掌握","img":"assets/img/ch06/p058.jpg","anim":null,"fig":null,"points":["微管维持高尔基体等膜性细胞器的空间分布","诺考达唑(nocodazole)解聚微管后，高尔基体分散、不再定位于核旁"],"check":{"q":"用诺考达唑(nocodazole)处理细胞后，高尔基体出现的变化及原因是？","o":["A. 微管解聚，高尔基体碎裂并散布到整个细胞中","B. 微管解聚，但高尔基体体积增大且位置不变","C. 微丝解聚，高尔基体向细胞边缘移动","D. 微管稳定，高尔基体更紧密聚集于中心体附近"],"a":"A","e":"微管维持膜性细胞器空间分布：微管完整时高尔基体靠近中心体，nocodazole解聚微管后高尔基体碎裂并弥散全细胞。","oe":["nocodazole解聚微管后高尔基体碎裂弥散。","nocodazole处理后高尔基体位置与形态均改变，并非保持不变。","诺考达唑作用于微管而非微丝，故不引起微丝解聚。","nocodazole是解聚剂，并非稳定剂。"]},"cards":null,"mem":"微管完整高尔基聚集，解聚则分散","big":"assets/img/ch06/big/p058.jpg","summary":"高尔基体、核糖体等","goal":"学完应能掌握并运用「微管维持膜性细胞器的空间分布」的核心内容，能解释其机制、比较相关概念。","intuition":"微管像“细胞器的定位轨道”：线粒体、高尔基体等沿微管分布；破坏微管后分布就乱。"}],"mcq":[],"judge":[],"fill":[],"short":[],"calc":[],"term":[]},{"i":11,"name":"第一节 微管 · 1.7.2 物质运输：微管作为运输轨道，马达蛋白提供动","slides":[{"i":58,"sec":"1.7.1 维持细胞内膜性细胞器的空间分","title":"1.7.2 物质运输：微管作为运输轨道，马达蛋白提供动","notes":"A nerve cell:\nvesicles move in\nboth directions\nwithin the axon\n力驱动。\n例如，神经元细胞\n●向外顺向运输(anterograde transport)：在细胞体中\n合成的蛋白等物质，如神经递质、膜向轴突末端的运\n输。 kinesin/MT运向轴突末梢\n●向内逆向运输(retrograde transport)：轴突末梢形成\n的内吞泡向细胞体运输 dynein\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.2 物质运输：微管作为运输轨道，马达蛋白提供动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。","page":59,"level":"掌握","img":"assets/img/ch06/p059.jpg","anim":null,"fig":null,"points":["顺向运输(anterograde)：kinesin驱动，由胞体向轴突末梢","逆向运输(retrograde)：dynein驱动，由轴突末梢向胞体"],"check":{"q":"神经元轴突运输中，顺向运输和逆向运输分别由哪种马达蛋白驱动？","o":["A. 顺向与逆向运输均由kinesin驱动","B. 顺向运输由dynein驱动，逆向运输由kinesin驱动","C. 顺向与逆向运输均由dynein驱动","D. 顺向运输由kinesin驱动，逆向运输由dynein驱动"],"a":"D","e":"轴突运输中，顺向运输（细胞体→轴突末梢）由kinesin驱动，逆向运输（末梢→细胞体）由dynein驱动。","oe":["逆向运输由dynein沿微管负端完成，故顺向由kinesin负责。","该选项把kinesin与dynein对应的运输方向完全颠倒，故错误。","顺向运输由kinesin完成。","顺向靠kinesin，逆向靠dynein。"]},"cards":null,"mem":"顺向kinesin去末梢，逆向dynein回胞体","big":"assets/img/ch06/big/p059.jpg","terms":[{"t":"顺向运输","en":"anterograde transport","d":"沿微管由细胞体向轴突末梢方向的运输，由驱动蛋白驱动。"},{"t":"逆向运输","en":"retrograde transport","d":"沿微管由轴突末梢返回细胞体的运输，由动力蛋白驱动。"}],"summary":"向外顺向运输(anterograde transport)：在细胞体中","goal":"学完应能掌握并运用「1.7.2 物质运输：微管作为运输轨道，马达蛋白提供动」的核心内容，能解释其机制、比较相关概念。","intuition":"微管是“运输轨道”，马达蛋白是“车”：顺向 kinesin、逆向 dynein，沿轴突双向运输。"},{"i":59,"sec":"1.7.1 维持细胞内膜性细胞器的空间分","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• Microtubule —— 微管\n• Vesicle —— 囊泡\n• Kinesin —— 驱动蛋白\n• Kinesin receptor —— 驱动蛋白受体\n• (−) end —— （−）端（负端）\n• (+) end —— （+）端（正端）\n• Stationary microtubule —— 静止的微管\n• Figure 18-20 Molecular Cell Biology 6e —— 图18-20《分子细胞生物学》第6版\n• 0.1 μm —— 0.1 微米（标尺）\n【读图讲解】\n电镜＋示意图：kinesin 经 kinesin receptor 结合囊泡，沿微管由(-)end 走向(+)end。考点：驱动蛋白向微管正端顺向运输，需 ATP 供能。","page":60,"level":"掌握","img":"assets/img/ch06/p060.jpg","anim":null,"fig":null,"points":["(b)","Microtubule","Vesicles","Vesicle","Kinesin","receptor.","Kinesin","(-) end"],"check":{"q":"kinesin经kinesin受体结合囊泡后沿微管运输，其移动方向和能量来源是？","o":["A. 由微管正端走向负端，需GTP供能","B. 由微管负端走向正端，需ATP供能","C. 由微管正端走向负端，需ATP供能","D. 由微管负端走向正端，不需消耗能量"],"a":"B","e":"kinesin经kinesin受体结合囊泡，由微管负端走向正端，需ATP水解供能。","oe":["该选项的移动方向与供能分子GTP均与事实不符。","图示kinesin由(-)端走向(+)端，ATP供能。","kinesin沿微管由负端走向正端，该选项方向写反。","驱动蛋白行走必须水解ATP，不需要微管解聚提供动力。"]},"cards":null,"mem":"kinesin连囊泡，沿微管(−)向(+)","big":"assets/img/ch06/big/p060.jpg","summary":"Figure 18-20 Molecular Cell Biology 6e —— 图18-20《分子细胞生物学》第6版","goal":"学完应能掌握并运用「（本页为图片/无文字层）」的核心内容，能解释其机制、比较相关概念。","intuition":"本页以图展示 kinesin 结合囊泡沿微管运输。"},{"i":60,"sec":"1.7.1 维持细胞内膜性细胞器的空间分","title":"melanophores(黑色素","notes":"Movement of pigment granules: color adjustment\nMake skin\ndarker                                              Skin paler\nMovement of pigment\ngranules in frog\n细胞).\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.2 物质运输：微管作为运输轨道，马达蛋白提供动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页讲色素颗粒运动（movement of pigment granules）与颜色调节（color adjustment）。在蛙的黑色素细胞（melanophores）中，色素颗粒沿细胞骨架定向运输，使皮肤变深（make skin darker）或变浅（skin paler）。颗粒向细胞周边分散时颜色变深，向中心聚集时颜色变浅。这是马达蛋白驱动细胞内运输的直观例证，常用于说明微管/微丝在物质运输中的作用。","page":61,"level":"掌握","img":"assets/img/ch06/p061.jpg","anim":"melanophore","fig":null,"points":["蛙黑色素细胞通过色素颗粒运输进行颜色调节(皮肤变深/变浅)"],"check":{"q":"蛙黑色素细胞中色素颗粒的运输与颜色调节，下列叙述正确的是？","o":["A. 颗粒向中心聚集时皮肤变深，向周边分散时变浅","B. 色素颗粒的运输与细胞骨架无关","C. 颗粒向细胞周边分散时皮肤变深，向中心聚集时变浅","D. 颜色调节仅由色素合成量决定，与颗粒运动无关"],"a":"C","e":"蛙黑色素细胞中色素颗粒向周边分散时皮肤变深、向中心聚集时变浅，是马达蛋白驱动运输的直观例证。","oe":["该选项把颗粒分散与聚集引起的肤色深浅变化写反了。","颗粒运输依赖细胞骨架与马达蛋白。","颗粒向周边分散时肤色变深，向中心聚集时变浅，故正确。","颜色变化由色素颗粒沿细胞骨架运动直接造成，与合成量无关。"]},"cards":null,"mem":"色素颗粒沿微管移，控肤色深浅","big":"assets/img/ch06/big/p061.jpg","terms":[{"t":"黑色素细胞","en":"melanophore","d":"含色素颗粒、通过颗粒聚集或分散改变颜色以调节体色的细胞。"}],"summary":"考点：第一节 微管 · 1.7.2 物质运输：微管作为运输轨道，马达蛋白提供动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「melanophores(黑色素」的核心内容，能解释其机制、比较相关概念。","intuition":"黑色素细胞像“会变色的细胞”：色素颗粒沿骨架运输，分散则变深、聚集则变浅。"},{"i":61,"sec":"1.7.1 维持细胞内膜性细胞器的空间分","title":"对照           突变体","notes":"Expression of a mutant motor protein inhibits the\ndispersion of pigment granules on a pigment cell\n马达蛋白突变体抑制了爪蟾色素细胞中色素颗粒的运输分布。\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.2 物质运输：微管作为运输轨道，马达蛋白提供动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页展示表达突变马达蛋白会抑制色素颗粒在色素细胞中的分散（dispersion）。图中为对照（对照）与突变体（突变体）的对比，原文指出马达蛋白突变体会抑制爪蟾色素细胞中色素颗粒的运输与分布。这说明色素颗粒的正常转运依赖功能性马达蛋白，反过来也用于鉴定参与运输的马达蛋白种类。突变体抑制运输是本节经典实验证据。","page":62,"level":"掌握","img":"assets/img/ch06/p062.jpg","anim":null,"fig":null,"points":["表达突变马达蛋白会抑制爪蟾色素细胞中色素颗粒的分散","说明色素颗粒运输由马达蛋白驱动"],"check":{"q":"表达突变的马达蛋白会抑制爪蟾色素细胞中色素颗粒的分散，这说明？","o":["A. 突变马达蛋白增强了色素颗粒的运输","B. 色素颗粒的分散完全不需要马达蛋白","C. 色素颗粒由微丝驱动，不涉及马达蛋白","D. 色素颗粒的正常转运依赖功能性马达蛋白"],"a":"D","e":"表达突变马达蛋白会抑制色素颗粒的分散，说明色素颗粒的正常转运依赖功能性马达蛋白。","oe":["突变马达蛋白表现为抑制运输，而非增强颗粒的分散。","该说法与突变体抑制颗粒分散的实验现象完全相反。","无论何种骨架，运输都需功能性马达蛋白。","突变马达蛋白抑制分散，证明运输依赖马达蛋白。"]},"cards":null,"mem":"突变马达蛋白，阻色素颗粒分散","big":"assets/img/ch06/big/p062.jpg","summary":"马达蛋白突变体抑制了爪蟾色素细胞中色素颗粒的运输分布","goal":"学完应能掌握并运用「对照           突变体」的核心内容，能解释其机制、比较相关概念。","intuition":"突变马达蛋白会抑制色素颗粒分散，说明运输依赖功能性马达。"}],"mcq":[],"judge":[],"fill":[],"short":[],"calc":[],"term":[]},{"i":12,"name":"第一节 微管 · 1.7.3 鞭毛(flagellae)、纤毛(cilia)运动","slides":[{"i":62,"sec":"1.7.3 鞭毛(flagellae)、","title":"1.7.3 鞭毛(flagellae)、纤毛(cilia)运动","notes":"而推动前进的；\n集体定向运动推动液体流；\n鞭毛、纤毛中的微管骨架属于永久性微管，没有解\n聚、聚合的动态不稳定性。\n鞭毛、纤毛是一种弯曲运动，其动力主要来源\n于轴丝中微管马达蛋白dynein动力臂带动微管\n的滑动。","page":63,"level":"掌握","img":"assets/img/ch06/p063.jpg","anim":null,"fig":null,"points":["原生动物中纤毛虫纲、鞭毛虫纲；","动物精子细胞；","两栖类和哺乳类动物的卵是依靠输卵管内壁上的纤毛运动","动物呼吸系统中气管由具有纤毛的表皮细胞层组成，纤毛"],"check":{"q":"关于鞭毛、纤毛的微管骨架及其运动，下列叙述正确的是？","o":["A. 其微管骨架具有显著的动态不稳定性","B. 运动由肌球蛋白沿微丝滑动驱动","C. 弯曲运动主要靠轴丝中dynein动力臂带动微管滑动","D. 每次运动后微管骨架完全解聚"],"a":"C","e":"鞭毛、纤毛中的微管属永久性微管，无动态不稳定性；其弯曲运动主要来源于轴丝中马达蛋白dynein动力臂带动微管滑动。","oe":["鞭毛纤毛微管为永久性微管，无动态不稳定性。","其运动依赖微管马达蛋白dynein，而非肌球蛋白。","dynein动力臂带动微管滑动产生弯曲运动。","其微管骨架稳定，并不在运动后完全解聚。"],"basis":"动力主要来源于轴丝中微管马达蛋白dynein动力臂带动微管的滑动"},"cards":null,"mem":"纤毛为永久微管，dynein臂滑动致弯曲","big":"assets/img/ch06/big/p063.jpg","summary":"集体定向运动推动液体流；","goal":"学完应能掌握并运用「1.7.3 鞭毛(flagellae)、纤毛(cilia)运动」的核心内容，能解释其机制、比较相关概念。","intuition":"鞭毛/纤毛像“细胞的桨”：由 9+2 轴丝组成，靠 dynein 驱动弯曲摆动。"},{"i":63,"sec":"1.7.3 鞭毛(flagellae)、","title":"真核细胞的纤毛","notes":"气管\n草履虫\n\n【读图讲解】\n本图说明真核细胞的纤毛及结构的统一性。草履虫(Paramecium)靠体表纤毛在池塘水中游动，人体气管上皮细胞的纤毛则向上摆动，清除黏液与碎片。图中取两者各一根纤毛做电镜横切对比，均呈“9+2”排列：外围9组二联体微管环绕中央2根单微管，横切图标尺0.1 μm；草履虫标尺15 μm、气管纤毛标尺5 μm示其尺度。要点：尽管草履虫与人类亲缘极远，纤毛却共有相同微管构筑，体现生命多样性的统一；牢记纤毛横切面的9+2结构。","page":64,"level":"掌握","img":"assets/img/ch06/p064.jpg","anim":null,"fig":null,"points":["真核细胞纤毛横切面微管排列为“9+2”(外9组二联体+中央一对)"],"check":{"q":"真核细胞纤毛横切面的微管排列方式是？","o":["A. 13根原纤维呈纵向平行排列","B. 9组二联体微管，无中央微管","C. 外围9组二联体微管环绕中央2根单微管，即\"9+2\"","D. 外围9组单微管环绕中央2根二联体，即\"9+2\""],"a":"C","e":"真核细胞纤毛轴丝横切呈9+2排列，即外围9组二联体微管环绕中央2根单微管，体现结构的统一性。","oe":["这是微管壁的结构，非纤毛横切。","9+2结构中央为2根单微管，外围才是二联体，故该选项错误。","纤毛轴丝横切为9组二联体加中央2单管。","纤毛横切外围为二联体、中央为单微管，并非无中央微管。"]},"cards":null,"mem":"草履虫与气管纤毛皆9+2","big":"assets/img/ch06/big/p064.jpg","summary":"本图说明真核细胞的纤毛及结构的统一性","goal":"学完应能掌握并运用「真核细胞的纤毛」的核心内容，能解释其机制、比较相关概念。","intuition":"纤毛横切像“9+2 阵列”：外围 9 组二联体、中央 2 根单微管。"},{"i":64,"sec":"1.7.3 鞭毛(flagellae)、","title":"（本页为图片/无文字层）","notes":"【图中英文对照】\n• Cilia —— 纤毛\n• Longitudinal section of cilium —— 纤毛纵切面\n• Cross section of cilium —— 纤毛横切面\n• Transmission electron microscopy (TEM) —— 透射电镜\n• Scanning electron microscopy (SEM) —— 扫描电镜\n• 2 μm —— 2 微米（标尺）\n• TEM text —— TEM 显示标本薄切片剖面；气管细胞的纤毛沿长度切为纵切面、垂直切为横切面\n• SEM text —— SEM 显示标本表面三维图像；气管细胞表面覆盖纤毛突起，黑白电镜图常人工着色\n【读图讲解】\n电镜组图：SEM 示气管上皮表面纤毛三维形态；TEM 示纤毛纵切与横切，横切可见微管成环排列（9+2）。考点：纤毛由微管构成，横切显示 9+2 轴丝。","page":65,"level":"掌握","img":"assets/img/ch06/p065.jpg","anim":null,"fig":null,"points":["tha scan-","Longitudinalsection","Crosssection","ofcilium","ofcilium","Transmissionelectron","specimen.","microscopy (TEM)."],"check":{"q":"观察气管上皮纤毛的纵切面和横切面，最常采用的显微技术是？","o":["A. 普通光学显微镜可直接分辨9+2结构","B. 透射电镜(TEM)显示切面，扫描电镜(SEM)显示表面三维形态","C. 荧光显微镜可清晰显示纤毛内部微管排列","D. 扫描电镜显示切面，透射电镜显示表面形态"],"a":"B","e":"观察纤毛常联合使用电镜：TEM显示纵切与横切面，SEM显示气管上皮表面纤毛的三维形态。","oe":["普通光镜分辨率不足，观察9+2等细节必须借助电镜。","TEM看切面、SEM看表面形态是标准用法。","荧光显微镜不能分辨9+2微管细节。","该选项把TEM与SEM的功能相互颠倒，故叙述错误。"]},"cards":null,"mem":"SEM看表面，TEM横切显9+2","big":"assets/img/ch06/big/p065.jpg","summary":"TEM text —— TEM 显示标本薄切片剖面；气管细胞的纤毛沿长度切为纵切面、垂直切为横切面","goal":"学完应能掌握并运用「（本页为图片/无文字层）」的核心内容，能解释其机制、比较相关概念。","intuition":"本页以电镜图展示纤毛表面与切面，记住 9+2。"},{"i":65,"sec":"1.7.3 鞭毛(flagellae)、","title":"鞭毛(flagellae)、纤毛(cilia)轴心结构组分","notes":"1) “9+2”排列的平行微管\n2中央单体微管 + 9外围二联体微管\n2) 微管马达蛋白－动力蛋白\n(axonemal dynein)\n力臂(dynein arms)同相邻二联体微管\n作用, 使纤毛运动。 3) 微管连接蛋白(nexin): 将相\n邻微管二联体连在一块","page":66,"level":"掌握","img":"assets/img/ch06/p066.jpg","anim":"cilia_9plus2","fig":null,"points":["附着在二联体微管上，伸出动"],"check":{"q":"关于鞭毛、纤毛轴心的结构组分，下列叙述正确的是？","o":["A. 由“9+3”排列的单体微管构成","B. 中央2个单体微管，外围9个二联体微管，动力蛋白臂与连接蛋白连接相邻二联体","C. 中央为2个二联体，外围9个单体微管","D. 微管连接蛋白nexin具有ATP酶活性，驱动滑动"],"a":"B","e":"轴心为“9+2”排列(2中央单体+9外围二联体)，动力蛋白臂水解ATP驱动滑动，nexin将相邻二联体连接。","oe":["轴心为9+2排列，不是9+3。","轴心为2中央单体加9外围二联体，靠两种蛋白连接。","应为中央2个单体微管、外围9个二联体。","nexin仅连接相邻二联体，无ATP酶活性。"]},"cards":null,"mem":"轴丝9+2；dynein力臂，nexin连接","big":"assets/img/ch06/big/p066.jpg","terms":[{"t":"动力蛋白臂","en":"dynein arms","d":"轴丝中连在二联体上、伸向相邻二联体的动力蛋白结构。"},{"t":"微管连接蛋白","en":"nexin","d":"连接相邻二联体的弹性蛋白，使二联体相互滑动转变为弯曲运动。"}],"summary":"中央单体微管 + 9外围二联体微管","goal":"学完应能掌握并运用「鞭毛(flagellae)、纤毛(cilia)轴心结构组分」的核心内容，能解释其机制、比较相关概念。","intuition":"轴丝三要素：9+2 微管、动力蛋白臂(dynein)、连接蛋白(nexin)。"},{"i":66,"sec":"1.7.3 鞭毛(flagellae)、","title":"轴丝动力蛋","notes":"白(axonemal\ndynein)的球\n形头部伸向\n相邻二联体\n的B管。\nLongitudinal\nview of an\naxoneme\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.3 鞭毛(flagellae)、纤毛(cilia)运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n\n【本页英文讲解】\n本页讲轴丝动力蛋白（axonemal dynein）的结构与位置：其球形头部伸向相邻二联体微管的B管，图中给出轴丝（axoneme）的纵切面（longitudinal view）。轴丝动力蛋白一端固定在自己的A管上，头部朝向相邻二联体的B管，水解ATP时试图使相邻二联体相对滑动。由于二联体间存在连接，滑动被转化为弯曲。掌握“头部朝向相邻B管”这一结构特征是理解鞭毛运动的基础。","page":67,"level":"掌握","img":"assets/img/ch06/p067.jpg","anim":null,"fig":null,"points":["轴丝动力蛋白球形头部伸向相邻二联体的B管"],"check":{"q":"关于轴丝动力蛋白(axonemal dynein)的位置，下列叙述正确的是？","o":["A. 一端固定在B管，球状头部伸向自身的A管","B. 一端固定在A管，球状头部伸向相邻二联体的B管","C. 游离于轴丝基质中，不结合任何微管","D. 位于中央微管，连接两根中央单微管"],"a":"B","e":"轴丝动力蛋白一端固定在A管，球状头部伸向相邻二联体的B管，为相邻二联体相对滑动提供动力。","oe":["动力蛋白固定在A管、头部朝B管，该选项固定与朝向均写错。","头部伸向相邻二联体的B管是其结构特征。","轴丝动力蛋白固定于A管并伸向B管，并非游离于基质中。","轴丝动力蛋白位于外周二联体之间。"]},"cards":null,"mem":"轴丝dynein固A管，头朝邻B管","big":"assets/img/ch06/big/p067.jpg","summary":"考点：第一节 微管 · 1.7.3 鞭毛(flagellae)、纤毛(cilia)运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「轴丝动力蛋」的核心内容，能解释其机制、比较相关概念。","intuition":"轴丝动力蛋白像“伸向邻居的手”：一端固定在自己的 A 管、头部伸向相邻 B 管。"},{"i":67,"sec":"1.7.3 鞭毛(flagellae)、","title":"• 是多头的动力蛋白","notes":"ciliary dynein\n纤毛运动机制\n动相邻轴心外围的微管二联体间(outer doublet MTs)\n的相对滑动\nMTs “walk” along the adjacent doublet’s B tubule.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.3 鞭毛(flagellae)、纤毛(cilia)运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n\n【本页讲解】\n本页讲解纤毛（cilium）运动的分子机制，核心是多头动力蛋白——纤毛动力蛋白（ciliary dynein）。它属于动力蛋白臂（dynein arms），基部与A管相连、头部与相邻双联体的B管相连，头部具有ATP结合位点并能水解ATP。机制上，动力蛋白臂水解ATP释放能量，驱动轴心外围相邻的微管二联体（outer doublet MTs）之间相对滑动。考点联系翟中和《细胞生物学》第十章细胞骨架第二节微管功能，注意比较动力蛋白与驱动蛋白（kinesin）。","page":68,"level":"掌握","img":"assets/img/ch06/p068.jpg","anim":null,"fig":null,"points":["基部同A管相连","头部同相邻的B管相连","头部具有ATP结合位点，能够水解ATP。","动力蛋白臂(dynein arms)水解ATP产生能量，驱","The dynein arms on the A tubule of one doublet"],"check":{"q":"关于纤毛动力蛋白(ciliary dynein)的作用机制，下列叙述正确的是？","o":["A. 驱动相邻二联体相互靠拢而非滑动","B. 基部与A管相连，头部与相邻二联体的B管相连，水解ATP驱动相对滑动","C. 头部具有ATP结合位点但不能水解ATP","D. 基部与B管相连，头部与相邻A管相连"],"a":"B","e":"纤毛动力蛋白基部同A管相连、头部同相邻二联体B管相连，水解ATP产生能量，驱动相邻二联体相对滑动。","oe":["其作用是驱动相邻二联体相对滑动。","基部连A管、头部连相邻B管，水解ATP驱动滑动。","动力蛋白头部能结合并水解ATP以提供能量。","基部与A管相连、头部与相邻B管相连。"]},"cards":null,"mem":"dynein基A头B，水解ATP致二联体滑动","big":"assets/img/ch06/big/p068.jpg","summary":"动相邻轴心外围的微管二联体间(outer doublet MTs)","goal":"学完应能掌握并运用「• 是多头的动力蛋白」的核心内容，能解释其机制、比较相关概念。","intuition":"纤毛动力蛋白水解 ATP 驱动相邻二联体相对滑动。"},{"i":68,"sec":"1.7.3 鞭毛(flagellae)、","title":"微管的相对滑动   Microtubule/dynein sliding causes","notes":"cilia/flagella to bend- Crosslinks and\nspokes\n连接蛋白nexin\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.3 鞭毛(flagellae)、纤毛(cilia)运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n\n【本页英文讲解】\n本页讲微管的相对滑动（microtubule/dynein sliding）引起纤毛和鞭毛弯曲。轴丝动力蛋白（dynein）驱动相邻二联体微管相互滑动，但由于二联体之间由连接蛋白（nexin）和放射辐（spokes）等结构限制，滑动不能自由进行，于是被转换成纤毛、鞭毛的弯曲运动。要点是“滑动→受连接蛋白约束→弯曲”这一逻辑链，是纤毛/鞭毛运动机制的核心考点。","page":69,"level":"掌握","img":"assets/img/ch06/p069.jpg","anim":null,"fig":null,"points":["纤毛/鞭毛中微管相对滑动最终转变为弯曲运动","原因是相邻二联体由nexin等连接蛋白交联"],"check":{"q":"纤毛、鞭毛中微管的相对滑动最终转变为弯曲运动，其原因是？","o":["A. 微管本身具有弹性，滑动后自动弯曲","B. 相邻二联体间由nexin等连接蛋白限制，滑动被转换为弯曲","C. 中央微管收缩牵拉所致","D. 动力蛋白不能产生滑动，只能使微管弯曲"],"a":"B","e":"dynein驱动的相邻二联体滑动受nexin等连接蛋白和放射辐限制，滑动被转换为纤毛、鞭毛的弯曲。","oe":["弯曲源于约束而非微管自动变形。","nexin等连接限制滑动，从而转为弯曲。","弯曲与中央微管收缩无因果关系。","动力蛋白确能产生滑动，只是被约束。"]},"cards":null,"mem":"滑动被nexin/辐限制→弯曲","big":"assets/img/ch06/big/p069.jpg","terms":[{"t":"放射辐","en":"radial spokes","d":"轴丝中从中央鞘伸向二联体的结构，参与协调鞭毛/纤毛运动。"}],"summary":"考点：第一节 微管 · 1.7.3 鞭毛(flagellae)、纤毛(cilia)运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「微管的相对滑动   Microtubule/dynein sliding cau」的核心内容，能解释其机制、比较相关概念。","intuition":"鞭毛弯曲像“一排人同时拉绳子”：dynein 想让相邻二联体互相滑动，但二联体被 nexin 等连接蛋白捆住、滑不动，于是整根轴丝只能弯。约束把“滑动”翻译成了“摆动”。"},{"i":69,"sec":"1.7.3 鞭毛(flagellae)、","title":"A 体外：外侧二联体微管及结合的动力蛋白从精子","notes":"鞭毛分离出来然后处于ATP中，由于microtubules与\n其结合的马达蛋白dynein的相互作用，水解ATP，驱\n动微管之间以望远镜拉长的方式自身相互滑动。\nB 体内：在一条完整的鞭毛中，它的外侧二联体微\n管通过易弯曲的蛋白－微管连接蛋白(nexin)连接而相\n互结合在一起，所以整个系统产生的动作是弯曲而不\n是滑动。","page":70,"level":"掌握","img":"assets/img/ch06/p070.jpg","anim":null,"fig":null,"points":["体外：二联体微管与dynein在ATP中相互滑动，呈望远镜式拉长","体内：因nexin交联，整体运动表现为弯曲而非滑动"],"check":{"q":"体外将精子鞭毛外侧二联体微管与dynein置于ATP中，与完整鞭毛内相比，结果是？","o":["A. 体外微管间相互滑动并呈望远镜式拉长，体内因nexin连接而表现为弯曲","B. 体外表现为弯曲，体内表现为滑动","C. 体外和体内均只表现为弯曲","D. 体外和体内均只表现为滑动"],"a":"A","e":"体外分离的二联体微管加dynein与ATP表现为相互滑动，体内因nexin连接而使滑动转为弯曲。","oe":["体外滑动、体内因连接蛋白转为弯曲。","该选项把体外滑动、体内弯曲的表现完全说反了。","体外缺少连接限制，表现为滑动。","体内受nexin约束表现为弯曲。"]},"cards":null,"mem":"体外滑，体内因nexin而弯","big":"assets/img/ch06/big/p070.jpg","summary":"鞭毛分离出来然后处于ATP中，由于microtubules与","goal":"学完应能掌握并运用「A 体外：外侧二联体微管及结合的动力蛋白从精子」的核心内容，能解释其机制、比较相关概念。","intuition":"体外二联体加 dynein+ATP 会相互滑动（望远镜式拉长）；体内因 nexin 交联而变成弯曲。"}],"mcq":[],"judge":[],"fill":[{"id":"ch06_fill_11","modI":12,"q":"构成一根微管的原纤丝有______条。","a":"13","kp":"ch06_s12_68","oe":["微管由13条原纤丝围成中空管状，每条原纤丝由异二聚体纵向排列。"]}],"short":[{"id":"ch06_short_9","modI":12,"q":"列举细菌与动物细胞之间的差别。这些差别很可能是由于在进化过程中出现的部分或所 有现代真核细胞具有的细胞骨架所造成的。","a":"（1）动物细胞相当大，形状多变，而且没有细胞壁，因而需要细胞骨架来支撑并保持 其形状。 （2）动物细胞及其他真核细胞都有细胞核，细胞核靠中间纤维在细胞中成形并维持在适当 的部位。核纤层附着于核被膜的内侧，支持核被膜并使之成形，中间纤维网络包围核并穿行 在细胞质中。 （3）动物细胞可通过改变细胞形状进行移动。这—过程需要肌动蛋白及肌球蛋白的参与。 （4）动物细胞的基因组比细菌大得多，分为许多染色体。细胞分裂时，染色体必须精确地 分配到两个子细胞中。这—过程需要形成有丝分裂纺锤体的微管系统参与。 （5）动物细胞具有胞内细胞器。细胞器在胞内的定位依赖于沿着微管移动的发动机蛋白。 显著的例子是从脊髓到脚部的神经轴突（该轴突可长达 1 m）中，胞内运输小泡（细胞器） 沿着微管的长距离运输。","kp":"ch06_s12_63"},{"id":"ch06_short_10","modI":12,"q":"什么叫凝胶-溶胶（gel-sol）和溶胶-凝胶（sol-gel）转变？","a":"原生动物中的变形虫，高等动物中的巨噬细胞和白细胞等没有鞭毛、纤毛等运动器官， 但能够依靠细胞体的变化进行移动，叫作变形运动。通常要靠胞质环流形成伪足，细胞沿着 伪足形成的方向前进。细胞内流动的细胞质叫作内质，从尾部流向前进中的伪足。当液流到 达伪足时，流动的细胞质分向细胞的两侧，并形成较硬的外质。其间，位于细胞后部的外质 被破坏并向前方提供新的内质，由此产生内质和外质的循环转变，并引起细胞向前移动。细 胞质由坚硬的凝质状态（外质）向可流动的液态（内质）转变的过程称为凝胶-溶胶转变， 相反的过程叫溶胶-凝胶转变。","kp":"ch06_s12_68"}],"calc":[],"term":[]},{"i":13,"name":"第一节 微管 · 1.7.4 染色体运动","slides":[{"i":70,"sec":"1.7.4 染色体运动","title":"1.7.4 染色体运动","notes":"纺锤体(spindle):\n移向细胞两极)直接相关的细胞器；\n地更加活跃。\nLight micrographs of lily endosperm(胚乳) cells\n\n【读图讲解】\n本图讲1.7.4染色体运动与纺锤体。文字给出定义：纺锤体(spindle)是与染色体运动(中期排列于赤道板、后期染色单体分离移向两极)直接相关的细胞器，主要由微管和微管相关蛋白组成；微管的动态不稳定性在有丝分裂期比间期更活跃。下方为百合胚乳(lily endosperm)细胞光镜照片(A、B)，标尺20 μm：A中染色体趋向赤道板，红色纺锤丝连接两极；B为后期，染色体呈V形分向两极。要点：掌握纺锤体的成分、功能及微管动态特性。","page":71,"level":"掌握","img":"assets/img/ch06/p071.jpg","anim":null,"fig":null,"points":["与染色体运动(中期列队赤道板&后期染色单体分离","主要由微管和微管相关蛋白组成。","微管的动态不稳定性在细胞有丝分裂期比间期表现"],"check":{"q":"关于纺锤体与染色体运动，下列叙述正确的是？","o":["A. 染色体向两极运动与微管解聚无关","B. 纺锤体主要由微管和微管相关蛋白构成，其动态不稳定性在分裂期更活跃","C. 纺锤体由微丝和中间纤维构成","D. 纺锤体是永久性细胞器"],"a":"B","e":"纺锤体是与染色体运动直接相关的临时细胞器，主要由微管和微管相关蛋白构成，其动态不稳定性在分裂期更活跃。","oe":["染色体向两极运动依靠纺锤体微管的解聚。","纺锤体以微管为主，分裂期动态变化更活跃。","纺锤体主要由微管和微管相关蛋白构成。","纺锤体是细胞分裂期临时性细胞器。"]},"cards":null,"mem":"纺锤体=微管+MAP，分裂期动态强","big":"assets/img/ch06/big/p071.jpg","summary":"移向细胞两极)直接相关的细胞器；","goal":"学完应能掌握并运用「1.7.4 染色体运动」的核心内容，能解释其机制、比较相关概念。","intuition":"染色体运动像“纺锤体指挥的列队”：中期排赤道板、后期分向两极。"},{"i":71,"sec":"1.7.4 染色体运动","title":"（本页为图片/无文字层）","notes":"本页展示有丝分裂各时相(间期→前期→前中期→中期→后期→末期→胞质分裂)的微管动态变化。\n【图中英文对照】\n• Interphase —— 间期\n• Prophase —— 前期\n• Prometaphase —— 前中期\n• Metaphase —— 中期\n• Anaphase —— 后期\n• Telophase —— 末期\n• Cytokinesis —— 胞质分裂\n• Chromosome duplication and cohesion —— 染色体复制与黏连\n• Centrosome duplication —— 中心体复制\n• Mitotic aster separation —— 有丝分裂星体分离\n• Chromosome condensation —— 染色体凝缩\n• Nuclear envelope breakdown —— 核膜解体\n• Chromosomes aligned at the metaphase plate —— 染色体排列在中期板(赤道板)\n• APC/C activated and cohesins degraded —— APC/C 激活、黏连蛋白降解\n• Anaphase A: chromosome movement to poles —— 后期A：染色体移向两极\n• Anaphase B: spindle pole separation —— 后期B：纺锤体两极分离\n• Nuclear envelope reassembly —— 核膜重新组装\n• Contractile ring forms cleavage furrow —— 收缩环形成卵裂沟\n【读图讲解】\n细胞分裂荧光图＋模式图：Interphase→Prophase→Prometaphase→Metaphase→Anaphase→Telophase→Cytokinesis。关键：纺锤体微管动态组装、染色体排列赤道板、APC/C 激活降解 cohesin、后期 A/B、收缩环形成分裂沟。考点：微管在 M 期的动态变化。","page":72,"level":"掌握","img":"assets/img/ch06/p072.jpg","anim":null,"fig":null,"points":["Interphase","Prophase","Prometaphase","Metaphase","Chromosomeduplication","Breakdownofinterphase","Nuclearenvelope","Chromosomesaligned at"],"check":{"q":"下列有丝分裂事件发生的先后顺序，正确的是？","o":["A. 后期A/B→染色体排列赤道板→APC/C激活→核膜解体","B. 染色体排列赤道板→染色体凝缩→核膜解体→后期A/B","C. 染色体凝缩→核膜解体→染色体排列赤道板→APC/C激活、cohesin降解→后期A/B→核膜重新组装","D. 核膜解体→染色体凝缩→APC/C激活→染色体排列赤道板"],"a":"C","e":"有丝分裂按间期→前期→前中期→中期→后期→末期→胞质分裂依次进行，涉及染色体凝缩、赤道板排列、APC/C激活、后期A/B及核膜重建。","oe":["后期发生在染色体排列赤道板之后，顺序不可能提前。","染色体凝缩属前期事件，应先于核膜解体发生。","该顺序符合前期凝缩到末期核膜重建的标准时序，故正确。","凝缩先于核膜解体，且排序有误。"]},"cards":null,"mem":"前中核膜解，中期列队，后期分离","big":"assets/img/ch06/big/p072.jpg","summary":"本页展示有丝分裂各时相(间期→前期→前中期→中期→后期→末期→胞质分裂)的微管动态变化","goal":"学完应能掌握并运用「（本页为图片/无文字层）」的核心内容，能解释其机制、比较相关概念。","intuition":"本页以图展示有丝分裂各时相的微管变化。"},{"i":72,"sec":"1.7.4 染色体运动","title":"Three classes of MTs of the   ●星体微管(astral microtubles)","notes":"spindle in an animal cell     ●动粒微管(kinetochore MTs)\n●两极微管/极性微管(polar MTs)\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.4 染色体运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页讲动物细胞纺锤体（spindle）中微管的三类：星体微管（astral microtubules）、动粒微管（kinetochore MTs）和两极微管/极性微管（polar MTs）。星体微管由两极伸向细胞皮层，参与纺锤体定位；动粒微管连接着丝粒动粒，负责染色体分离；极性微管在两极间相互重叠并交联，维持纺锤体结构。三类微管的名称、走向与功能对应是本章必考内容。","page":73,"level":"掌握","img":"assets/img/ch06/p073.jpg","anim":"spindle_classes","fig":null,"points":["动物细胞纺锤体微管分三类：星体微管、动粒微管、极性(极间)微管"],"check":{"q":"动物细胞纺锤体微管分为三类，下列描述正确的是？","o":["A. 极性微管、轴丝微管和动粒微管","B. 星体微管、收缩环微管和极性微管","C. 星体微管、动粒微管和极性微管(两极微管)","D. 动粒微管、中间纤维和星体微管"],"a":"C","e":"动物细胞纺锤体微管分三类：星体微管参与定位，动粒微管连接动粒负责染色体分离，极性微管维持纺锤体结构。","oe":["轴丝微管存在于鞭毛纤毛，非纺锤体。","收缩环由微丝构成，非纺锤体微管。","三类即星体微管、动粒微管、极性微管。","中间纤维是独立的骨架系统，不属于纺锤体微管的三类。"]},"cards":null,"mem":"纺锤三类：星体、动粒、极性微管","big":"assets/img/ch06/big/p073.jpg","terms":[{"t":"星体微管","en":"astral MTs","d":"纺锤体中由中心体伸向细胞膜方向的微管。"},{"t":"动粒微管","en":"kinetochore MTs","d":"与染色体动粒相连、牵引染色体的纺锤体微管。"},{"t":"极性微管","en":"polar MTs","d":"从两极伸向赤道方向、相互重叠的纺锤体微管。"}],"summary":"两极微管/极性微管(polar MTs)","goal":"学完应能掌握并运用「Three classes of MTs of the   ●星体微管(astr」的核心内容，能解释其机制、比较相关概念。","intuition":"纺锤体微管分三类：星体微管、动粒微管、极性微管。"},{"i":73,"sec":"1.7.4 染色体运动","title":"微管解聚与聚合——前中期染色体向赤道板聚集","notes":"前中期染色体向细胞中央赤道板（中期板）聚集，是由纺锤体微管调控的。微管正极动态地解聚/延伸（聚合），以“搜索、捕获”染色体动粒，并拉动染色体向中央赤道板移动。这体现了微管的动态不稳定性在染色体整列中的作用。","page":74,"level":"掌握","img":"assets/img/ch06/p074.jpg","anim":"chromosome_congression","fig":null,"points":["前中期染色体向赤道板(中期板)聚集由纺锤体微管调控","微管正极动态解聚/聚合，“搜索-捕获”动粒"],"check":{"q":"前中期染色体向赤道板(中期板)聚集，主要依靠什么调控？","o":["A. 纺锤体微管正极动态地解聚/延伸，搜索并捕获动粒","B. 微丝收缩环的牵引","C. 中间纤维网络的收缩","D. 核纤层的解聚"],"a":"A","e":"染色体向中央赤道板聚集由纺锤体微管调控，微管正极动态解聚/聚合，以“搜索、捕获”染色体动粒并拉动染色体移动。","oe":["纺锤体微管正端动态搜索捕获动粒并牵引染色体。","收缩环参与胞质分裂，不负责赤道板聚集。","中间纤维提供机械支持，不牵引染色体。","核纤层解聚与染色体向赤道板聚集无直接关系。"],"basis":"染色体向细胞中央赤道板聚集过程是由纺锤体微管调控的"},"cards":null,"mem":"微管搜索捕获动粒，拉向赤道板","big":"assets/img/ch06/big/p074.jpg","summary":"前中期染色体向细胞中央赤道板（中期板）聚集，是由纺锤体微管调控的","goal":"学完应能掌握并运用「微管解聚与聚合——前中期染色体向赤道板聚集」的核心内容，能解释其机制、比较相关概念。","intuition":"前中期染色体向赤道板聚集像“微管搜索并抓住动粒”：正端动态解聚/聚合，把染色体拉正。"},{"i":74,"sec":"1.7.4 染色体运动","title":"在染色体移动中，微管正极与动粒牢牢结合，却能在正极通过","notes":"MT de/polymerization\noccur at the exposed“+”\nend while the MTs\nremains attached to the\nkinetochore.\n丢失或获得tubulin来缩短或延长。\nHow\ndepolymerization\nmay pull the\nkinetochore toward\nthe spindle pole.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.4 染色体运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页讲染色体移动中动粒微管的动态：微管的解聚/聚合（de/polymerization）发生在暴露的“正端（+ end）”，而微管另一端仍牢牢连接在动粒（kinetochore）上。原文指出，染色体移动时微管正端与动粒牢固结合，却能在正端通过丢失或获得tubulin来缩短或延长。图示说明解聚如何将动粒拉向纺锤体极。核心是“微管正端解聚拉动物粒”的后期A机制。","page":75,"level":"掌握","img":"assets/img/ch06/p075.jpg","anim":null,"fig":null,"points":["染色体移动中，动粒微管的解聚/聚合发生在暴露的正(+)端","微管与动粒保持连接的同时在正端丢失/获得tubulin"],"check":{"q":"染色体移动中动粒微管的解聚/聚合发生在何处？","o":["A. 动粒微管全长同步地解聚","B. 发生在与动粒相连的微管负端","C. 只发生在微管的中部","D. 发生在暴露的微管正端，而微管仍与动粒相连"],"a":"D","e":"染色体移动时动粒微管的解聚/聚合发生在暴露的正端，而微管另一端仍与动粒牢固相连。","oe":["并非全长同步，而是正端选择性变化。","与动粒相连的一端保持稳定，动态变化发生在暴露的正端。","微管动态发生在暴露的正端，而非全长同步或微管中部。","正端加减、另一端连动粒，是后期A机制。"]},"cards":null,"mem":"微管正端连动粒，解聚拉向极","big":"assets/img/ch06/big/p075.jpg","terms":[{"t":"动粒","en":"kinetochore","d":"染色体着丝粒两侧的蛋白质结构，是纺锤体动粒微管的附着点。"}],"summary":"丢失或获得tubulin来缩短或延长","goal":"学完应能掌握并运用「在染色体移动中，微管正极与动粒牢牢结合，却能在正极通过」的核心内容，能解释其机制、比较相关概念。","intuition":"动粒微管像“一边连着动粒、一边加减亚基”：正端解聚就把染色体拉向极。"},{"i":75,"sec":"1.7.4 染色体运动","title":"●Major motor proteins of the spindle","notes":"The colored arrows indicate the direction of motor movement\nalong a MT-blue toward the minus end, and red toward the plus\nend.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.4 染色体运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 染色体（chromosome）：当细胞进入有丝分裂时，伸展、弥散的丝状染色质高度折叠、盘曲而凝缩成条状或棒状的特殊形态，称为染色体。\n\n【本页英文讲解】\n本页讲纺锤体的主要马达蛋白（major motor proteins of the spindle），它们参与染色体运动。图中彩色箭头标示马达沿微管的运动方向：蓝色箭头表示朝微管负端移动，红色箭头表示朝微管正端移动。也就是说，不同马达蛋白（如kinesin和dynein）在纺锤体上按方向分工，协同完成染色体排列与分离。方向与功能对应是本节考点。","page":76,"level":"掌握","img":"assets/img/ch06/p076.jpg","anim":null,"fig":null,"points":["involved in chromosome movement"],"check":{"q":"纺锤体马达蛋白沿微管运动的方向性表现为？","o":["A. 蓝色箭头表示朝微管正端移动","B. 所有马达蛋白均朝同一方向移动","C. 蓝色箭头朝负端、红色箭头朝正端","D. 红色箭头表示朝微管负端移动"],"a":"C","e":"图中蓝色箭头表示马达朝微管负端移动，红色箭头表示朝正端移动，不同马达按方向分工协同完成染色体运动。","oe":["蓝色箭头表示马达朝微管负端方向移动。","不同马达蛋白在纺锤体上方向不同。","蓝色朝负端、红色朝正端，方向分工明确。","红色箭头表示马达朝微管正端方向移动。"]},"cards":null,"mem":"纺锤马达定向：蓝向−，红向+","big":"assets/img/ch06/big/p076.jpg","summary":"考点：第一节 微管 · 1.7.4 染色体运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「●Major motor proteins of the spindle」的核心内容，能解释其机制、比较相关概念。","intuition":"纺锤体马达蛋白方向不同：蓝箭头朝负端、红箭头朝正端，协同完成分离。"},{"i":76,"sec":"1.7.4 染色体运动","title":"缺失某种马达蛋白对染色体整列的后果","notes":"CK                      missing motor protein\non chromsome\nalignment during\nprometaphase.\nFrog egg extract\nDepleted of a\nparticular kinesin-like\nproein\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.4 染色体运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 驱动蛋白（kinesin）：与微丝运动有关的动力蛋白，分头部、颈部和尾部。头部是产\f生力的活性部位，尾部能与膜泡结合。\n\n【本页英文讲解】\n本页展示缺失某种马达蛋白的后果（consequence of a missing motor protein）：在哺乳动物细胞前中期（prometaphase），染色体无法正常排列（alignment）。实验中用蛙卵提取物（frog egg extract）去除某种类驱动蛋白（kinesin-like protein）后，观察到染色体排列异常。这说明该马达蛋白是纺锤体正常组装与染色体排列所必需的。缺失功能实验是研究马达蛋白功能的常用手段。","page":77,"level":"掌握","img":"assets/img/ch06/p077.jpg","anim":null,"fig":null,"points":["蛙卵提取物去除某种类驱动蛋白后，前中期染色体整列异常","说明该马达蛋白参与染色体整列"],"check":{"q":"用蛙卵提取物去除某种类驱动蛋白(kinesin-like protein)后，前中期出现的结果是？","o":["A. 染色体无法正常排列，说明该马达蛋白为染色体排列所必需","B. 细胞直接进入后期，跳过前中期","C. 染色体排列完全正常，无任何影响","D. 纺锤体消失，微管无法成核"],"a":"A","e":"去除某种类驱动蛋白后染色体无法正常排列，说明该马达蛋白是纺锤体组装与染色体排列所必需。","oe":["缺失后染色体排列异常，证明其必需。","该实验只显示染色体排列异常，并未显示跳过前中期。","去除该马达蛋白后染色体排列异常，与此说法恰好相反。","去除的是马达蛋白，不影响成核。"]},"cards":null,"mem":"缺kinesin样蛋白，染色体排列乱","big":"assets/img/ch06/big/p077.jpg","summary":"考点：第一节 微管 · 1.7.4 染色体运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「缺失某种马达蛋白对染色体整列的后果」的核心内容，能解释其机制、比较相关概念。","intuition":"去掉某种类驱动蛋白后染色体排列异常，说明它对整列必需。"},{"i":77,"sec":"1.7.4 染色体运动","title":"后期A: 染色                后期B：两","notes":"Separate daughter chromosomes at\nanaphase in the mammalian cell\n体向两极运动                 极分离运动\n【结合课本/笔记】后期(anaphase)◆排列在赤道面上的染色体的姐妹染色单体分离产生向极运动◆后期(anaphase)大致可以划分为连续的两个阶段，即后期A和后期B·后期A，动粒微管去装配变短，染色体产生两极运动·后期B，极间微管长度增加，两极之间的距离逐渐拉长，介导染色体向极运动\n\n【本页英文讲解】\n本页讲哺乳动物细胞有丝分裂后期的染色体分离，分为两个阶段：后期A（anaphase A）是染色体向两极运动，即动粒微管解聚把染色体拉向两极；后期B（anaphase B）是两极分离运动，即纺锤体两极相互远离。二者协同完成染色体向子细胞的分配。区分后期A与后期B的运动主体（染色体 vs 两极）是高频考点。","page":78,"level":"掌握","img":"assets/img/ch06/p078.jpg","anim":"anaphase_AB","fig":null,"points":["后期A：姐妹染色单体向两极运动","后期B：纺锤体两极相互分离"],"check":{"q":"关于有丝分裂后期A和后期B，下列叙述正确的是？","o":["A. 后期A两极分离，后期B染色体移向两极","B. 后期A和B均只表现为两极分离","C. 后期A动粒微管去装配变短使染色体移向两极，后期B极间微管延长使两极分离","D. 后期A染色体移向两极，后期B染色体继续移向两极"],"a":"C","e":"后期A动粒微管去装配变短，染色体移向两极；后期B极间微管延长，两极距离拉大。","oe":["该选项把后期A与后期B各自的运动主体相互颠倒，故错误。","后期A以动粒微管变短、染色体向极运动为主，而非两极分离。","后期A动粒微管变短、后期B极间微管延长。","后期B是两极分离，非染色体继续向极。"]},"cards":null,"mem":"后期A管缩拉染色体，B管延长分两极","big":"assets/img/ch06/big/p078.jpg","summary":"体向两极运动                 极分离运动","goal":"学完应能掌握并运用「后期A: 染色                后期B：两」的核心内容，能解释其机制、比较相关概念。","intuition":"后期像“两段接力”：后期A 动粒微管变短，把染色体拉向两极；后期B 极间微管伸长滑动，把两极推开。前者拉货，后者撑场。"},{"i":78,"sec":"1.7.4 染色体运动","title":"A model of motor protein in anaphase B","notes":"【结合课本/笔记】肌肉收缩系统中的有关蛋白①肌球蛋白(myosin)—所有actin-dependent motor proteins都属于该家族，其头部具ATP酶活力,沿微丝从负极到正极进行运动。·Myosin Ⅱ主要分布于肌细胞，有两个球形头部结构域(具有ATPase活性)和尾部链,多个Myosin尾部相互缠绕，形成myosin filament,即粗肌丝。②原肌球蛋白(tropomyosin, Tm)由两条平行的多肽链形成α-螺旋构型,位于肌动蛋白螺旋沟内,结合于细丝, 调节肌动蛋白与肌球蛋白头部的结合。③肌钙蛋白 (Troponin, Tn)为复合物，包括三个亚基：TnC(Ca2+敏感性蛋白)能特异与Ca2+结合; TnT(与原肌球蛋白结合)\n\n【本页英文讲解】\n本页给出后期B（anaphase B）中马达蛋白作用的模型（model of motor protein in anaphase B）。后期B是纺锤体两极分离的过程，一般认为由两类机制共同驱动：极性微管之间的马达蛋白（如kinesin-5）滑动，将两极推开；同时星体微管在细胞皮层处受力，协助两极分离。原文仅给出标题与模型图，重点掌握“马达蛋白驱动两极分离”这一核心结论。","page":79,"level":"掌握","img":"assets/img/ch06/p079.jpg","anim":null,"fig":null,"points":["后期B两极分离机制模型：极微管聚合加长并在重叠区滑动"],"check":{"q":"关于后期B(anaphase B)纺锤体两极分离的机制，目前认为主要是？","o":["A. 动粒微管解聚将染色体拉向两极","B. 微丝收缩环收缩产生拉力","C. 中心体主动沿微管行走以拉开距离","D. 极性微管间马达蛋白(如kinesin-5)滑动推开两极，并辅助星体微管在细胞皮层受力"],"a":"D","e":"后期B两极分离主要由极性微管间马达蛋白滑动推开两极，并辅以星体微管在细胞皮层受力完成。","oe":["动粒微管解聚拉染色体是后期A的机制，与后期B无关。","收缩环参与胞质分裂，不介导两极分离。","中心体本身不是沿微管行走的马达。","极性微管滑动加星体微管受力共同拉开两极。"]},"cards":null,"mem":"kinesin5滑极微管，推两极分开","big":"assets/img/ch06/big/p079.jpg","summary":"肌肉收缩系统中的有关蛋白①肌球蛋白(myosin)—所有actin-dependent motor proteins都属于该家族，其头部具ATP酶活力,沿微丝从负极到正极进行运动","goal":"学完应能掌握并运用「A model of motor protein in anaphase B」的核心内容，能解释其机制、比较相关概念。","intuition":"后期 B 像“两根微管互相顶开”：极微管间马达滑动、把两极推开。"},{"i":79,"sec":"1.7.4 染色体运动","title":"⎯Both microtubule-depolymerizing drugs (such as vinblastine)","notes":"and microtubule-polymerizing drugs (such as taxol)\npreferentially kill dividing cells, since“ both MT\nassembly and disassembly are crucial for correct\nfunction of the mitotic spindle”.\nin a human patient, although not without toxicity to rapidly\ndividing normal cells, including those in the bone marrow\n(骨髓), intestine (肠), and hair follicles (毛囊)..\nof the breast and lung, and it is frequently successful in\ntreatment of tumors that are resistant to other chemotherapeutic\nagents.\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.4 染色体运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 纺锤体（mitotic spindle）：有丝分裂前期，中心粒分别移向细胞两级，微管加速聚合，形成纺锤形结构，称为纺锤体。\n\n【本页英文讲解】\n本页讲微管药物与癌症化疗：解聚微管的药物（如长春碱 vinblastine）和稳定/促聚合微管的药物（如紫杉醇 taxol）都优先杀死分裂中的细胞，因为微管的组装与解聚对纺锤体正常功能都至关重要。这些药可有效杀伤某些肿瘤细胞，但对骨髓（bone marrow）、肠（intestine）和毛囊（hair follicles）等快速分裂的正常细胞有毒性。紫杉醇常用于治疗乳腺癌和肺癌，对其他化疗耐药的肿瘤也常有效。","page":80,"level":"掌握","img":"assets/img/ch06/p080.jpg","anim":null,"fig":null,"points":["These drugs efficiently kill certain types of tumor cells","Taxol in particular has been widely used to treat cancers"],"check":{"q":"长春碱(vinblastine)与紫杉醇(taxol)作用相反，却都能用于癌症化疗，原因是？","o":["A. 二者都抑制DNA复制","B. 二者都阻断核糖体翻译","C. 二者都优先杀死分裂细胞，因微管组装与解聚对纺锤体功能都关键","D. 二者只杀死不分裂的细胞"],"a":"C","e":"解聚微管药(长春碱)与稳定/促聚合微管药(紫杉醇)都优先杀死分裂细胞，因为微管的组装与解聚对纺锤体的正常功能都至关重要。","oe":["二者作用于微管，并不抑制DNA复制。","长春碱与紫杉醇作用于微管，并不阻断核糖体翻译。","微管组装与解聚均影响纺锤体，故都杀伤分裂细胞。","它们优先杀伤快速分裂的细胞，而非不分裂细胞。"],"basis":"微管组装与解聚对纺锤体正常功能都至关重要"},"cards":null,"mem":"长春花碱/紫杉醇皆优先杀分裂细胞","big":"assets/img/ch06/big/p080.jpg","summary":"考点：第一节 微管 · 1.7.4 染色体运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）","goal":"学完应能掌握并运用「⎯Both microtubule-depolymerizing drugs (」的核心内容，能解释其机制、比较相关概念。","intuition":"长春碱（解聚）与紫杉醇（稳定）作用相反却都抗癌：都优先杀伤依赖纺锤体的分裂细胞。"},{"i":80,"sec":"1.7.4 染色体运动","title":"哺乳动物小肠上皮细胞的更新和干细胞增殖","notes":"【结合课本/笔记】二、细胞在体内条件下的衰老●在机体内，细胞的衰老和死亡是常见的现象，甚至在个体发育的早期也会发生;●正常情况下终生保持分裂的细胞，其分裂能力是否随着有机体年龄的增高而下降？它们 会不会衰老？◆衰老动物体内，细胞分裂速度显著减慢，其原因主要是G1期明显延长;◆衰老个体内的环境因素影响了细胞的增殖和衰老;◆骨髓干细胞移植实验说明随着年龄的增加，干细胞增殖速度也趋缓慢.","page":81,"level":"掌握","img":"assets/img/ch06/p081.jpg","anim":null,"fig":null,"points":["哺乳动物小肠上皮细胞不断更新，体现机体细胞的更新与衰老"],"check":{"q":"关于机体内细胞的衰老，下列叙述正确的是？","o":["A. 干细胞增殖速度随年龄增加而加快","B. 细胞衰老与机体内环境因素无关","C. 衰老动物体内细胞分裂速度减慢，主要因G1期明显延长","D. 衰老动物体内细胞分裂速度加快，G1期缩短"],"a":"C","e":"在机体内细胞衰老常见，衰老个体细胞分裂减慢主要因G1期延长，且内环境影响干细胞增殖速度。","oe":["随年龄增加，干细胞增殖速度逐渐趋缓，而非加快。","衰老个体内环境影响细胞增殖与衰老。","原文指出衰老个体分裂减慢，G1期延长。","衰老个体细胞分裂减慢而非加快，该选项与事实相反。"]},"cards":null,"mem":"衰老分裂慢，G1延长，干细胞增殖降","big":"assets/img/ch06/big/p081.jpg","summary":"二、细胞在体内条件下的衰老●在机体内，细胞的衰老和死亡是常见的现象，甚至在个体发育的早期也会发生;●正常情况下终生保持分裂的细胞，其分裂能力是否随着有机体年龄的增高而下降","goal":"学完应能掌握并运用「哺乳动物小肠上皮细胞的更新和干细胞增殖」的核心内容，能解释其机制、比较相关概念。","intuition":"小肠上皮不断更新，体现体内细胞的更新与衰老（G1 延长使衰老细胞分裂变慢）。"},{"i":81,"sec":"1.7.4 染色体运动","title":"are continuously renewed throughout life. 皮肤和毛发","notes":"The skin and hair are exposed to a harsh external\nenvironment-including UV radiation from sunlight-and\n在整个生命周期中是持续更新的。\nThe stem cells干细胞 responsible for producing\nhair reside in a region of the hair follicle(毛囊)\ncalled the bulge.\nThe bulge stem cells give rise to transit-\namplifying matrix cells(毛基质细胞), which\nproliferate and differentiate to form the hair\nshaft(毛干).\n【中文讲解·对照课本/考点】\n考点：第一节 微管 · 1.7.4 染色体运动 ｜ 教材：第十章 细胞骨架 · 第二节 微管及其功能（教材 p206–220）\n• 的一体化网络结构。狭义：指细胞质骨架，位于细胞质中，由微丝、微管、中间纤维构成纤维型的网络结构。弥散性、整体性、变动性共同特点：由蛋白质亚基构成的线性多聚体、动态，可组装和去组装、高度保守微管       （中心粒、鞭毛、纤毛、纺锤体）由 13 根原纤维呈纵向平行排列而成微管蛋白(tubulin)：α 微管蛋白、β 微管蛋白（结合 GTP，可水解为 GDP）聚                              原纤维                    微管异二聚体\n\n【本页英文讲解】\n本页讲皮肤和毛发（skin and hair）在整个生命周期中持续更新。皮肤与毛发暴露于包括阳光紫外线（UV）在内的恶劣外界环境。负责产生毛发的干细胞（stem cells）位于毛囊（hair follicle）中一个称为隆突（bulge）的区域；隆突干细胞产生短暂扩增的毛基质细胞（transit-amplifying matrix cells），后者增殖并分化形成毛干（hair shaft）。要点是毛发干细胞的定位与分化谱系。","page":82,"level":"掌握","img":"assets/img/ch06/p082.jpg","anim":null,"fig":null,"points":["负责产生毛发的干细胞位于毛囊的隆突(bulge)区","皮肤和毛发在生命周期中持续更新"],"check":{"q":"负责产生毛发的干细胞位于毛囊的哪个区域？","o":["A. 毛球(matrix)","B. 毛乳头(dermal papilla)","C. 隆突(bulge)","D. 毛干(shaft)"],"a":"C","e":"毛囊隆突区的干细胞产生短暂扩增的毛基质细胞，后者增殖分化形成毛干。","oe":["毛基质细胞由干细胞产生，本身非干细胞。","毛乳头是间充质结构，非干细胞所在。","毛囊隆突区是毛发干细胞的所在地。","毛干是分化后的结构，不含干细胞。"]},"cards":null,"mem":"毛囊bulge干细胞→毛基质→毛干","big":"assets/img/ch06/big/p082.jpg","summary":"在整个生命周期中是持续更新的","goal":"学完应能掌握并运用「are continuously renewed throughout life」的核心内容，能解释其机制、比较相关概念。","intuition":"皮肤和毛发终生更新：毛囊隆突处的干细胞产生毛发。"}],"mcq":[],"judge":[],"fill":[],"short":[{"id":"ch06_short_6","modI":13,"q":"由神经冲动诱发的肌肉收缩基本过程分哪几步？","a":"由神经冲动诱发的肌肉收缩基本过程可以分为：（1）动作电位的产生；（2）Ca2 的释 ＋   放；（3）原肌球蛋白位移；（4）肌动蛋白丝与肌球蛋白丝的相对滑动；（5）Ca2 的回收。 ＋","kp":"ch06_s13_78"}],"calc":[{"id":"ch06_calc_6","modI":13,"q":"如何理解细胞骨架的动态不稳定性？这一现象与细胞生命活动过程有什么关系？","a":"（1）细胞骨架的动态不稳定性的理解 ①细胞骨架的动态不稳定性是指骨架纤维的持续组装与去组装，通过蛋白亚基的添加和解聚 实现骨架长度的延长或缩短。 ②细胞骨架是一种高度动态的结构体系，细胞的运动是通过肌动蛋白的聚合与解聚完成的。 ③在细胞周期的不同时相，细胞骨架具有完全不同的分布状态。间期微丝、微管分布在细胞 质中，中间丝在细胞质和细胞核均有分布。分裂期时，细胞质中的微管迅速解体，用于纺锤 体微管的延长，牵拉染色体运动；微丝解聚，在细胞赤道板分裂沟部位组装成胞质分裂环， 实现胞质分离；细胞内的中间丝解体，游离在细胞质中。分裂末期，这一过程逆向转变。 （2）细胞骨架的动态不稳定性与细胞生命活动过程的关系 ①在细胞周期中，细胞内的微管经历着动态组装和去组装，在间期和分裂期，其分布或组织 形式存在很大的差异； ②胞质环流和细胞的运动或迁移需要凝胶态与溶胶态的互变； ③细胞的分裂需要纺锤体的组装与解聚； ④细胞核的消失与重新形成也涉及核纤层结构的动态不稳定性； ⑤踏车行为改变了微管或微丝在细胞中分布的部位，可能与细胞的移动有关。","kp":"ch06_s13_70"}],"term":[{"id":"ch06_term_2","modI":13,"term":"肌原纤维（myofrbrils）。","def":"肌原纤维（myofrbrils）是指肌纤维中许多纵行的，直径约 1μm 的圆筒状的微细结构， 与肌肉的收缩有直接关系。骨骼肌的肌原纤维的单位是肌节，藉 Z 线隔开，其中间有 A 带， 两侧有 I 带，明-暗重复单位是肌肉收缩和舒张最基本的功能单位。","kps":"","kp":"ch06_s13_78"}]},{"i":14,"name":"第一节 微管 · 1.7.5 细胞信号转导","slides":[{"i":82,"sec":"1.7.5 细胞信号转导","title":"1.7.5 细胞信号转导","notes":"力、震动、膨压的感受(sensor)\n细胞骨架       ⎯离子通道活性调节；\n细胞凋亡等\n【结合课本/笔记】总趋势●细胞生物学与分子生物学(包括分子遗传学与生物化学) 相互渗透与交融是总的发展趋势。重点领域●染色体DNA与蛋白质相互作用关系—主要是非组蛋白对基因组的作用●细胞增殖、分化、凋亡的相互关系及其调控●细胞信号转导的研究●细胞结构体系的组装","page":83,"level":"掌握","img":"assets/img/ch06/p083.jpg","anim":null,"fig":null,"points":["骨架蛋白对机械刺激，如压","信号分子的细胞定位；","信号分子向核的运输；"],"check":{"q":"关于细胞骨架在细胞信号转导中的作用，下列叙述正确的是？","o":["A. 骨架蛋白可感受机械刺激并调节离子通道活性","B. 信号分子向核运输与骨架无关","C. 细胞骨架不参与信号分子的细胞定位","D. 细胞骨架与细胞凋亡无关"],"a":"A","e":"骨架蛋白可感受压力、震动、膨压等机械刺激，调节离子通道活性，并参与信号分子定位、向核运输及细胞凋亡。","oe":["骨架蛋白可感受机械刺激并调节离子通道活性。","信号分子向核运输与细胞骨架有关。","细胞骨架参与信号分子的细胞定位。","细胞骨架也参与细胞凋亡等过程的调控。"]},"cards":null,"mem":"骨架感机械，调离子通道，送信号入核","big":"assets/img/ch06/big/p083.jpg","summary":"力、震动、膨压的感受(sensor)","goal":"学完应能掌握并运用「1.7.5 细胞信号转导」的核心内容，能解释其机制、比较相关概念。","intuition":"本节讲微管与信号转导的联系，涉及膨压感受等。"}],"mcq":[],"judge":[],"fill":[],"short":[],"calc":[{"id":"ch06_calc_5","modI":14,"q":"为什么说细胞骨架是细胞结构和功能的组织者？细胞内一些细胞器和生物大分子的不对 称分布有什么意义？","a":"（1）细胞骨架是细胞结构和功能的组织者的原因 ①细胞骨架形成了细胞的多种结构：微管能形成鞭毛、纤毛、基体和中心体等结构，微丝参 与微绒毛、收缩环、应力纤维、黏着斑和黏着带的形成，中间丝对维持细胞核的形态和形成 桥粒等具有重要的作用； ②细胞骨架在细胞形态发生和维持等方面具有重要的作用； ③细胞骨架在物质运输、信号传递、细胞运动、细胞分裂等活动中具有重要的作用。 （2）细胞内一些细胞器和生物大分子不对称分布的意义 ①细胞内一些细胞器和生物大分子的不对称分布与细胞不同结构或部分具有特定的功能是 相互联系的，这种不对称分布与细胞骨架的组织方式有关； ②神经细胞中的轴突和树突具有大量的胞质骨架，这与轴突和树突形态的维持及物质的定向 运输有关； ③桥粒、半桥粒、黏着斑和黏着带含有丰富的细胞质骨架结构，这与锚定连接的形成有关； ④细胞内一些细胞器和生物大分子的不对称分布特点是与细胞特定结构的功能相一致的。","kp":"ch06_s14_82"}],"term":[]}],"mcq":[{"id":"ch06_mcq_1","mod":"1.3 MTOC and orienta","modI":4,"q":"由微管组成的细胞表面特化结构是（            ）。","o":["A．鞭毛","B．微绒毛","C．伪足","D．桥粒与半桥粒"],"a":"A","e":"纤毛和鞭毛是细胞表面的特化结构，具有运动功能。纤毛和鞭毛的轴心有一束“9 ＋2”排列的平行微管。","kp":"ch06_s12_0","oe":["正确。鞭毛由微管组成，轴心为9+2排列的平行微管束。","错误。微绒毛由微丝构成，不是由微管组成。","错误。伪足由微丝构成，参与细胞的变形运动。","错误。桥粒与半桥粒是细胞连接，非微管组成的结构。"]},{"id":"ch06_mcq_2","mod":"一、微管","modI":2,"q":"具有稳定微管的结构特异性药物是（            ）。","o":["A．秋水仙素","B．细胞松弛素","C．鬼笔环肽","D．紫杉酚"],"a":"D","e":"紫杉酚能促进微管的装配，并使已形成的微管稳定，但这种稳定性的增加对细胞是 有害的。","kp":"ch06_s5_0","oe":["错误。秋水仙素抑制微管聚合，是解聚剂而非稳定剂。","错误。细胞松弛素破坏微丝，不是微管的稳定药物。","错误。鬼笔环肽稳定微丝，与微管无关。","正确。紫杉酚促进微管装配并使已形成的微管稳定。"]},{"id":"ch06_mcq_3","mod":"一、微管","modI":2,"q":"微管蛋白在一定条件下，能装配成微管，其管壁由几根原纤维构成？（           ）","o":["A．9","B．11","C．13","D．15"],"a":"C","e":"在微管装配的过程中，αβ二聚体形成后，再形成原纤维（protofilament），经过侧 面增加而扩展为片层，至 13 根原纤维时，即合拢形成一段微管。","kp":"ch06_s2_2","oe":["错误。9不是微管管壁原纤维数，9为纤毛二联体等结构数目。","错误。11不是微管管壁的原纤维数目。","正确。13根原纤维合拢形成微管，构成其管壁。","错误。15不是微管管壁的原纤维数目。"]},{"id":"ch06_mcq_4","mod":"1.4 微管特异性药物","modI":5,"q":"促进微管聚合的药物是（         ）。","o":["A．鬼臼素","B．长春花碱","C．紫杉酚","D．细胞松弛素"],"a":"C","e":"A 项，鬼臼素（peltatin）会抑制细胞 DNA 合成，使细胞处于分裂期。B 项，长春 花碱与秋水仙素的作用相似，能抑制微管的装配，是微管的特异性抑制剂。C 项，紫杉酚和 重水（D2O）可使微管稳定性增加并使细胞周期停止于有丝分裂期。D 项，细胞松弛素可以 切断微丝，并结合在微丝正极阻抑肌动蛋白聚合，而可以破坏微丝的三维网络，特异性的抑 制微丝的装配。","kp":"ch06_s5_0","oe":["错误。鬼臼素抑制DNA合成，使细胞处于分裂期，非促微管聚合。","错误。长春花碱抑制微管装配，为微管解聚剂。","正确。紫杉酚和重水使微管稳定性增加，促进微管聚合。","错误。细胞松弛素特异性抑制微丝的装配。"]},{"id":"ch06_mcq_5","mod":"1.3 MTOC and orienta","modI":4,"q":"纤毛、鞭毛的基体由下列哪种微管构成（         ）。","o":["A．二联管","B．三联管","C．单管","D．四联管"],"a":"A","e":"中心粒是三联管。","kp":"ch06_s12_3","oe":["正确。纤毛、鞭毛的轴心为9+2排列，其组成微管是二联管。","错误。三联管是中心粒(及基体)的结构，不同于二联管。","错误。单管是细胞质中的普通微管，不是纤毛鞭毛的微管。","错误。细胞内并不存在四联管这样的微管结构。"]},{"id":"ch06_mcq_6","mod":"绪论 · 概览","modI":0,"q":"凝胶与溶胶的互变与（       ）的变化有关。","o":["A．微丝","B．微管","C．中间丝","D．胶原纤维"],"a":"A","e":"微丝与细胞伪足的形成与迁移运动有关。","kp":"ch06_s0_0","oe":["正确。凝胶与溶胶的互变与微丝的解聚和聚合有关。","错误。微管主要参与运输和染色体运动，与此无直接关系。","错误。中间丝主要起机械支撑作用，不参与溶胶凝胶互变。","错误。胶原纤维是细胞外基质成分，与胞质胶凝无关。"]},{"id":"ch06_mcq_7","mod":"一、微管","modI":2,"q":"微管蛋白的异二聚体上具有哪种核苷酸的结合位点？（             ）[厦门大学 2011 研]","o":["A．GDP","B．ADP","C．GTP","D．ATP"],"a":"C","e":"在α/β-微管蛋白二聚体中，α-微管蛋白上有一个 GTP 结合位点，结合在该位点上的 GTP 通常不会被水解，被称为不可交换位点；β-微管蛋白上也有一个 GTP 结合位点，该 GTP 在微管蛋白二聚体参与组装成微管后即被水解成 GDP，因此β-微管蛋白上的 GTP 结合位点 是可交换位点。","kp":"ch06_s2_7","oe":["GDP是β亚基GTP水解后的产物，并非微管蛋白结合位点直接结合的核苷酸。","ADP是腺嘌呤核苷酸，微管蛋白上不存在ADP的结合位点。","正确——α、β微管蛋白各有一个GTP结合位点，故异二聚体含GTP位点。","ATP是肌动蛋白结合的核苷酸，微管蛋白不结合ATP。"]}],"judge":[{"id":"ch06_judge_1","modI":4,"q":"通常微管的负端埋在中心体中，而正端只能加长，不能缩短，所以能保证微管的稳定。 （   ）","a":"错","e":"微管的负端埋在中心体中，但正端是可以加长的。","kp":"ch06_s4_3","oe":["若判对则误认为正端不能解聚，实际微管正端既可加长也可缩短。","微管具动态不稳定性，正端既能加长也能缩短，并非只加长而稳定。"]},{"id":"ch06_judge_2","modI":4,"q":"在动物细胞中，中心体是主要的微管组织中心。（            ）","a":"对","e":"纺锤体微管和胞质微管由中心体基质囊多个γ管蛋白形成的环状核心放射出来。","kp":"ch06_s4_2","oe":["动物细胞中中心体是主要微管组织中心，γ管蛋白环形核心向外发出微管。","误判为错者或否定中心体作用，其实纺锤体与胞质微管多由中心体发出。"]},{"id":"ch06_judge_3","modI":4,"q":"微管存在于所有真核生物细胞中。（                 ）","a":"错","e":"人的红细胞中没有微管，另外，原核生物中没有微管。","kp":"ch06_s2_0","oe":["若判对则忽视了人成熟红细胞无微管，且原核生物根本不存在微管。","微管并非存在于所有真核细胞，如哺乳动物成熟红细胞中就没有微管。"]},{"id":"ch06_judge_4","modI":5,"q":"紫杉酚能促进微管的装配，因此对细胞是有利的。（                    ）","a":"错","e":"紫杉酚能促进微管的装配，但这种稳定性的增加对细胞是有害的，使细胞周期停止 于有丝分裂期。","kp":"ch06_s5_0","oe":["若判对则只看其促进装配，忽视过度稳定会使细胞停滞于有丝分裂期。","紫杉酚虽促进微管装配并使之稳定，但导致细胞周期阻断于有丝分裂期。"]},{"id":"ch06_judge_5","modI":4,"q":"在所有动力动物细胞中，中心体是主要的微管组织中心。（                   ）","a":"错","e":"在动物细胞中，微管组织中心还包括纤毛、鞭毛的基体。","kp":"ch06_s4_2","oe":["若判对则忽略纤毛、鞭毛基体等也可作为微管组织中心。","动物细胞中微管组织中心除中心体外，还包括纤毛和鞭毛的基体等。"]},{"id":"ch06_judge_6","modI":0,"q":"肌肉的收缩是细肌丝收缩的结果。              （      ）","a":"错","e":"肌肉的收缩是粗肌丝和细肌丝相对滑动的结果。","kp":"ch06_s0_0","oe":["若判对则误认为是细肌丝本身收缩，其实是粗细肌丝相对滑动。","肌肉收缩是粗肌丝与细肌丝相对滑动的结果，并非细肌丝自身收缩。"]},{"id":"ch06_judge_7","modI":8,"q":"纤毛的运动是微管收缩的结果。（                ）","a":"错","e":"纤毛的运动是肌动蛋白运动的结果。","kp":"ch06_s12_0","oe":["若判对则误以为纤毛运动靠微管收缩，实际依靠微管滑动及动力蛋白。","纤毛运动源于轴丝二联体微管间的滑动，由动力蛋白臂驱动，非收缩。"]},{"id":"ch06_judge_8","modI":4,"q":"加入秋水仙碱可抑制绿藻细胞中的胞质环流运动。（                        ）","a":"对","e":"秋水仙碱是微管组装的阻断剂，用它处理细胞会导致细胞内微管系统的解体，从而 抑制胞质环流运动。","kp":"ch06_s5_0","oe":["秋水仙碱是微管组装阻断剂，使微管解体从而抑制依赖微管的胞质环流。","误判为错者或以为胞质环流与微管无关，其实该运动依赖微管系统。"]},{"id":"ch06_judge_9","modI":2,"q":"中心粒和基体均不具有自我复制性质。（                       ）","a":"错","e":"中心体与基体都有自我复制能力，新的中心粒是由原来的中心粒在 S 期复制而来， 而基体则可由中心体衍生而来。","kp":"ch06_s4_3","oe":["若判对则误认为二者无复制能力，实则中心粒和基体均可自我复制。","中心粒和基体均有自我复制能力，中心粒于S期复制，基体可由中心体衍生。"]},{"id":"ch06_ajudge_2","modI":3,"q":"●αβ→αβ→αβ重复排列, 头尾相接, 构成微管","a":"对","e":"本页要点：●αβ→αβ→αβ重复排列, 头尾相接, 构成微管","kp":"ch06_s3_0","oe":["αβ微管蛋白二聚体头尾相接重复排列，构成微管的原纤维。","误判为错者或不知微管由αβ二聚体头尾相接重复排列而成。"]}],"fill":[{"id":"ch06_fill_1","modI":2,"q":"组成细肌丝主要的三种蛋白质是：______、______、______。组成粗肌丝的主要蛋白成 分是：______。构成微管的蛋白有两类：______和______。","a":"肌动蛋白；原肌球蛋白；肌钙蛋白；肌球蛋白；α-微管蛋白；β-微管蛋白","kp":"ch06_s1_2","oe":["细肌丝主要由肌动蛋白构成，是肌肉收缩的重要成分。","原肌球蛋白沿肌动蛋白螺旋排列，属细肌丝的调节蛋白。","肌钙蛋白结合原肌球蛋白并感受Ca2+，属细肌丝调节蛋白。","粗肌丝的主要成分是肌球蛋白，其头部具ATP酶活性。","微管由α和β微管蛋白异二聚体组装，α为其中一亚基。","β微管蛋白是微管蛋白异二聚体的另一亚基，故为答案。"]},{"id":"ch06_fill_2","modI":4,"q":"______在细胞间期组织形成间期微管，在细胞分裂期组织形成______，因而被称为细胞 的微管组织中心。","a":"中心体；胞质分裂环","kp":"ch06_s4_0","oe":["间期微管由中心体即微管组织中心组织形成，故填中心体。","分裂期微管组织中心组织纺锤体，其星体微管定位胞质分裂环。"]},{"id":"ch06_fill_3","modI":7,"q":"构成纺锤体的微管有三种：______、______和 ______ 。","a":"星体微管；动力微管；极性微管","kp":"ch06_s13_0","oe":["星体微管由中心体发出伸向细胞皮层，参与纺锤体定位。","动力微管即连接动粒的微管，牵引染色体向两极移动。","极性微管从两极发出并相互重叠，维持纺锤体的结构。"]},{"id":"ch06_fill_4","modI":2,"q":"细胞质骨架包括______、______和______。","a":"微丝；微管；中间丝","kp":"ch06_s1_0","oe":["微丝由肌动蛋白构成，参与细胞运动与收缩，是骨架之一。","微管由微管蛋白构成，参与支持、运输和纺锤体形成。","中间丝由中间丝蛋白构成，为细胞提供机械强度。"]},{"id":"ch06_fill_5","modI":6,"q":"胞质中微管动力蛋白分为两大类分别为：______（kinesin）和______（cytoplasmic dynein）。 驱动蛋白通常朝微管的______方向运动，动力蛋白朝微管的______运动。","a":"驱动蛋白；动力蛋白；正极；负极","kp":"ch06_s7_9","oe":["kinesin是朝微管正极移动的马达蛋白，故填驱动蛋白。","cytoplasmic dynein朝微管负极移动，故填动力蛋白。","驱动蛋白通常沿微管向正极运输，如运往细胞外周。","动力蛋白沿微管向负极运输，如运回细胞中心。"]},{"id":"ch06_fill_6","modI":5,"q":"微管蛋白二聚体是由______和______组成的。","a":"α-微管蛋白；β微管蛋白","kp":"ch06_s2_7","oe":["微管蛋白异二聚体由α微管蛋白和β微管蛋白组成，α为其一。","β微管蛋白是异二聚体的另一亚基，具GTP结合位点。"]},{"id":"ch06_fill_7","modI":4,"q":"肌丝成分中收缩蛋白有______和______，调节蛋白有______和______。","a":"肌动蛋白；肌球蛋白；原肌球蛋白；肌钙蛋白","kp":"ch06_s1_2","oe":["收缩蛋白包括肌动蛋白和肌球蛋白，二者相互作用产生收缩。","肌球蛋白是粗肌丝主要成分，其头部与肌动蛋白结合并水解ATP。","调节蛋白包括原肌球蛋白和肌钙蛋白，调控收缩的启动。","肌钙蛋白结合Ca2+后解除原肌球蛋白对肌动蛋白的阻挡。"]},{"id":"ch06_fill_8","modI":4,"q":"组成纤毛、鞭毛结构的 3 部分是______、______和______，其中______具有 MTOC 作 用。","a":"毛部；基体；根丝；基体","kp":"ch06_s12_3","oe":["纤毛鞭毛伸出细胞表面的主体，由9+2微管构成，可摆动。","位于毛部基部，由9组三联体微管组成，是微管的锚定结构。","基体下方伸入细胞质的微丝样结构，起固定和支持作用。","作为微管组织中心，是纤毛鞭毛微管装配的起始部位。"]},{"id":"ch06_fill_9","modI":7,"q":"纺锤体中与染色体连接的微管有______和______。","a":"染色体微管；中间微管","kp":"ch06_s13_0","oe":["染色体微管即动粒微管，一端附着染色体动粒，牵引其移向两极。","中间微管不直接连动粒，位于纺锤体中部连接两极，维持形态。"]},{"id":"ch06_fill_10","modI":0,"q":"广义的核骨架成分包括______、______和______。","a":"核基质核纤层；核孔复合体；染色体骨架","kp":"ch06_s0_0","oe":["核基质（含核纤层）是核内非染色质的纤维网络，为核骨架主体。","核孔复合体镶嵌于核膜，是核质之间物质运输的通道。","染色体骨架是维持染色体形态的非组蛋白支架结构。"]},{"id":"ch06_fill_11","modI":12,"q":"构成一根微管的原纤丝有______条。","a":"13","kp":"ch06_s2_2","oe":["微管由13条原纤丝围成中空管状，每条原纤丝由异二聚体纵向排列。"]},{"id":"ch06_fill_12","modI":5,"q":"紫杉醇和长春花碱抗癌作用的机制分别是______。","a":"抑制微管解聚和抑制微管聚合","kp":"ch06_s5_0","oe":["紫杉醇稳定微管、抑制其解聚；长春花碱抑制微管聚合，均破坏纺锤体。"]},{"id":"ch06_fill_13","modI":4,"q":"微管在细胞中以三种形式存在，大部分细胞质微管是______不太稳定；构成纤毛、鞭毛 周围小管的是 ______，比较稳定；组成中心粒和基体的是______，十分稳定。","a":"单体；二联体；三联体","kp":"ch06_s2_2","oe":["细胞质微管多为13条原纤丝组成的单管，动态变化不稳定。","纤毛鞭毛周围小管由A、B两亚管并合而成，较为稳定。","中心粒和基体由A、B、C三个亚管组成，十分稳定。"]},{"id":"ch06_fill_14","modI":2,"q":"组成细肌丝主要的三种蛋白质是：______、______、______。组成粗肌丝的主要蛋白成 分是：______。构成微管的蛋白有两类：______和______。","a":"肌动蛋白；原肌球蛋白；肌钙蛋白；肌球蛋白；α微管蛋白；β微管蛋白","kp":"ch06_s1_2","oe":["细肌丝主体，由球形肌动蛋白单体聚合成的双螺旋纤维。","缠绕于肌动蛋白双螺旋沟中的长条状调节蛋白。","结合在原肌球蛋白上的调节蛋白，可结合钙离子触发收缩。","粗肌丝的主要成分，头部具ATP酶活性，属分子马达。","微管蛋白异二聚体的一类亚基，与β亚基组成基本单元。","与α微管蛋白组成异二聚体，其GTP水解与微管动态相关。"]},{"id":"ch06_fill_15","modI":2,"q":"细胞内具有分子马达（引擎蛋白）作用的蛋白分子有______、______、______、______ 等。","a":"肌球蛋白；动力蛋白；驱动蛋白；ATP 合成酶","kp":"ch06_s6_8","oe":["沿微丝运动，参与肌肉收缩和胞质分裂。","沿微管向负极运动，介导轴突逆行运输和纤毛摆动。","沿微管向正极运动，介导轴突顺行运输和纺锤体形成。","利用质子梯度旋转合成ATP，具有旋转分子马达特性。"]},{"id":"ch06_fill_16","modI":0,"q":"细胞骨架是指存在于真核细胞中的蛋白纤维网架体系，狭义的骨架系统主要是指细胞质 骨架，包括 ______、______和______。","a":"微丝；微管；中间纤维","kp":"ch06_s1_0","oe":["由肌动蛋白组成的细丝，直径约7nm，参与收缩和形态维持。","由微管蛋白组成的管状结构，参与运输、支持和纺锤体形成。","由角蛋白、结蛋白等组成的纤维，起机械支撑和抗张力作用。"]},{"id":"ch06_fill_17","modI":1,"q":"广义细胞骨架包括_________、_________、_________及_________，它们一起构成了高 等动物的纤维网络结构。[浙江师范大学 2011 研]","a":"细胞核骨架；细胞质骨架；细胞膜骨架；细胞外基质","kp":"ch06_s1_0","oe":["核内以核纤层、核基质为主的纤维网络体系。","由微丝、微管和中间纤维组成的细胞质网架系统。","膜下由血影蛋白、肌动蛋白等构成的支撑网络。","细胞分泌的糖蛋白、蛋白聚糖等构成的胞外网络。"]},{"id":"ch06_fill_18","modI":8,"q":"纤毛具有______结构，通过微管上结合的_________分解_______造成微管间的______。[南 京师范大学 2008 研]","a":"“9＋2”排列的平行微管；ATP 酶；ATP；二联管解聚","kp":"ch06_s12_3","oe":["纤毛轴心为9组二联体围绕2条中央单管，即9+2排列。","二联体A亚管结合有ATP酶（动力蛋白臂），可水解ATP。","动力蛋白臂分解ATP释放能量，为微管滑动提供动力。","相邻二联管相对滑动并部分解聚，使纤毛产生弯曲运动。"]},{"id":"ch06_fill_19","modI":7,"q":"在神经轴突物质转运过程中，有两种马达蛋白介导，一是_________介导运输小泡由轴突 顶端运向胞体；二是_________介导运输小泡由胞体运向轴突顶端。[中科院-中科大 2006 研]","a":"动力蛋白；驱动蛋白","kp":"ch06_s11_0","oe":["向微管负极运动，将运输小泡从轴突顶端运回胞体。","向微管正极运动，将运输小泡从胞体运向轴突顶端。"]}],"term":[{"id":"ch06_term_1","modI":7,"term":"基粒（basal body）。","def":"基粒（basal body）是指位于鞭毛和纤毛根部，类似于动物细胞中的中心体，呈圆柱状 的微管性结构，平均大小为 0.2～0.5μm。其壁由 9 组微管三联体组成，包括完全微管与不 完全微管。胞质动力蛋白。中心粒和基粒是同源的，在某些时候可以相互转变，且都具有自 我复制能力。","kps":"","kp":"ch06_s12_3"},{"id":"ch06_term_2","modI":13,"term":"肌原纤维（myofrbrils）。","def":"肌原纤维（myofrbrils）是指肌纤维中许多纵行的，直径约 1μm 的圆筒状的微细结构， 与肌肉的收缩有直接关系。骨骼肌的肌原纤维的单位是肌节，藉 Z 线隔开，其中间有 A 带， 两侧有 I 带，明-暗重复单位是肌肉收缩和舒张最基本的功能单位。","kps":"","kp":"ch06_s0_0"},{"id":"ch06_term_3","modI":4,"term":"微管组织中心（microtubule organizingcenter，MTOC）。","def":"微管组织中心（microtubule organizingcenter，MTOC）是指微管在生理状态或实验处理 解聚后重新装配的发生处。如鞭毛基体、动物细胞中的中心体。微管组织中心决定了细胞微 管的极性，微管的负极指向微管组织中心，正极背向微管组织中心。","kps":"","kp":"ch06_s4_0"},{"id":"ch06_term_4","modI":2,"term":"微管蛋白流（tubulin flow）。","def":"微管踏车学说认为微管组装过程中，在 GTP、 Mg2 等条件下，微管蛋白异二聚体不断 ＋   地在微管正极端聚合使微管延长，而微管的负极端则因微管蛋白的解聚缩短。微管蛋白从负 极端解聚下来，又到正极端聚合的流动称为微管蛋白流，但 GTP 不存在时，微管蛋白流就 不会发生。","kps":"","kp":"ch06_s2_6"},{"id":"ch06_term_5","modI":2,"term":"微管相关蛋白（MAP）","def":"微管相关蛋白（MAP）即微管结合蛋白，是指一些与微管密切联系，附着于微管多聚 体上，参与微管装配并能增加微管稳定性的蛋白，包括 MAP1，MAP2，MAP3，tau 蛋白等。 微管相关蛋白多分布于神经元的树突和轴突中，一般认为与骨架纤维间的连接有关，可能决 定了轴突和树突的不同形态。","kps":"","kp":"ch06_s6_0"},{"id":"ch06_term_6","modI":6,"term":"kinesin & cytoplasmatic dynein 相关试题：驱动蛋白与动力蛋白（Kinesin and cytoplasmic dynein）","def":"kinesin 的中文名称是驱动蛋白，cytoplasmatic dynein 的中文名称是细胞质动力蛋白。二 者均属于微管马达蛋白，主要负责为物质沿着微管运输提供能量。 二者的区别在于沿微管运动的方向不同。驱动蛋白从微管的（－）端移向微管的（＋）端， 是正端走向的微管发动机；细胞质动力蛋白是负端走向的微管发动机，担负小泡和各种膜结 合细胞器的运输任务，同时还是细胞分裂中染色体运动的动力来源。","kps":"","kp":"ch06_s7_0"},{"id":"ch06_term_7","modI":4,"term":"MTOC（Microtubule-organizing center (MTOC)）","def":"MTOC 的中文名称是微管组织中心。微管组织中心是指具有起始微管组装和延伸的细 胞结构，细胞内的微管组织中心包括中心体和位于纤毛和鞭毛基部的基体等。MTOC 不仅 为微管提供了生长的起点，而且还决定了微管的方向性。靠近 MTOC 的一端由于生长慢而 称为负端；远离 MTOC 一端的微管生长速度快，称为正端，所以正端指向细胞质基质，常 常靠近细胞质膜。","kps":"","kp":"ch06_s4_0"}],"short":[{"id":"ch06_short_1","modI":4,"q":"微管的主要功能有哪些？","a":"真核细胞内部是高度区域化的体系，微管与生物大分子、细胞器在细胞内的分布，以及 细胞形态的维持具有密切关系。 （1）支持细胞的功能，构成细胞内网状支架，维持细胞形状，固定与支持细胞器的位置。 （2）与细胞器位移和细胞运动有关，染色体的移动、纤毛、鞭毛的运动都是由微管聚合和 解聚产生的。 （3）参与运输，颗粒物质可沿微管移动。 （4）与某些信息的传递有关。","kp":"ch06_s8_0","kps":"支持维持形状、固定细胞器;细胞器位移与纤毛/鞭毛/染色体运动;运输轨道(颗粒沿微管移动);参与信息传递"},{"id":"ch06_short_2","modI":4,"q":"试述纤毛和鞭毛的结构与功能。","a":"纤毛（flagella）和鞭毛（cilia）是真核细胞表面的具有运动功能特化结构。 （1）纤毛和鞭毛的结构：是细胞质膜所包被的细长突起，内部由微管构成轴丝结构。由基 体和纤毛轴丝两部分组成。纤毛轴轴丝为“9＋2”排列微管，即外周 9 组二联体微管＋中央鞘 包围的 2 根中央单体微管。外周二联体微管由 A，B 亚纤维组成，A 亚纤维为完全微管，B 亚纤维仅由 10 个亚基构成。中央微管均为完全微管。基体的微管组成为“9＋0”，无中央微 管。 （2）纤毛和鞭毛的运动机相关的滑动学说被普遍认可：纤毛运动由轴丝介导的相邻二联体 间相互滑动所致。由一个二联体的 A 管伸出的动力蛋白臂的马达结构域在相邻的二联体的 B 管上“行走”。","kp":"ch06_s12_0","kps":"质膜包被突起,基体+轴丝;轴丝9+2、基体9+0;运动:滑动学说,动力蛋白臂致二联体滑动、ATP供能"},{"id":"ch06_short_3","modI":2,"q":"叙述什么是微管的 GTP 帽和 GDP 帽，其对微管的动态性质有什么影响。","a":"微管的 GTP 或 GDP 帽就是微管正端αβ微管蛋白二聚体结合 GTP 或 GDP 的状态。 （1）如果微管正端结合的是由结合 GTP 的微管蛋白二聚体组成的 GTP 帽结构，微管就趋 于生长； （2）如果微管的正端结合的是由结合 GDP 的微管蛋白二聚体组成的 GDP 帽结构，这种微 管就趋于缩短。 决定微管正端是 GTP 帽还是 GDP 帽，又受两种因素影响：一是结合 GTP 的游离微管蛋白 二聚体的浓度；二是 GTP 帽中 GTP 水解的速度。当（＋）端形成 GTP 帽，而游离微管蛋 白二聚体的浓度又很高时，微管趋向于生长。由于结合 GTP 的游离微管蛋白二聚体的浓度 降低，使得微管延长的速度下降，随着 GTP 水解的不断进行最后 GTP 帽结构转变成 GDP， 逐渐使微管变得不稳定，趋于解聚。细胞内微管的这两种状态是不断发生的，因为细胞内不 断有微管解聚，又不断地有新微管的组装。","kp":"ch06_s2_9","kps":"GTP帽结合GTP二聚体趋生长;GDP帽结合GDP二聚体趋缩短;受游离GTP-微管蛋白浓度与水解速度影响;动态不稳定"},{"id":"ch06_short_4","modI":0,"q":"如何用荧光显微镜研究细胞骨架?其基本原理是什么？","a":"用荧光显微镜研究细胞骨架主要是基于两方面的原理。 （1）组成细胞骨架的蛋白亚基能够同小分子的荧光染料共价结合，使细胞骨架带上荧光标 记，发出荧光。 （2）可以制备细胞骨架的荧光抗体，然后用荧光抗体进行细胞骨架的研究。借助于这两方 面原理，可用荧光显微镜研究细胞骨架的动力学。例如，用小分子的荧光染料标记细胞骨架 的蛋白亚基，就可以追踪细胞骨架蛋白在细胞活动中的作用，包括组装、去组装、物质运输 等。这种方法还有一个好处，就是在活细胞时就可以观察。 可用荧光抗体研究以很低浓度存在的蛋白质在细胞内的位置，因为标记的荧光抗体同特异的 蛋白质具有很高的亲和性，只要有相应的蛋白质存在，就一定会有反应。这种反应是特异的， 通过荧光显微镜观察就可确定。荧光抗体既可以直接注射活细胞进行反应，也可以加到固定 的细胞或组织切片中进行反应和分析。用这种方法可对微管、肌动蛋白纤维、中间纤维进行 定位。","kp":"ch06_s2_10","kps":"荧光染料标记骨架蛋白亚基追踪组装/去组装/运输,可活细胞观察;荧光抗体标记特异蛋白定位,亲和性高、灵敏"},{"id":"ch06_short_5","modI":2,"q":"比较胞质骨架三种组分。","a":"胞质骨架三种组分比较如下： 表 10-1","kp":"ch06_s1_0","kps":"微管(微管蛋白、25nm、kinesin/dynein);微丝(肌动蛋白7nm、肌球蛋白);中间丝(10nm、无极性)"},{"id":"ch06_short_6","modI":13,"q":"由神经冲动诱发的肌肉收缩基本过程分哪几步？","a":"由神经冲动诱发的肌肉收缩基本过程可以分为：（1）动作电位的产生；（2）Ca2 的释 ＋   放；（3）原肌球蛋白位移；（4）肌动蛋白丝与肌球蛋白丝的相对滑动；（5）Ca2 的回收。 ＋","kp":"ch06_s0_0","kps":"动作电位产生;Ca2+释放;原肌球蛋白位移;肌动蛋白丝与肌球蛋白丝相对滑动;Ca2+回收"},{"id":"ch06_short_7","modI":1,"q":"如何证明染色体骨架的真实性？","a":"（1）银染法能选择性地显示染色体轴结构；（2）DNA 酶和 RNA 酶处理或用 0.4mol ／LH2sO4 处理去除组蛋白，对染色体轴没有影响，用胰蛋白酶消化则染色体轴破坏，说明 染色体轴是非组蛋白性的；（3）染色体骨架／放射环模型在分子水平上得到两个直接证据。","kp":"ch06_s13_0","kps":"银染显示染色体轴;DNA酶/RNA酶/硫酸去组蛋白不破坏轴,胰蛋白酶破坏→轴为非组蛋白性;骨架/放射环模型分子证据"},{"id":"ch06_short_8","modI":7,"q":"比较细胞质动力蛋白与驱动蛋白。","a":"（1）两者都是将 ATP 的化学能转化为动能的大的发动机蛋白，都与微管结合在一起， 但只有动力蛋白存在于纤毛和鞭毛的微管之中。 （2）驱动蛋白是通过加末端方式来引导微管的运动，动力蛋白则通过减末端方式来引导微 管运动。 （3）虽然它们在功能上有相似之处，但不是同源蛋白，而且立体结构非常不同。它们并不 属于同一蛋白家族。","kp":"ch06_s7_9","kps":"动力蛋白仅存于纤毛鞭毛微管;驱动蛋白向加端运动,动力蛋白向减端;功能似但非同源、结构不同、不同家族;均为ATP酶马达蛋白"},{"id":"ch06_short_9","modI":12,"q":"列举细菌与动物细胞之间的差别。这些差别很可能是由于在进化过程中出现的部分或所 有现代真核细胞具有的细胞骨架所造成的。","a":"（1）动物细胞相当大，形状多变，而且没有细胞壁，因而需要细胞骨架来支撑并保持 其形状。 （2）动物细胞及其他真核细胞都有细胞核，细胞核靠中间纤维在细胞中成形并维持在适当 的部位。核纤层附着于核被膜的内侧，支持核被膜并使之成形，中间纤维网络包围核并穿行 在细胞质中。 （3）动物细胞可通过改变细胞形状进行移动。这—过程需要肌动蛋白及肌球蛋白的参与。 （4）动物细胞的基因组比细菌大得多，分为许多染色体。细胞分裂时，染色体必须精确地 分配到两个子细胞中。这—过程需要形成有丝分裂纺锤体的微管系统参与。 （5）动物细胞具有胞内细胞器。细胞器在胞内的定位依赖于沿着微管移动的发动机蛋白。 显著的例子是从脊髓到脚部的神经轴突（该轴突可长达 1 m）中，胞内运输小泡（细胞器） 沿着微管的长距离运输。","kp":"ch06_s0_0","kps":"动物细胞大、无壁需骨架支撑;核靠中间纤维/核纤层定位;变形移动需肌动蛋白/肌球蛋白;染色体分配需纺锤体"},{"id":"ch06_short_10","modI":12,"q":"什么叫凝胶-溶胶（gel-sol）和溶胶-凝胶（sol-gel）转变？","a":"原生动物中的变形虫，高等动物中的巨噬细胞和白细胞等没有鞭毛、纤毛等运动器官， 但能够依靠细胞体的变化进行移动，叫作变形运动。通常要靠胞质环流形成伪足，细胞沿着 伪足形成的方向前进。细胞内流动的细胞质叫作内质，从尾部流向前进中的伪足。当液流到 达伪足时，流动的细胞质分向细胞的两侧，并形成较硬的外质。其间，位于细胞后部的外质 被破坏并向前方提供新的内质，由此产生内质和外质的循环转变，并引起细胞向前移动。细 胞质由坚硬的凝质状态（外质）向可流动的液态（内质）转变的过程称为凝胶-溶胶转变， 相反的过程叫溶胶-凝胶转变。","kp":"ch06_s1_2","kps":"变形运动:胞质环流形成伪足;外质(凝胶态)与内质(液态)循环转变;凝胶-溶胶=外质变内质;溶胶-凝胶=内质变外质"},{"id":"ch06_short_11","modI":4,"q":"用秋水仙素处理动物细胞，细胞内质网与高尔基体分布有什么改变，为什么？","a":"（1）秋水仙素处理动物细胞后内质网与高尔基体分布的改变 用秋水仙素处理动物细胞，内质网缩回到细胞核周围，高尔基体解体成小的膜泡样结构分散 在细胞质内，细胞内依赖于微管的物质运输系统全面瘫痪。 （2）发生改变的原因 真核细胞内部是高度区室化的结构，细胞中某些物质的合成部位与行使功能部位往往是不同 的。内膜系统把细胞质分割成一个个区室，将物质合成部位和功能行使部位分隔开，微管是 维持区室化的重要结构基础。秋水仙素是微管蛋白组装抑制剂，当用秋水仙素处理动物细胞 后，微管很快解聚，从而造成内质网和高尔基体凝聚化。","kp":"ch06_s5_0","kps":"改变:内质网缩回核周,高尔基体解体为膜泡分散,微管依赖运输瘫痪;原因:秋水仙素抑制微管组装→解聚→区室化破坏"},{"id":"ch06_short_12","modI":0,"q":"何谓细胞骨架？如何理解细胞骨架是细胞内的一种动态结构？","a":"（1）细胞骨架的概念 细胞骨架是指由细胞内蛋白质成分组成的一个复合的网架系统，包括微管、微丝和中间丝。 与其他细胞结构相比，细胞骨架在形态结构上具有弥散性、整体性和变动性等特点，这些都 是与它们的功能相适应的。细胞骨架为真核细胞所特有，它不仅是活细胞的支撑结构，决定 了细胞的形状并赋予其强度，而且在细胞多种多样的生理活动（如细胞运动、膜泡运输和细 胞分裂等）中发挥着重要作用。 （2）细胞骨架是一种动态结构的理解 由于细胞骨架与细胞运动有关，在不同的功能状态、不同的细胞周期，细胞骨架是不断地组 装或去组装，因此细胞骨架是细胞内的一种动态结构。","kp":"ch06_s1_0","kps":"概念:蛋白组成的网架系统(微管/微丝/中间丝),弥散性/整体性/变动性;动态:随功能与周期不断组装去组装,动态平衡"},{"id":"ch06_short_13","modI":8,"q":"试分析纤毛不动症发生机制，并以此为例叙述纤毛和鞭毛的运动机制。","a":"（1）纤毛不动症发生机制 纤毛不动症即原发性纤毛运动障碍（PCD），是指纤毛超微结构具有特异的、先天性遗传缺 陷导致的一组疾病。目前认为 PCD 的纤毛异常与内、外动力蛋白臂的缺失或纤毛动力蛋白 臂中 ATP 酶缺乏或代谢异常有关，以致微管滑行缺乏能量，使纤毛摆动受阻。 （2）纤毛和鞭毛的运动机制 纤毛和鞭毛的运动本质是轴丝动力蛋白介导的相邻二联体微管之间的相互滑动。纤毛和鞭毛 摆动的特征是从基体产生滑动，沿着轴丝将弯曲传递到尾部，因此，二联管之间的滑动必须 转换为弯曲运动。当轴丝上任意两点的滑动速率不等时，滑动即可转换为弯曲。 ①滑动速率的差异主要来自维持轴丝结构的连接蛋白，它们在一定程度上限制了二联管的自 由滑动； ②在某一时间某一位置，只有部分动力蛋白臂被激活，激活一半的动力蛋白臂使轴丝朝一边 弯曲，激活另一半则朝另一边弯曲。二条动力蛋白臂的作用不同，内臂产生滑动，导致轴丝 弯曲，而外臂可以加快滑动的速度。","kp":"ch06_s12_0","kps":"纤毛不动症:内外动力蛋白臂缺失或ATP酶异常→微管滑行缺能;运动:动力蛋白介导相邻二联体滑动,速率不均由连接蛋白转换弯曲"},{"id":"ch06_short_14","modI":0,"q":"通过本章的学习，你对生命体的自组装原则有何认识？","a":"我对生命体自组装原则的认识如下： （1）细胞内的复杂结构可由简单的分子组装而成，其组装过程受到细胞本身的调节，这样 便于细胞在不同生理状态下调节细胞结构的组织形式，执行特定的功能。 （2）多种结构相互联系，共同完成细胞的生命活动。 （3）生命体在装配过程中受到多种因素影响。如影响微管组装的因素有秋水仙素、紫杉醇、 长春花碱；影响微丝组装的因素有细胞松弛素、鬼笔环肽。 （4）生命体自组装具有高度的时空顺序性。","kp":"ch06_s0_0","kps":"复杂结构由简单分子组装且受调节;多结构相互联系;受多因素影响(秋水仙素/紫杉醇/长春花碱等);时空顺序性"},{"id":"ch06_short_15","modI":1,"q":"除支持作用和运动功能外，细胞骨架还有什么功能？怎样理解“骨架”的概念？","a":"（1）细胞骨架的其他功能 为物质运输提供轨道、参与肌肉收缩和细胞分化、介导染色体的移动和动物细胞胞质分裂、 形成细胞的特化结构等。 （2）“骨架”的理解 ①骨架是指真核细胞内一个复杂的由特异蛋白质组成的纤维网架结构，具有支持功能，在细 胞形态维持、膜性细胞器定位和移动过程中具有重要的作用。 ②理解骨架概念时的注意事项： a．细胞骨架是一种动态平衡的结构； b．具有多种功能； c．由蛋白质组装而成，组装的过程受到信号的调节。","kp":"ch06_s1_0","kps":"其他功能:运输轨道、肌肉收缩与细胞分化、染色体移动与胞质分裂、形成特化结构;骨架:蛋白纤维网架,动态、多功能、受信号调节"},{"id":"ch06_short_y1","modI":0,"q":"比较微管、微丝和中间纤维在直径、亚基、极性、组装方式和主要功能上的异同。","a":"①直径：微管约24nm，微丝约7nm，中间纤维约10nm。②亚基：微管由αβ-微管蛋白异二聚体组成；微丝由肌动蛋白（G-actin）组成；中间纤维由多种纤维状蛋白（角蛋白、波形蛋白、结蛋白、神经丝蛋白、核纤层蛋白等）组成。③极性：微管和微丝有极性（正/负端），中间纤维无极性。④组装方式：微管和微丝由球状亚基聚合，具动态不稳定性/踏车行为，需核苷酸（GTP/ATP）；中间纤维由纤维状蛋白分步组装（二聚体→四聚体→原纤丝→纤维），不依赖核苷酸。⑤功能：微管维持形态、作为运输轨道、形成纺锤体与纤毛鞭毛；微丝参与收缩、运动、胞质分裂和黏着；中间纤维提供机械强度、参与桥粒与核膜稳定。","kps":"直径:24/7/10nm;亚基:αβ微管蛋白/G-actin/多种纤维蛋白;极性:有/有/无;组装:依赖核苷酸动态/分步不依赖核苷酸;功能:运输纺锤体/收缩运动/机械强度","type":"比较型","kp":"ch06_s1_0"}],"calc":[{"id":"ch06_calc_1","modI":0,"q":"什么是分子马达？举例说明（至少 3 个）。","a":"分子马达（molecular motor），主要是指依赖于微管的驱动蛋白、动力蛋白和依赖于微 丝的肌球蛋白这三类蛋白超家族的成员。它们既能与微管或者微丝结合，又能与一些细胞器 或膜状小泡特异性结合，并利用水解 ATP 所产生的能量有规则地沿微管或微丝等细胞骨架 纤维运输所携带的“货物”。 （1）肌球蛋白是与微丝相关的一类分子马达。其共同特征是都含有一个作为马达结构域的 头部。其马达结构域包含一个微丝结合位点和一个具有 ATP 酶活性的 ATP 结合位点。 ①Ⅱ型肌球蛋白存在于多种细胞，包含 2 条重链和 4 条轻链。头部即马达结构域，尾部主要 起结构作用。Ⅱ型肌球蛋白尾尾相接所构成的双极纤维能介导相邻的微丝相互滑动。 ②Ⅰ型肌球蛋白头部亦为马达结构域，在 ATP 存在时可沿微丝运动。其尾部结构域具有多 样性，能与多种细胞组分结合，通过头部驱动或细胞质膜作相对于微丝的运动。V 型肌球蛋 白是二聚体马达蛋白，具有两个头部，交替与微丝结合可以确保整个分子以及所运载的“货 物”始终不与微丝脱离。 （2）驱动蛋白是一类蛋白质超家族，与微管相关。通常由 2 条重链和 2 条轻链组成，它们 共有保守的“马达”域，内有 ATP 结合位点和微管结合位点。马达结构域在重链的 N 端，介 导物质向微管的正极运动；而另一些少数驱动蛋白的马达结构域在重链的 C 端，介导物质 向微管的负极运动。 驱动蛋白的马达结构域具有两个重要的功能位点： ①ATP 结合位点； ②微管结合位点。 有关驱动蛋白沿微管运动的分子模型有两种：步行模型和尺蠖爬行模型。大多数学者承认步 行模型：驱动蛋白的两个球状头部交替向前，每水解一分子 ATP，落在后面的那个马达结 构域将移动两部的距离，即 16nm，并循环该过程。 （3）动力蛋白是马达蛋白中最大、移动速度最快的成员： ①轴丝动力蛋白，在纤毛与鞭毛中发现，与纤毛和鞭毛的运动相关； ②胞质动力蛋白，在真核细胞胞质内发现，与细胞内介导微管从正极向负极端的膜泡运输以 及有丝分裂动粒和纺锤体的共定位有关。 动力蛋白由 2 条或 3 条重链，多条轻链及中间链组成。其马达结构域位于重链 C 端，轴丝 动力蛋白有 3 个马达结构域，胞质动力蛋白有 2 个马达结构域。","kp":"ch06_s6_8","kps":"分子马达=驱动蛋白/动力蛋白(微管)+肌球蛋白(微丝);特征:结合骨架与货物、水解ATP、定向运输;举例:肌球蛋白I/II/V、驱动蛋白、动力蛋白"},{"id":"ch06_calc_2","modI":1,"q":"试述三种胞质细胞骨架的主要成分、形态结构、功能及特异性药物。","a":"细胞骨架（cytoskeleton）是指真核细胞中复杂的蛋白纤维网架体系。广义的细胞骨架包 括细胞核骨架，细胞质骨架，细胞膜骨架和细胞外基质。狭义的细胞骨架是指细胞质骨架， 包括微丝（microfilament，MF）、微管（microtubule，MT）、中间纤维（inter- mediated filament， IF）。 （1）微管的形态结构：中空圆柱状，直径 15nm，一般长几微米，微管蛋白是与肌动蛋白相 似的一种酸性蛋白质，常常以二聚体存在（αβ-微管蛋白）。 微管的功能：①支架作用：维持细胞形态、固定细胞器。②细胞收缩，伪足运动；如纤毛、 鞭毛。③细胞器位移、染色体分裂与位移。④胞质内物质运输。 特异性药物：紫杉酚：抗肿瘤药物，研究表明它对微管的作用与传统的抗癌药长春花碱和秋 水仙碱等相反，它能促进微管的聚合、抑制微管的解聚。是微管的特异性稳定剂。 （2）微丝的形态结构：微丝存在很普遍，具有可变结构，直径 6 μm，由肌动蛋白组成，与 微管共同构成细胞支架。 微丝的功能：①与微管共同形成细胞支架，以维持细胞形状。②具有运动功能，与细胞质的 运动紧密相关。③与细胞器关系密切。④细胞内信号传递、蛋白质合成支架。 特异性药物：鬼笔环肽：特异性与微丝侧面结合，增强其稳定性，抑制微丝解聚，对微丝具 有稳定作用。荧光标记的鬼笔环肽可特异性的显示微丝。是微丝的特异性稳定剂。 细胞松弛素：可以切断微丝，并结合在微丝正极阻抑肌动蛋白聚合，因而可以破坏微丝的三 维网络，特异性的抑制微丝的装配。是微丝的特异性抑制剂。 （3）中间纤维：大小介于微管和微丝之间，结构复杂。中间纤维具有严格的组织特异性， 不同类型细胞含有不同 IF。按其组织来源及免疫原性可分为 5 类：①角蛋白纤维：为上皮 细胞特有，具有α和β两类，β角蛋白存在于体表、体腔的上皮细胞中，α角蛋白形成头发、 指甲等坚韧结构；②波形纤维：存在于间充质细胞及中胚层来源的细胞中；③神经胶质纤维： 存在于星形神经胶质细胞；④结蛋白纤维：存在于肌肉细胞；⑤神经元纤维：存在于神经元 中。 此外细胞核中的核纤层蛋白（lamin）也是一种中间纤维。 肿瘤细胞转移后仍保留源细胞的 IF，因此可用 IF 抗体来鉴定肿瘤的来源。如乳腺癌和胃肠 道癌，含有角蛋白，因此可断定它来源于上皮组织。而且大多数细胞中只含有一种中间纤维 （少数细胞含有两种以上，如骨骼肌细胞含有结蛋白和波形蛋白）。中间纤维这种严格的组 织特异性，就被应用于肿瘤临床鉴别诊断，以鉴别肿瘤细胞。 至今尚未发信中间纤维的特异性药物。","kp":"ch06_s1_0","kps":"微管(24nm中空、αβ二聚体、有极、紫杉酚稳定/秋水仙素解聚);微丝(7nm双螺旋、G-actin、有极、鬼笔环肽稳定/细胞松弛素破坏);IF(10nm、无极性、机械强度);成分/结构/功能/药物"},{"id":"ch06_calc_3","modI":2,"q":"动态不稳定性造成微管迅速伸长或缩短。设想一条单一的处于缩短状态的微管： （1）如果要停止缩短并进入伸长状态，其末端必须发生什么变化？ （2）发生这一转换后微管蛋白的浓度有什么变化？ （3）如果溶液中只有 GDP 而没有 GTP，将会发生什么情况？ （4）如果溶液中存在不能被水解的 GTP 类似物，将会发生什么情况？","a":"（1）由于失去了 GTP 帽，即末端的微管蛋白亚基都以结合 GDP 的形式存在，微管因 而缩短。溶液中带有 GTP 的微管蛋白亚基仍会添加到末端，但是寿命很短，因为 GTP 可能 被水解，或者围绕着的微管解体使其脱落下来。但是如果足够的带有 GTP 的亚基以足够快 的速度添加上去并覆盖了微管末端带有 GDP 的微管蛋白亚基，   这时可产生一个新的 GTP 帽， 微管就可重新开始生长。 （2）当微管蛋白浓度较高时，GTP 亚基的添加速率会比较高，因而缩短微管转变为增长微 管的频率也会随微管蛋白浓度的升高而增加。这种调节机制使该系统达到自主平衡：较多微 管的缩短可造成高浓度的游离微管蛋白，转为增长的微管也就增多；反之，增长的微管多了， 游离微管蛋白浓度下降从而 GTP-亚基的添加速率也下降，在某些部位 GTP 水解的速率会超 过添加速率，造成 GTP 帽破坏，微管又开始进入缩短状态。 （3）如果只有 GDP 存在，微管会持续短缩，并最终消失，因为结合有 GDP 的微管蛋白二 聚体之间的亲和力十分低，不可能被稳定地添加到微管上。 （4）如果有 GTP 存在但不能被水解，那么微管将持续增长，直到所有游离的微管蛋白亚基 被消耗完为止。","kp":"ch06_s2_5","kps":"失去GTP帽→缩短;GTP亚基足够快添加形成新GTP帽→转生长;浓度升高→转换频率增加(自主平衡);无GTP→无法聚合;不可水解GTP类似物→持续稳定生长"},{"id":"ch06_calc_4","modI":0,"q":"细胞中同时存在几种骨架体系有什么意义？是否是物质和能量的一种浪费？","a":"（1）细胞骨架是指细胞内以蛋白质纤维为主要成分的网络结构，细胞中同时存在的骨 架体系为微丝、微管和中间丝，这三种细胞骨架的意义在于它们在细胞的生命活动中各自的 功能。 ①微丝的功能主要有：肌细胞中参与肌原纤维收缩；非肌细胞中参与胞质分裂、胞质环流、 吞噬作用、细胞变形运动、膜泡运输、细胞黏着与连接（黏着带与黏着斑）、微绒毛的支撑 结构等。 ②微管的功能主要包括：支架作用，维持细胞形态、定位细胞器，作为细胞内物质运输通道， 作为纤毛、鞭毛的运动元件，构成纺锤体参与细胞分裂等。 ③中间丝的功能有：为细胞提供机械强度支持，参与细胞连接（桥粒与半桥粒），维持核膜 稳定等。 （2）三种骨架成分在细胞中同时存在不是物质和能量的一种浪费，理由如下： 三种骨架成分在细胞中同时存在，自成系统，但又互相联系，互不重合。微丝分布在靠近细 胞膜的部位，微管、中间丝从细胞核向细胞周缘放射状延伸。它们在功能上相互配合、相互 协调，缺乏任何一种骨架成分都会引起细胞生命活动的异常。因此细胞中同时存在几种骨架 体系并不是物质和能量的浪费。","kp":"ch06_s1_0","kps":"微丝:收缩/运动/胞质分裂/黏着;微管:支架/运输/纺锤体/纤毛鞭毛;IF:机械强度/桥粒/核膜;非浪费:自成系统、互相联系、功能互补、分区分布"},{"id":"ch06_calc_5","modI":14,"q":"为什么说细胞骨架是细胞结构和功能的组织者？细胞内一些细胞器和生物大分子的不对 称分布有什么意义？","a":"（1）细胞骨架是细胞结构和功能的组织者的原因 ①细胞骨架形成了细胞的多种结构：微管能形成鞭毛、纤毛、基体和中心体等结构，微丝参 与微绒毛、收缩环、应力纤维、黏着斑和黏着带的形成，中间丝对维持细胞核的形态和形成 桥粒等具有重要的作用； ②细胞骨架在细胞形态发生和维持等方面具有重要的作用； ③细胞骨架在物质运输、信号传递、细胞运动、细胞分裂等活动中具有重要的作用。 （2）细胞内一些细胞器和生物大分子不对称分布的意义 ①细胞内一些细胞器和生物大分子的不对称分布与细胞不同结构或部分具有特定的功能是 相互联系的，这种不对称分布与细胞骨架的组织方式有关； ②神经细胞中的轴突和树突具有大量的胞质骨架，这与轴突和树突形态的维持及物质的定向 运输有关； ③桥粒、半桥粒、黏着斑和黏着带含有丰富的细胞质骨架结构，这与锚定连接的形成有关； ④细胞内一些细胞器和生物大分子的不对称分布特点是与细胞特定结构的功能相一致的。","kp":"ch06_s8_0","kps":"形成结构(鞭毛纤毛/微绒毛/收缩环/桥粒)、维持形态、参与运输信号运动分裂;不对称分布意义:与特定功能相适应、轴突树突、锚定连接"},{"id":"ch06_calc_6","modI":13,"q":"如何理解细胞骨架的动态不稳定性？这一现象与细胞生命活动过程有什么关系？","a":"（1）细胞骨架的动态不稳定性的理解 ①细胞骨架的动态不稳定性是指骨架纤维的持续组装与去组装，通过蛋白亚基的添加和解聚 实现骨架长度的延长或缩短。 ②细胞骨架是一种高度动态的结构体系，细胞的运动是通过肌动蛋白的聚合与解聚完成的。 ③在细胞周期的不同时相，细胞骨架具有完全不同的分布状态。间期微丝、微管分布在细胞 质中，中间丝在细胞质和细胞核均有分布。分裂期时，细胞质中的微管迅速解体，用于纺锤 体微管的延长，牵拉染色体运动；微丝解聚，在细胞赤道板分裂沟部位组装成胞质分裂环， 实现胞质分离；细胞内的中间丝解体，游离在细胞质中。分裂末期，这一过程逆向转变。 （2）细胞骨架的动态不稳定性与细胞生命活动过程的关系 ①在细胞周期中，细胞内的微管经历着动态组装和去组装，在间期和分裂期，其分布或组织 形式存在很大的差异； ②胞质环流和细胞的运动或迁移需要凝胶态与溶胶态的互变； ③细胞的分裂需要纺锤体的组装与解聚； ④细胞核的消失与重新形成也涉及核纤层结构的动态不稳定性； ⑤踏车行为改变了微管或微丝在细胞中分布的部位，可能与细胞的移动有关。","kp":"ch06_s2_5","kps":"动态不稳定性=持续组装/去组装;周期时相分布改变(间期散布、分裂期纺锤体/收缩环/IF解体);与胞质环流、运动、分裂相关"},{"id":"ch06_calc_y2","modI":0,"q":"说明微管动态不稳定性及GTP帽理论，并解释紫杉酚和秋水仙素对微管的不同作用。","a":"①动态不稳定性：微管末端可在生长与缩短之间转换。②GTP帽理论：αβ-微管蛋白二聚体带GTP时易于聚合，聚合后β亚基的GTP水解为GDP。当末端保持GTP-微管蛋白帽时，微管稳定并继续生长；当GTP水解速度超过添加速度、GTP帽丢失（呈GDP帽）时，末端去稳定，微管转为解聚缩短。③紫杉酚：促进微管聚合、抑制解聚，使微管稳定，破坏纺锤体的动态变化，抑制细胞分裂（抗癌药）。④秋水仙素：与微管蛋白结合，抑制微管聚合、促进解聚，破坏纺锤体，使细胞分裂停止于中期。二者作用相反。","kps":"动态不稳定性;GTP帽稳定/GDP帽解聚;紫杉酚促聚合稳定;秋水仙素抑聚合解聚;均阻断纺锤体","type":"机制型","kp":"ch06_s2_9"},{"id":"ch06_calc_y3","modI":0,"q":"设计实验判断某药物是否通过影响微管聚合来抑制细胞分裂。","a":"思路：检测药物处理后微管/纺锤体的状态与细胞分裂情况。①用荧光免疫标记α-微管蛋白（或GFP-微管蛋白）观察间期微管网络和分裂期纺锤体形态。②药物处理后观察微管是否解聚（细胞变圆、纺锤体消失）或过度稳定（纺锤体异常、多极）。③用流式细胞术检测细胞周期分布，判断是否阻滞于M期/中期。④对照：未加药的正常细胞、已知微管药物（紫杉酚/秋水仙素）阳性对照。预期：若药物处理导致微管解聚或异常稳定并伴随M期阻滞，说明其通过影响微管聚合抑制细胞分裂。","kps":"免疫荧光/GFP标记微管;观察纺锤体形态;流式测M期阻滞;对照(正常/已知药物);预期微管异常+M期阻滞","type":"实验设计型","kp":"ch06_s5_0"}],"appcards":[{"front":"微管的主要功能有哪些？","back":"真核细胞内部是高度区域化的体系，微管与生物大分子、细胞器在细胞内的分布，以及 细胞形态的维持具有密切关系。 （1）支持细胞的功能，构成细胞内网状支架，维持细胞形状，固定与支持细胞器的位置。 （2）与细胞器位移和细胞运动有关，染色体的移动、纤毛、鞭毛的运动都是由微管聚合和 解聚产生的。 （3）参与运输，颗粒物质可沿微管移动。 （4）与某些信息的传递有关。","mod":4,"modName":"第一节 微管 · 1.3 MTOC and orienta","points":""},{"front":"试述纤毛和鞭毛的结构与功能。","back":"纤毛（flagella）和鞭毛（cilia）是真核细胞表面的具有运动功能特化结构。 （1）纤毛和鞭毛的结构：是细胞质膜所包被的细长突起，内部由微管构成轴丝结构。由基 体和纤毛轴丝两部分组成。纤毛轴轴丝为“9＋2”排列微管，即外周 9 组二联体微管＋中央鞘 包围的 2 根中央单体微管。外周二联体微管由 A，B 亚纤维组成，A 亚纤维为完全微管，B 亚纤维仅由 10 个亚基构成。中央微管均为完全微管。基体的微管组成为“9＋0”，无中央微 管。 （2）纤毛和鞭毛的运动机相关的滑动学说被普遍认可：纤毛运动由轴丝介导的相邻二联体 间相互滑动所致。由一个二联体的 A 管伸出的动力蛋白臂的马达结构域在相邻的二联体的 B 管上“行走”。","mod":4,"modName":"第一节 微管 · 1.3 MTOC and orienta","points":""},{"front":"叙述什么是微管的 GTP 帽和 GDP 帽，其对微管的动态性质有什么影响。","back":"微管的 GTP 或 GDP 帽就是微管正端αβ微管蛋白二聚体结合 GTP 或 GDP 的状态。 （1）如果微管正端结合的是由结合 GTP 的微管蛋白二聚体组成的 GTP 帽结构，微管就趋 于生长； （2）如果微管的正端结合的是由结合 GDP 的微管蛋白二聚体组成的 GDP 帽结构，这种微 管就趋于缩短。 决定微管正端是 GTP 帽还是 GDP 帽，又受两种因素影响：一是结合 GTP 的游离微管蛋白 二聚体的浓度；二是 GTP 帽中 GTP 水解的速度。当（＋）端形成 GTP 帽，而游离微管蛋 白二聚体的浓度又很高时，微管趋向于生长。由于结合 GTP 的游离微管蛋白二聚体的浓度 降低，使得微管延长的速度下降，随着 GTP 水解的不断进行最后 GTP 帽结构转变成 GDP， 逐渐使微管变得不稳定，趋于解聚。细胞内微管的这两种状态是不断发生的，因为细胞内不 断有微管解聚，又不断地有新微管的组装。","mod":2,"modName":"第一节 微管 · 一、微管","points":""},{"front":"如何用荧光显微镜研究细胞骨架?其基本原理是什么？","back":"用荧光显微镜研究细胞骨架主要是基于两方面的原理。 （1）组成细胞骨架的蛋白亚基能够同小分子的荧光染料共价结合，使细胞骨架带上荧光标 记，发出荧光。 （2）可以制备细胞骨架的荧光抗体，然后用荧光抗体进行细胞骨架的研究。借助于这两方 面原理，可用荧光显微镜研究细胞骨架的动力学。例如，用小分子的荧光染料标记细胞骨架 的蛋白亚基，就可以追踪细胞骨架蛋白在细胞活动中的作用，包括组装、去组装、物质运输 等。这种方法还有一个好处，就是在活细胞时就可以观察。 可用荧光抗体研究以很低浓度存在的蛋白质在细胞内的位置，因为标记的荧光抗体同特异的 蛋白质具有很高的亲和性，只要有相应的蛋白质存在，就一定会有反应。这种反应是特异的， 通过荧光显微镜观察就可确定。荧光抗体既可以直接注射活细胞进行反应，也可以加到固定 的细胞或组织切片中进行反应和分析。用这种方法可对微管、肌动蛋白纤维、中间纤维进行 定位。","mod":0,"modName":"第一节 微管 · 绪论 · 概览","points":""},{"front":"比较胞质骨架三种组分。","back":"胞质骨架三种组分比较如下： 表 10-1","mod":2,"modName":"第一节 微管 · 一、微管","points":""},{"front":"由神经冲动诱发的肌肉收缩基本过程分哪几步？","back":"由神经冲动诱发的肌肉收缩基本过程可以分为：（1）动作电位的产生；（2）Ca2 的释 ＋   放；（3）原肌球蛋白位移；（4）肌动蛋白丝与肌球蛋白丝的相对滑动；（5）Ca2 的回收。 ＋","mod":13,"modName":"第一节 微管 · 1.7.4 染色体运动","points":""},{"front":"如何证明染色体骨架的真实性？","back":"（1）银染法能选择性地显示染色体轴结构；（2）DNA 酶和 RNA 酶处理或用 0.4mol ／LH2sO4 处理去除组蛋白，对染色体轴没有影响，用胰蛋白酶消化则染色体轴破坏，说明 染色体轴是非组蛋白性的；（3）染色体骨架／放射环模型在分子水平上得到两个直接证据。","mod":1,"modName":"第一节 微管 · I 细胞骨架的基本组成及其结构","points":""},{"front":"比较细胞质动力蛋白与驱动蛋白。","back":"（1）两者都是将 ATP 的化学能转化为动能的大的发动机蛋白，都与微管结合在一起， 但只有动力蛋白存在于纤毛和鞭毛的微管之中。 （2）驱动蛋白是通过加末端方式来引导微管的运动，动力蛋白则通过减末端方式来引导微 管运动。 （3）虽然它们在功能上有相似之处，但不是同源蛋白，而且立体结构非常不同。它们并不 属于同一蛋白家族。","mod":7,"modName":"第一节 微管 · 1.6.1 驱动蛋白(kinesin)","points":""},{"front":"列举细菌与动物细胞之间的差别。这些差别很可能是由于在进化过程中出现的部分或所 有现代真核细胞具有的细胞骨架所造成的。","back":"（1）动物细胞相当大，形状多变，而且没有细胞壁，因而需要细胞骨架来支撑并保持 其形状。 （2）动物细胞及其他真核细胞都有细胞核，细胞核靠中间纤维在细胞中成形并维持在适当 的部位。核纤层附着于核被膜的内侧，支持核被膜并使之成形，中间纤维网络包围核并穿行 在细胞质中。 （3）动物细胞可通过改变细胞形状进行移动。这—过程需要肌动蛋白及肌球蛋白的参与。 （4）动物细胞的基因组比细菌大得多，分为许多染色体。细胞分裂时，染色体必须精确地 分配到两个子细胞中。这—过程需要形成有丝分裂纺锤体的微管系统参与。 （5）动物细胞具有胞内细胞器。细胞器在胞内的定位依赖于沿着微管移动的发动机蛋白。 显著的例子是从脊髓到脚部的神经轴突（该轴突可长达 1 m）中，胞内运输小泡（细胞器） 沿着微管的长距离运输。","mod":12,"modName":"第一节 微管 · 1.7.3 鞭毛(flagellae)、纤毛(cilia)运动","points":""},{"front":"什么叫凝胶-溶胶（gel-sol）和溶胶-凝胶（sol-gel）转变？","back":"原生动物中的变形虫，高等动物中的巨噬细胞和白细胞等没有鞭毛、纤毛等运动器官， 但能够依靠细胞体的变化进行移动，叫作变形运动。通常要靠胞质环流形成伪足，细胞沿着 伪足形成的方向前进。细胞内流动的细胞质叫作内质，从尾部流向前进中的伪足。当液流到 达伪足时，流动的细胞质分向细胞的两侧，并形成较硬的外质。其间，位于细胞后部的外质 被破坏并向前方提供新的内质，由此产生内质和外质的循环转变，并引起细胞向前移动。细 胞质由坚硬的凝质状态（外质）向可流动的液态（内质）转变的过程称为凝胶-溶胶转变， 相反的过程叫溶胶-凝胶转变。","mod":12,"modName":"第一节 微管 · 1.7.3 鞭毛(flagellae)、纤毛(cilia)运动","points":""},{"front":"用秋水仙素处理动物细胞，细胞内质网与高尔基体分布有什么改变，为什么？","back":"（1）秋水仙素处理动物细胞后内质网与高尔基体分布的改变 用秋水仙素处理动物细胞，内质网缩回到细胞核周围，高尔基体解体成小的膜泡样结构分散 在细胞质内，细胞内依赖于微管的物质运输系统全面瘫痪。 （2）发生改变的原因 真核细胞内部是高度区室化的结构，细胞中某些物质的合成部位与行使功能部位往往是不同 的。内膜系统把细胞质分割成一个个区室，将物质合成部位和功能行使部位分隔开，微管是 维持区室化的重要结构基础。秋水仙素是微管蛋白组装抑制剂，当用秋水仙素处理动物细胞 后，微管很快解聚，从而造成内质网和高尔基体凝聚化。","mod":4,"modName":"第一节 微管 · 1.3 MTOC and orienta","points":""},{"front":"何谓细胞骨架？如何理解细胞骨架是细胞内的一种动态结构？","back":"（1）细胞骨架的概念 细胞骨架是指由细胞内蛋白质成分组成的一个复合的网架系统，包括微管、微丝和中间丝。 与其他细胞结构相比，细胞骨架在形态结构上具有弥散性、整体性和变动性等特点，这些都 是与它们的功能相适应的。细胞骨架为真核细胞所特有，它不仅是活细胞的支撑结构，决定 了细胞的形状并赋予其强度，而且在细胞多种多样的生理活动（如细胞运动、膜泡运输和细 胞分裂等）中发挥着重要作用。 （2）细胞骨架是一种动态结构的理解 由于细胞骨架与细胞运动有关，在不同的功能状态、不同的细胞周期，细胞骨架是不断地组 装或去组装，因此细胞骨架是细胞内的一种动态结构。","mod":0,"modName":"第一节 微管 · 绪论 · 概览","points":""},{"front":"试分析纤毛不动症发生机制，并以此为例叙述纤毛和鞭毛的运动机制。","back":"（1）纤毛不动症发生机制 纤毛不动症即原发性纤毛运动障碍（PCD），是指纤毛超微结构具有特异的、先天性遗传缺 陷导致的一组疾病。目前认为 PCD 的纤毛异常与内、外动力蛋白臂的缺失或纤毛动力蛋白 臂中 ATP 酶缺乏或代谢异常有关，以致微管滑行缺乏能量，使纤毛摆动受阻。 （2）纤毛和鞭毛的运动机制 纤毛和鞭毛的运动本质是轴丝动力蛋白介导的相邻二联体微管之间的相互滑动。纤毛和鞭毛 摆动的特征是从基体产生滑动，沿着轴丝将弯曲传递到尾部，因此，二联管之间的滑动必须 转换为弯曲运动。当轴丝上任意两点的滑动速率不等时，滑动即可转换为弯曲。 ①滑动速率的差异主要来自维持轴丝结构的连接蛋白，它们在一定程度上限制了二联管的自 由滑动； ②在某一时间某一位置，只有部分动力蛋白臂被激活，激活一半的动力蛋白臂使轴丝朝一边 弯曲，激活另一半则朝另一边弯曲。二条动力蛋白臂的作用不同，内臂产生滑动，导致轴丝 弯曲，而外臂可以加快滑动的速度。","mod":8,"modName":"第一节 微管 · 1.7 微管的功能","points":""},{"front":"通过本章的学习，你对生命体的自组装原则有何认识？","back":"我对生命体自组装原则的认识如下： （1）细胞内的复杂结构可由简单的分子组装而成，其组装过程受到细胞本身的调节，这样 便于细胞在不同生理状态下调节细胞结构的组织形式，执行特定的功能。 （2）多种结构相互联系，共同完成细胞的生命活动。 （3）生命体在装配过程中受到多种因素影响。如影响微管组装的因素有秋水仙素、紫杉醇、 长春花碱；影响微丝组装的因素有细胞松弛素、鬼笔环肽。 （4）生命体自组装具有高度的时空顺序性。","mod":0,"modName":"第一节 微管 · 绪论 · 概览","points":""},{"front":"除支持作用和运动功能外，细胞骨架还有什么功能？怎样理解“骨架”的概念？","back":"（1）细胞骨架的其他功能 为物质运输提供轨道、参与肌肉收缩和细胞分化、介导染色体的移动和动物细胞胞质分裂、 形成细胞的特化结构等。 （2）“骨架”的理解 ①骨架是指真核细胞内一个复杂的由特异蛋白质组成的纤维网架结构，具有支持功能，在细 胞形态维持、膜性细胞器定位和移动过程中具有重要的作用。 ②理解骨架概念时的注意事项： a．细胞骨架是一种动态平衡的结构； b．具有多种功能； c．由蛋白质组装而成，组装的过程受到信号的调节。","mod":1,"modName":"第一节 微管 · I 细胞骨架的基本组成及其结构","points":""},{"front":"什么是分子马达？举例说明（至少 3 个）。","back":"分子马达（molecular motor），主要是指依赖于微管的驱动蛋白、动力蛋白和依赖于微 丝的肌球蛋白这三类蛋白超家族的成员。它们既能与微管或者微丝结合，又能与一些细胞器 或膜状小泡特异性结合，并利用水解 ATP 所产生的能量有规则地沿微管或微丝等细胞骨架 纤维运输所携带的“货物”。 （1）肌球蛋白是与微丝相关的一类分子马达。其共同特征是都含有一个作为马达结构域的 头部。其马达结构域包含一个微丝结合位点和一个具有 ATP 酶活性的 ATP 结合位点。 ①Ⅱ型肌球蛋白存在于多种细胞，包含 2 条重链和 4 条轻链。头部即马达结构域，尾部主要 起结构作用。Ⅱ型肌球蛋白尾尾相接所构成的双极纤维能介导相邻的微丝相互滑动。 ②Ⅰ型肌球蛋白头部亦为马达结构域，在 ATP 存在时可沿微丝运动。其尾部结构域具有多 样性，能与多种细胞组分结合，通过头部驱动或细胞质膜作相对于微丝的运动。V 型肌球蛋 白是二聚体马达蛋白，具有两个头部，交替与微丝结合可以确保整个分子以及所运载的“货 物”始终不与微丝脱离。 （2）驱动蛋白是一类蛋白质超家族，与微管相关。通常由 2 条重链和 2 条轻链组成，它们 共有保守的“马达”域，内有 ATP 结合位点和微管结合位点。马达结构域在重链的 N 端，介 导物质向微管的正极运动；而另一些少数驱动蛋白的马达结构域在重链的 C 端，介导物质 向微管的负极运动。 驱动蛋白的马达结构域具有两个重要的功能位点： ①ATP 结合位点； ②微管结合位点。 有关驱动蛋白沿微管运动的分子模型有两种：步行模型和尺蠖爬行模型。大多数学者承认步 行模型：驱动蛋白的两个球状头部交替向前，每水解一分子 ATP，落在后面的那个马达结 构域将移动两部的距离，即 16nm，并循环该过程。 （3）动力蛋白是马达蛋白中最大、移动速度最快的成员： ①轴丝动力蛋白，在纤毛与鞭毛中发现，与纤毛和鞭毛的运动相关； ②胞质动力蛋白，在真核细胞胞质内发现，与细胞内介导微管从正极向负极端的膜泡运输以 及有丝分裂动粒和纺锤体的共定位有关。 动力蛋白由 2 条或 3 条重链，多条轻链及中间链组成。其马达结构域位于重链 C 端，轴丝 动力蛋白有 3 个马达结构域，胞质动力蛋白有 2 个马达结构域。","mod":0,"modName":"第一节 微管 · 绪论 · 概览","points":""},{"front":"试述三种胞质细胞骨架的主要成分、形态结构、功能及特异性药物。","back":"细胞骨架（cytoskeleton）是指真核细胞中复杂的蛋白纤维网架体系。广义的细胞骨架包 括细胞核骨架，细胞质骨架，细胞膜骨架和细胞外基质。狭义的细胞骨架是指细胞质骨架， 包括微丝（microfilament，MF）、微管（microtubule，MT）、中间纤维（inter- mediated filament， IF）。 （1）微管的形态结构：中空圆柱状，直径 15nm，一般长几微米，微管蛋白是与肌动蛋白相 似的一种酸性蛋白质，常常以二聚体存在（αβ-微管蛋白）。 微管的功能：①支架作用：维持细胞形态、固定细胞器。②细胞收缩，伪足运动；如纤毛、 鞭毛。③细胞器位移、染色体分裂与位移。④胞质内物质运输。 特异性药物：紫杉酚：抗肿瘤药物，研究表明它对微管的作用与传统的抗癌药长春花碱和秋 水仙碱等相反，它能促进微管的聚合、抑制微管的解聚。是微管的特异性稳定剂。 （2）微丝的形态结构：微丝存在很普遍，具有可变结构，直径 6 μm，由肌动蛋白组成，与 微管共同构成细胞支架。 微丝的功能：①与微管共同形成细胞支架，以维持细胞形状。②具有运动功能，与细胞质的 运动紧密相关。③与细胞器关系密切。④细胞内信号传递、蛋白质合成支架。 特异性药物：鬼笔环肽：特异性与微丝侧面结合，增强其稳定性，抑制微丝解聚，对微丝具 有稳定作用。荧光标记的鬼笔环肽可特异性的显示微丝。是微丝的特异性稳定剂。 细胞松弛素：可以切断微丝，并结合在微丝正极阻抑肌动蛋白聚合，因而可以破坏微丝的三 维网络，特异性的抑制微丝的装配。是微丝的特异性抑制剂。 （3）中间纤维：大小介于微管和微丝之间，结构复杂。中间纤维具有严格的组织特异性， 不同类型细胞含有不同 IF。按其组织来源及免疫原性可分为 5 类：①角蛋白纤维：为上皮 细胞特有，具有α和β两类，β角蛋白存在于体表、体腔的上皮细胞中，α角蛋白形成头发、 指甲等坚韧结构；②波形纤维：存在于间充质细胞及中胚层来源的细胞中；③神经胶质纤维： 存在于星形神经胶质细胞；④结蛋白纤维：存在于肌肉细胞；⑤神经元纤维：存在于神经元 中。 此外细胞核中的核纤层蛋白（lamin）也是一种中间纤维。 肿瘤细胞转移后仍保留源细胞的 IF，因此可用 IF 抗体来鉴定肿瘤的来源。如乳腺癌和胃肠 道癌，含有角蛋白，因此可断定它来源于上皮组织。而且大多数细胞中只含有一种中间纤维 （少数细胞含有两种以上，如骨骼肌细胞含有结蛋白和波形蛋白）。中间纤维这种严格的组 织特异性，就被应用于肿瘤临床鉴别诊断，以鉴别肿瘤细胞。 至今尚未发信中间纤维的特异性药物。","mod":1,"modName":"第一节 微管 · I 细胞骨架的基本组成及其结构","points":""},{"front":"动态不稳定性造成微管迅速伸长或缩短。设想一条单一的处于缩短状态的微管： （1）如果要停止缩短并进入伸长状态，其末端必须发生什么变化？ （2）发生这一转换后微管蛋白的浓度有什么变化？ （3）如果溶液中只有 GDP 而没有 GTP，将会发生什么情况？ （4）如果溶液中存在不能被水解的 GTP 类似物，将会发生什么情况？","back":"（1）由于失去了 GTP 帽，即末端的微管蛋白亚基都以结合 GDP 的形式存在，微管因 而缩短。溶液中带有 GTP 的微管蛋白亚基仍会添加到末端，但是寿命很短，因为 GTP 可能 被水解，或者围绕着的微管解体使其脱落下来。但是如果足够的带有 GTP 的亚基以足够快 的速度添加上去并覆盖了微管末端带有 GDP 的微管蛋白亚基，   这时可产生一个新的 GTP 帽， 微管就可重新开始生长。 （2）当微管蛋白浓度较高时，GTP 亚基的添加速率会比较高，因而缩短微管转变为增长微 管的频率也会随微管蛋白浓度的升高而增加。这种调节机制使该系统达到自主平衡：较多微 管的缩短可造成高浓度的游离微管蛋白，转为增长的微管也就增多；反之，增长的微管多了， 游离微管蛋白浓度下降从而 GTP-亚基的添加速率也下降，在某些部位 GTP 水解的速率会超 过添加速率，造成 GTP 帽破坏，微管又开始进入缩短状态。 （3）如果只有 GDP 存在，微管会持续短缩，并最终消失，因为结合有 GDP 的微管蛋白二 聚体之间的亲和力十分低，不可能被稳定地添加到微管上。 （4）如果有 GTP 存在但不能被水解，那么微管将持续增长，直到所有游离的微管蛋白亚基 被消耗完为止。","mod":2,"modName":"第一节 微管 · 一、微管","points":""},{"front":"细胞中同时存在几种骨架体系有什么意义？是否是物质和能量的一种浪费？","back":"（1）细胞骨架是指细胞内以蛋白质纤维为主要成分的网络结构，细胞中同时存在的骨 架体系为微丝、微管和中间丝，这三种细胞骨架的意义在于它们在细胞的生命活动中各自的 功能。 ①微丝的功能主要有：肌细胞中参与肌原纤维收缩；非肌细胞中参与胞质分裂、胞质环流、 吞噬作用、细胞变形运动、膜泡运输、细胞黏着与连接（黏着带与黏着斑）、微绒毛的支撑 结构等。 ②微管的功能主要包括：支架作用，维持细胞形态、定位细胞器，作为细胞内物质运输通道， 作为纤毛、鞭毛的运动元件，构成纺锤体参与细胞分裂等。 ③中间丝的功能有：为细胞提供机械强度支持，参与细胞连接（桥粒与半桥粒），维持核膜 稳定等。 （2）三种骨架成分在细胞中同时存在不是物质和能量的一种浪费，理由如下： 三种骨架成分在细胞中同时存在，自成系统，但又互相联系，互不重合。微丝分布在靠近细 胞膜的部位，微管、中间丝从细胞核向细胞周缘放射状延伸。它们在功能上相互配合、相互 协调，缺乏任何一种骨架成分都会引起细胞生命活动的异常。因此细胞中同时存在几种骨架 体系并不是物质和能量的浪费。","mod":0,"modName":"第一节 微管 · 绪论 · 概览","points":""},{"front":"为什么说细胞骨架是细胞结构和功能的组织者？细胞内一些细胞器和生物大分子的不对 称分布有什么意义？","back":"（1）细胞骨架是细胞结构和功能的组织者的原因 ①细胞骨架形成了细胞的多种结构：微管能形成鞭毛、纤毛、基体和中心体等结构，微丝参 与微绒毛、收缩环、应力纤维、黏着斑和黏着带的形成，中间丝对维持细胞核的形态和形成 桥粒等具有重要的作用； ②细胞骨架在细胞形态发生和维持等方面具有重要的作用； ③细胞骨架在物质运输、信号传递、细胞运动、细胞分裂等活动中具有重要的作用。 （2）细胞内一些细胞器和生物大分子不对称分布的意义 ①细胞内一些细胞器和生物大分子的不对称分布与细胞不同结构或部分具有特定的功能是 相互联系的，这种不对称分布与细胞骨架的组织方式有关； ②神经细胞中的轴突和树突具有大量的胞质骨架，这与轴突和树突形态的维持及物质的定向 运输有关； ③桥粒、半桥粒、黏着斑和黏着带含有丰富的细胞质骨架结构，这与锚定连接的形成有关； ④细胞内一些细胞器和生物大分子的不对称分布特点是与细胞特定结构的功能相一致的。","mod":14,"modName":"第一节 微管 · 1.7.5 细胞信号转导","points":""},{"front":"如何理解细胞骨架的动态不稳定性？这一现象与细胞生命活动过程有什么关系？","back":"（1）细胞骨架的动态不稳定性的理解 ①细胞骨架的动态不稳定性是指骨架纤维的持续组装与去组装，通过蛋白亚基的添加和解聚 实现骨架长度的延长或缩短。 ②细胞骨架是一种高度动态的结构体系，细胞的运动是通过肌动蛋白的聚合与解聚完成的。 ③在细胞周期的不同时相，细胞骨架具有完全不同的分布状态。间期微丝、微管分布在细胞 质中，中间丝在细胞质和细胞核均有分布。分裂期时，细胞质中的微管迅速解体，用于纺锤 体微管的延长，牵拉染色体运动；微丝解聚，在细胞赤道板分裂沟部位组装成胞质分裂环， 实现胞质分离；细胞内的中间丝解体，游离在细胞质中。分裂末期，这一过程逆向转变。 （2）细胞骨架的动态不稳定性与细胞生命活动过程的关系 ①在细胞周期中，细胞内的微管经历着动态组装和去组装，在间期和分裂期，其分布或组织 形式存在很大的差异； ②胞质环流和细胞的运动或迁移需要凝胶态与溶胶态的互变； ③细胞的分裂需要纺锤体的组装与解聚； ④细胞核的消失与重新形成也涉及核纤层结构的动态不稳定性； ⑤踏车行为改变了微管或微丝在细胞中分布的部位，可能与细胞的移动有关。","mod":13,"modName":"第一节 微管 · 1.7.4 染色体运动","points":""}],"jyq":[{"id":"jyq_ch06_1","kind":"fill","q":"2007年国际十大科技新闻之一的“万能细胞”技术的核心内容是。","a":"人体皮肤细胞改造成类似胚胎干细胞的万能细胞。","src":"中山大学，2009年","kp":null,"oe":["2007年诱导多能干细胞(iPS)技术将人体皮肤细胞重编程为类似胚胎干细胞的万能细胞。"]},{"id":"jyq_ch06_2","kind":"short","q":"为什么解决生命科学的问题不能仅靠分子生物学而要靠细胞生物学？","a":"在生命活动中，随着细胞周期的进行和细胞代谢状态的不同，各种反应复合物，包括细胞器乃至整个细胞要不断进行组装和去组装。因此，细胞生命活动的基础是细胞组装活动，而这些组装活动又不题的缘由。的科学家，请列举获奖者的主要贡献。现了RNA（核糖核酸）干扰机制。法尔和梅洛获奖是因为他们“发现了控制遗传信息流动的基本机制”，这一机制为控制基因信息提供了基础性的依据。2007年诺贝尔生理学或医学奖授予来自美国的马里奥·卡佩奇、奥利弗·史密斯和来自英国的马丁·伊文思，他们因胚胎干细胞研究获该奖项。这三位科学家是因为“在涉及胚胎干细胞和哺乳动物DNA重组方面的一系列突破性发现”而获得这一殊荣的。2008年诺贝尔生理学或医学奖授予德国科学家哈拉尔德·楚尔·豪森及两名法国科学家弗朗索瓦丝·巴尔-西诺西和吕克·蒙塔尼。豪森的获奖成就是发现了人乳头状瘤病毒（HPV），这种病毒是导致女性第二常见癌症一宫颈癌的罪魁祸首。巴尔-西诺西和蒙塔尼的获奖成就是发现了人类免疫缺陷病毒（HIV），也就是人们常说的艾滋病病毒。2009年诺贝尔生理学或医学奖授予美国科学家伊丽莎白·布莱克本、卡萝尔·格雷德和杰克·绍斯塔克，以表彰他们“发现端粒和端粒酶是如何保护染色体的”。2011年诺贝尔生理学或医学奖一分为二，一半授予比特勒和霍夫曼，以表彰他们在激活人体先天免疫能力方面的重大发现；另一半授予斯坦曼，他在对获得性免疫系统的研究中发现了树突细胞及其特殊功能。2012年诺贝尔生理学或医学奖授予英国发育生物学家约翰·格登、日本京都大学物质-细胞统合系统据点iPS（诱导多功能干细胞）细胞研究中心主任长山中伸弥，他们因在细胞核重新编程研究领域的杰出贡献而获奖。第一章绪论核转录的分子基础”研究领域作出的贡献而获奖。2008年日本科学家下村修、美国科学家马丁·沙尔菲和美籍华裔科学家钱永健因在发现和研究绿色荧光蛋白方面作出的贡献而获奖。美籍印度科学家拉马克利什南，美国科学家斯太茨和以色列科学家雍纳斯因其对核糖体的结构和作用的研究而获得2009年度诺贝尔化学奖。美国科学家罗伯特·莱夫科维茨和布莱恩·克比尔卡因“G蛋白偶联受体研究”获得2012年诺贝尔化学奖。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch06_3","kind":"short","q":"蓝藻（Cyanophyceae）","a":"又称蓝绿藻、蓝细菌，能进行与高等植物类似的光合作用，以水为电子供体，放出02，与光合细菌的光合作用的机制不一样，因此被认为是最简单的植物。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch06_4","kind":"short","q":"质膜有何基本特性？受哪些因素影响？","a":"质膜具有不对称性和流动性。不对称性：膜脂分布的不对称性表现在：①膜内层和外层所含脂质分子的种类不同；②膜内外磷脂层所带电荷不同；③膜内外层磷脂臻物饱稽不同×4糖脂只第四章细胞质膜分布在外层脂质中。膜蛋白的分布是绝对不对称的：①糖蛋白的糖链主要分布在膜的外表面；②膜受体分子均分布在膜外层脂质分子中；③腺苷酸环化酶分布在膜的内表面。膜的流动性是由膜内部脂质分子和蛋白质分子的运动性所决定的。膜脂的流动性和膜蛋白的运动性使得细胞膜成为一种动态结构。膜脂分子的运动表现在：旋转异构、左右摆动、旋转运动、侧向扩散、倒翻运动。膜蛋白的分子运动包括侧向扩散运动和旋转扩散运动等。影响膜流动性的因素有：胆固醇；磷脂分子脂肪酸链；卵磷脂与鞘磷脂的比例。总之，流动性是质膜的一种基本特性，必须保持在适当程度才能保证质膜的正常功能。当细胞对其膜的流动性失去自我调节能力时，将会发生膜的功能障碍或细胞病变。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch06_5","kind":"judge","q":"溶酶体的膜含有蛋白质泵，可用ATP水解释放的能量将质子泵出溶酶体，从而维持溶酶体腔的低pH。","a":"错","src":"中山大学，2009年","kp":null,"oe":["溶酶体腔低pH确靠质子泵维持，但题中把泵的方向写成“泵出”，故有误。","应是由V型质子泵将H⁺泵入溶酶体内，而非泵出，原说法方向错误。"]},{"id":"jyq_ch06_6","kind":"short","q":"动物体内细胞外空间通常已有大量的Ca存在，为何肌肉细胞中在肌质网内仍储存高浓度的Ca²+？","a":"肌质网膜上的Ca²+-ATP酶将细胞质基质中的Ca²+泵人肌质网腔中，贮存起来，当受到神经冲动刺激后，Ca释放出来，肌肉收缩。在多数真核细胞中，细胞外的信号物质也可以引起Ca向细胞质基质中释放。内质网具有储备Ca的功能，在内质网膜上也存在与肌肉细胞的肌质网膜上相同的的肌醇三磷酸（IP）的受体。此外，在内质网中至少发现包括Bip在内的4种以上的钙结合蛋白，其中一种与肌质网中钙的结合蛋白相同。每个钙结合蛋白的分子可与30个左右的Ca结合，因为内质网腔中的钙结合蛋白可达30~100mg/mL，从而使内质网中的浓度高达3mmol/L。","src":"武汉大学，2007年","kp":null},{"id":"jyq_ch06_7","kind":"short","q":"如何从组织中分离、鉴定线粒体？","a":"可用差速离心法。因为细胞中各种细胞器或颗粒的大小、密度不一样，因此可以通过差速离心的方法得到不同的组分。具体做法是：先将组织做成匀浆，然后对匀浆进行差速离心，离心分离前先得到细胞核，然后是线粒体。如果一次离心得到的线粒体不够纯净，可以进行第二次甚至第三次。至于具体的离心速度和最后对线粒体组分的鉴定可以上网查些相关资料和数据，并且通过具体实验确定最佳方案。","src":"上海交通大学，2007年","kp":null},{"id":"jyq_ch06_8","kind":"mcq","q":"下列哪些细胞器在结构上和功能上有密切关系（）。","o":["A. 线粒体","B. 核膜","C. 内质网","D. 高尔基体"],"a":"B","src":"华中农业大学，2009年","kp":null,"e":"核膜与内质网在结构上连续、功能上协同，二者关系最为密切。","oe":["线粒体为独立双层膜细胞器，与本题所指密切关系不直接。","正确：核膜与内质网相连通，在结构与功能上密切相关。","内质网虽与核膜相连，但本题所问密切关系对应核膜，故选B。","高尔基体与内质网有运输联系，但本题所给答案为B。"]},{"id":"jyq_ch06_9","kind":"short","q":"信号转导（signaltransduction）","a":"指外界信号（如光、电、化学分子）与细胞表面受体作用，通过影响细胞内信使的水平变化，进而引起细胞应答反应的一系列过程。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch06_10","kind":"judge","q":"肌动蛋白有GTP结合位点。","a":"对","src":"华中师范大学，2008年","kp":null,"oe":["原答案判“对”，但经典教材认为肌动蛋白结合ATP，此说本身可疑。","肌动蛋白含ATP结合位点而非GTP，结合GTP的是微管蛋白，故该说法应判错。"],"doubt":1},{"id":"jyq_ch06_11","kind":"short","q":"细胞信号转导的机制有哪些？与肿瘤发生相关的有哪些？","a":"细胞信号转导的主要有：①G蛋白介导的细胞信号转导途径；②受体TPK介导的细胞信号转导途径。Ras基因的发现者，美国MIT肿瘤研究中心的RobertA.Weinberg教授认为，有四条细胞信号转导途径的异常与肿瘤的发生有密切关系，它们包括TGF-周期素途径、p19-p53途径、端粒酶途径和Ras-MARP途径。除此之外，还有其他一些信号转导途径与肿瘤的发生和发展有关。有关报告阐述了这四条途径。TGF-β及其相关生长因子（如BMP、Activin等）参与调节多种生命过程，影响多种细胞增殖、分化和调亡。","src":"中国科学院，2009年","kp":null},{"id":"jyq_ch06_12","kind":"judge","q":"细胞在有丝分裂期微丝发生收缩，故细胞形态变圆。","a":"错","src":"南京师范大学，2008年","kp":null,"oe":["有丝分裂期皮层肌动蛋白-肌球蛋白收缩使细胞变圆，此说在现今看基本成立。","原答案判错：微丝收缩成收缩环主要发生在胞质分裂期，M期变圆多归因于微管重排。"],"doubt":1},{"id":"jyq_ch06_13","kind":"short","q":"缺少动力蛋白臂（dyneinarm）的鞭毛无法运动。","a":"对。蛋白的基因类群。【答案】错。","src":"南京师范大学，2009年","kp":null},{"id":"jyq_ch06_14","kind":"judge","q":"为了使肌细胞质膜去极化，肌质网（SR)中的Ca²+泵使用ATP水解释放的能量将Ca²+从SR的腔输往胞质溶胶，以启动肌收缩。","a":"错","src":"中山大学，2009年","kp":null,"oe":["肌收缩确需胞质Ca²⁺升高，但把SR释放Ca²⁺说成由钙泵耗能完成是错的。","钙泵(SERCA)耗能把胞质Ca²⁺泵回SR腔；SR释钙经钙释放通道被动完成，故该说法错误。"]},{"id":"jyq_ch06_15","kind":"short","q":"除微管、微丝、中间纤维及其结合蛋白构成的骨架外，广义细胞骨架还包括及。","a":"细胞外基质；膜骨架；细胞质骨架；核骨架。第十章细胞骨架","src":"湖北大学，2008年","kp":null},{"id":"jyq_ch06_16","kind":"fill","q":"细胞质骨架主要由和三类纤维组成。","a":"微管；微丝；中间纤维。","src":"南京师范大学，2008年","kp":null,"oe":["微管由α、β微管蛋白二聚体组装成中空管状纤维，是细胞骨架之一。","微丝由肌动蛋白构成，参与细胞形态维持、运动与收缩。","中间纤维由角蛋白等组织特异性蛋白构成，起机械支撑作用。"]},{"id":"jyq_ch06_17","kind":"fill","q":"肌球蛋白有两个酶功能位点，肌球蛋白可被水解为头部和尾部重轻链两段。头部重段又可被水解为两段。","a":"胰蛋白酶；木瓜蛋白酶。","src":"山东大学，2006年","kp":null,"oe":["用胰蛋白酶水解肌球蛋白，可得轻酶解肌球蛋白(尾部)和重酶解肌球蛋白(头部)。","重酶解肌球蛋白再用木瓜蛋白酶水解，可得到S1头部和S2颈部两段。"]},{"id":"jyq_ch06_18","kind":"mcq","q":"下列哪些因素促进微管的组装（）。","o":["A. GTP","B. Mg2+","C. MAP","D. 高Ca²+"],"a":"A","src":"华中农业大学，2009年","kp":null,"e":"GTP、Mg2+和微管结合蛋白（MAP）均促进微管组装，高Ca2+抑制组装；本题按所给答案选GTP。","oe":["正确：GTP与微管蛋白结合，是微管组装的必需条件。","错误：Mg2+也促进组装，但本题所给答案为GTP。","错误：MAP能稳定微管、促进组装，本题按答案选A。","错误：高浓度Ca2+促使微管解聚，抑制组装。"]},{"id":"jyq_ch06_19","kind":"mcq","q":"(）是一种马达蛋白。","o":["A. Ras蛋白","B. 肌动蛋白","C. 肌钙蛋白","D. 驱动蛋白"],"a":"D","src":"湖北大学，2008年","kp":null,"e":"驱动蛋白沿微管定向运动并运输囊泡，是典型的马达蛋白。","oe":["错误：Ras蛋白是GTP结合的信号转导蛋白，不是马达蛋白。","错误：肌动蛋白是微丝的结构蛋白，本身不是马达蛋白。","错误：肌钙蛋白是调节肌肉收缩的钙结合蛋白，无马达功能。","正确：驱动蛋白水解ATP沿微管定向运输，属于马达蛋白。"]},{"id":"jyq_ch06_20","kind":"mcq","q":"下列属于细胞骨架的蛋白是（）。","o":["A. 微管蛋白、木质素和驱动蛋白","B. 微管、肌球蛋白和微丝","C. 微丝、中间纤维和微管","D. 肌动蛋白、肌球蛋白和中间丝"],"a":"C","src":"南京师范大学，2008年","kp":null,"e":"细胞骨架由微丝、中间纤维和微管三种纤维构成，故C正确。","oe":["错误：木质素是植物细胞壁成分，不属于细胞骨架。","错误：微管、微丝是结构名称，肌球蛋白属马达蛋白，表述不规范。","正确：微丝、中间纤维和微管共同构成细胞骨架。","错误：中间丝是结构名称，肌球蛋白也不属于骨架的主要成分。"]},{"id":"jyq_ch06_21","kind":"mcq","q":"细胞变形运动的本质是（）。","o":["A. 细胞膜迅速扩张使细胞局部伸长","B. 胞内微丝迅速重组装使细胞变形","C. 胞内微管迅速解聚使细胞变形","D. 胞内中间纤维重聚合使细胞变形"],"a":"B","src":"南开大学，2009年","kp":null,"e":"细胞变形运动依赖微丝（肌动蛋白）迅速组装与解聚形成伪足，故B正确。","oe":["错误：变形运动靠微丝重组，不是单纯细胞膜扩张伸长。","正确：胞内微丝迅速重组装，使细胞伸出伪足而变形移动。","错误：微管解聚主要与有丝分裂等有关，非变形运动的本质。","错误：中间纤维起机械支持作用，不驱动细胞的变形。"]},{"id":"jyq_ch06_22","kind":"short","q":"请设计一个实验，用两种方法来说明温度变化对细胞骨架的影响，实验包括方法、仪器、步骤、预期实验结果、分析。","a":"材料与仪器：新鲜洋葱，M-缓冲液，磷酸缓冲液，考马斯亮蓝等缓冲液和染色液，普通冰箱，低温冰箱，培养箱，显微和成像系统。C培养箱和常温中1h。②撕取每片鳞片的内表皮，放入磷酸缓冲液，抽提骨架以外蛋白，用M-缓冲液冲洗三次，同时使骨架稳定，用考马斯亮蓝染色，冲洗并干燥后拍摄细胞骨架照片分析。预期结果：常温下细分析：低温和高温会引起微丝、微管和中间纤维解聚，骨架相关蛋白就会消失。","src":"华东师范大学，2009年","kp":null},{"id":"jyq_ch06_23","kind":"short","q":"说明微管的装配过程和常见微管特异性药物的作用？","a":"①装配过程：二聚体→原丝→片状带→合拢成一段微管一两端延伸→成熟微管。②微管特异性药物。紫杉醇：促进聚合，稳定微管；秋水仙素：低浓度，导致微管解聚；长春花碱：抑制组装。","src":"华中农业大学，2009年","kp":null},{"id":"jyq_ch06_24","kind":"short","q":"细胞内运输小泡能否沿中间纤维移动？为什么？","a":"不能，因为中间纤维无极性，其两端在化学组上没有任何的区别，假设一个分子马达结合在中间纤维上，将无法感知一个确定的方向，无法进行定向的运动。只有微管和微丝才与分子马达蛋白结合。微管与驱动蛋白和动力蛋白结合，微丝与肌球蛋白结合。","src":"上海交通大学，2007年","kp":null},{"id":"jyq_ch06_25","kind":"short","q":"细胞中同时存在几种骨架体系有什么意义？","a":"是否是物质和能量的一种浪费？在细胞中，现在提到的有细胞质骨架、细胞核骨架、细胞膜骨架及染色体骨架，每种骨架及骨架的各种组成成分各有不同的功能。多种骨架体系存在有利细胞之间的分工与协作，当一种结构受到破坏时，其他结构依然可以起到支撑作用。对细胞完成正常的生理活动具有重要意义。所以，不能看成是物质和能量的一种浪费。什么意义？细胞骨架形成了细胞的多种结构。微管能形成鞭毛、纤毛、基体和中心体等结构，微丝参与微绒毛、收缩环、应力纤维、黏合斑和黏合带的形成，中间丝对维持细胞核的形态和形成桥粒等具有重要的作用。细胞骨架在细胞形态发生和维持等方面具有重要的作用。除支持功能外，它还在物质运输、信号传递、细胞运动、细胞分裂等活动中具有重要的作用。因此说细胞骨架是细胞结构和功能的组织者。细胞内一些细胞器和生物大分子的不对称分布，与细胞不同结构或部分具有特定的功能是相互联系的。这种不对称分布与细胞骨架的组织方式有关。例如，细胞皮层含有丰富的微丝结构，这与皮层中的微丝参与膜骨架的形成、细胞的吞噬活动和细胞的运动等有关；神经细胞中的轴突和树突具有大量的胞质骨架，这与轴突和树突形态的维持以及物质的定向运输有关；桥粒、半桥粒、黏合斑和黏合带含有丰富的胞质骨架结构，这与锚定连接的形成有关。因此细胞内一些细胞器和生物大分子的不对称分布这一特点是与细胞特定结构的功能相一致的。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch06_26","kind":"short","q":"如何理解细胞骨架的动态不稳定性？","a":"这一现象与细胞生命活动过程有什么关系？细胞骨架的动态不稳定性是指细胞骨架结构在一定条件下可以动态去组装或者重新组装。在生命活动过程中这一特性具有非常重要的生物学意义。①在细胞周期中，细胞内的微管经历着动态组装和去组装，在间期和分裂期，其分布或组织形式存在很大的差异；②胞质环流和细胞的运动或迁移需要凝胶与溶胶的互变；③细胞的分裂需要纺锤体的组装与解聚；④细胞核的消失与重新形成也涉及核纤层结构的动态不稳定性；5踏车行为不是没有意义的，它改变了微管或微丝在细胞中分布的部位，可能与细胞的移动有关。因此细胞骨架的动态不稳定性在生命过程中具有重要的作用。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch06_27","kind":"short","q":"用过量的TdR处理细胞一次，可将所有细胞的细胞周期抑制在G/S交界期。","a":"错。改：用TdR处理细胞来确定细胞个阶段的时长。","src":"华中师范大学，2007年","kp":null},{"id":"jyq_ch06_28","kind":"judge","q":"在所有动物细胞中，中心体是主要的微管组织中心。","a":"对","src":"南京师范大学，2008年","kp":null,"oe":["中心体的中心粒周围物质含γ-微管蛋白，是动物细胞微管装配的主要组织中心。","若强调“所有动物细胞”则过绝对，如哺乳动物成熟红细胞无中心体。"]},{"id":"jyq_ch06_29","kind":"judge","q":"亮氨酸拉链是组蛋白的一种结构模式。","a":"对","src":"华中师范大学，2008年","kp":null,"oe":["原答案判“对”，但亮氨酸拉链通常见于转录因子而非组蛋白，此判可疑。","亮氨酸拉链是Jun、Fos等转录因子的结构模式，组蛋白采用组蛋白折叠，故应判错。"],"doubt":1},{"id":"jyq_ch06_30","kind":"judge","q":"中心体的复制独立于染色体的复制。","a":"对","src":"上海交通大学，2007年","kp":null,"oe":["中心体在S期自主复制，与DNA复制在时间上相关，但机制上相对独立。","若认为中心体随染色体一起复制则错，中心体复制与DNA复制是两个独立过程。"]},{"id":"jyq_ch06_31","kind":"fill","q":"染色体组型是根据和排列而成的。","a":"染色体形态；着丝粒位置。","src":"湖北大学，2008年","kp":null,"oe":["核型分析先依据染色体的相对长度、臂比等形态特征进行排列。","再按着丝粒的位置（中着丝粒、亚中着丝粒等）对染色体分组排列。"]},{"id":"jyq_ch06_32","kind":"short","q":"简述核仁的结构与功能。","a":"核仁的主要结构式有颗粒组分以及纤维中心、致密纤维组分和核仁基质组成。功能体现在以简图来表示。【答案】SG2核仁解体G1M核膜开始消失细胞核仁细胞核膜(XX)核仁重组核膜开始形成图11-1核仁结构与细胞同期的关系G期一准备DNA复制；S期一DNA复制；G期一准备有丝分裂；M期一细胞分裂期，包括前期、中期、后期和末期","src":"华中师范大学，2008年","kp":null},{"id":"jyq_ch06_33","kind":"short","q":"怎样显示并鉴定核仁组织中心的存在？","a":"①核仁组织中心是有丝分裂中期染色体中的结构，位于次痕处。②是rDNA重复序列所在处。③荧光染料标记rDNA基因，制备探针。④制备中期核型，进行原位杂交。荧光显微镜观察，确定核仁组织中心位置及数目。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch06_34","kind":"short","q":"怎样证明染色体次缢痕处是否有核仁组织中心的存在？","a":"①核仁组织中心是有丝分裂中期染色体中的结构，位于次痕处。②是rDNA重复序列所在处。③荧光染料标记rDNA基因，制备探针。④制备中期核型，进行原位杂交。5荧光显微镜观察.确定核仁组织中心位置及数目。","src":"南京师范大学，2009年","kp":null},{"id":"jyq_ch06_35","kind":"short","q":"星体微管（astralmicrotubule）","a":"是在两极由中心体放射出的微管。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch06_36","kind":"judge","q":"有丝分裂后期开始，所有姐妹染色单体同时分裂，各单体分别向两极移动。","a":"对","src":"南京师范大学，2009年","kp":null,"oe":["后期启动时分离酶切开黏连蛋白，所有姐妹染色单体几乎同时分离移向两极。","若认为染色单体逐个分离则错，后期分离由黏连蛋白被同步切开所致。"]},{"id":"jyq_ch06_37","kind":"fill","q":"细胞松弛素B处理对动物细胞有丝分裂的影响是胞质，结果形成细胞。","a":"不分裂；双核。","src":"南京师范大学，2009年","kp":null,"oe":["细胞松弛素B破坏微丝，使有丝分裂末期细胞质不能缢缩，故胞质不分裂。","胞质分裂受阻而核分裂仍完成，结果形成含两个细胞核的双核细胞。"]},{"id":"jyq_ch06_38","kind":"fill","q":"动物细胞有丝分裂器包括和。","a":"中心体；纺锤体。","src":"山东大学，2006年","kp":null,"oe":["中心体由中心粒和周围物质组成，是纺锤体的微管组织中心。","纺锤体由微管和结合蛋白构成，负责牵引染色体向两极移动。"]},{"id":"jyq_ch06_39","kind":"mcq","q":"细胞间期是指（）。","o":["A. G,+S+G期","B. S+G期","C. G+S期","D. G期"],"a":"A","src":"南开大学，2009年","kp":null,"e":"细胞间期包括G1期、S期和G2期，是细胞生长、复制DNA并为分裂做准备的阶段。","oe":["正确：间期=G1+S+G2，为细胞分裂做准备。","错误：S+G2缺少G1期，划分不完整。","错误：G1+S缺少G2期，表述不全面。","错误：G期（G0期）是细胞静止期，不属于细胞间期。"]},{"id":"jyq_ch06_40","kind":"mcq","q":"下列关于纺锤体的叙述正确的是（）。","o":["A. 由微管和微管结合蛋白组成","B. 有动力微管和极性微管两种类型","C. 是细胞分裂中染色体分离相关细胞器","D. 以上全对"],"a":"D","src":"南京师范大学，2008年","kp":null,"e":"纺锤体由微管和微管结合蛋白组成，含动力微管与极性微管，是染色体分离相关的细胞器，故以上全对。","oe":["纺锤体确由微管和微管结合蛋白组成，但仅此表述不全面。","纺锤体含动力微管和极性微管，此表述也不完整。","纺锤体确与染色体分离相关，但仅此一项不够全面。","正确：A、B、C均正确，故关于纺锤体的叙述以上全对。"]},{"id":"jyq_ch06_41","kind":"mcq","q":"动物细胞有丝分裂前期不具有的特征是（）。","o":["A. 核仁消失","B. 染色体形成","C. 核膜消失","D. DNA复制"],"a":"D","src":"南京师范大学，2008年","kp":null,"e":"DNA复制发生在S期，而核仁消失、染色体形成和核膜消失均为有丝分裂前期的特征。","oe":["核仁消失是前期特征之一，故不属于前期的是D。","染色体形成即染色质凝缩成染色体，是前期特征之一。","核膜在前期逐渐解体消失，属于前期的特征。","正确：DNA复制在间期S期完成，不属于有丝分裂前期。"]},{"id":"jyq_ch06_42","kind":"short","q":"试述从DNA到染色体的包装过程，并说明细胞通过什么机制使染色体排列到赤道板上。","a":"H2A、H2B、H3、H4组蛋白是核小体核心组蛋白。在一个核小体中，核心组蛋白分别都有两个，它们形成核小体的核心。在连接核小体之间的DNA上，结合有H1组蛋白。对染色体高级结构的形成具有重要作用。由DNA与组蛋白包装成核小体，在组蛋白H1的介导了核小体彼此连接形成直径约10nm的核小体串珠结构，这是染色体包装的一级结构。在组蛋白H1存在的情况下，由直径10nm的核小体串珠结构螺旋盘绕，每圈6个核小体，形成外径30nm，内径10nm，螺距11nm的螺线管，组蛋白H1对螺线管的稳定起着重要作用。多级螺旋模型认为：螺线管是染色体包装的二级结构，螺线管通过进一步螺旋化形成直径","src":"南开大学，2009年","kp":null},{"id":"jyq_ch06_43","kind":"short","q":"敲除了某基因的动物细胞内可观察到纺锤体能将染色体拉向两极，但并不出现胞质分裂。请分析其可能的原因。","a":"可能原因是收缩环收缩和细胞质融合过程中起作用的基因被敲除了。胞质分裂开始时，在赤道板周围细胞表面下陷，形成分裂沟，肌动蛋白和肌球蛋白参与了分裂沟的形成和整个胞质分裂，胞质分裂时大量的肌动蛋白和肌球蛋白组装成微丝，形成收缩环。Larochelle等人在Dictyostelium中发现ras基因家族中的racE基因在收缩环和细胞质融合过程中起重要作用。","src":"武汉大学，2007年","kp":null},{"id":"jyq_ch06_44","kind":"short","q":"细胞通过什么机制将染色体排列到赤道板上？","a":"有何生物学意义？解释这一问题，目前流行两种学说，即牵拉假说和外推假说。牵拉假说认为，染色体向赤道板方向运动，是由于动粒微管牵拉的结果。动粒微管越长，拉力越大，当来自两极的动粒微管的拉力相等时，染色体即被稳定在赤道板上；外推假说认为，染色体向赤道方向移动，是由于星体的排斥力将染色体外推的结果。染色体距离中心体越近，星体对染色体的外推力越强，当来自两极的推力达到平衡时，染色体即被稳定在赤道板上。这两种假说并不排斥，有时可能同时作用，或有其他机制共同参与，最终将染色体排列在赤道板上。由于某些染色体不能被微管及时捕捉而滞后，Mad2和Bub1不能从这些染色体的动粒上消失，后期则不能启动，染色单体不能相互分离。只有等到这些染色体也被微管捕捉并排列到赤道板上，Mad2和Bub1从动粒上消失，后期才能开始启动。故只有染色体排列到赤道板，后期才能开始启动，细胞周期才能顺利进行。生物学意义：微管和动力接触后促使一些蛋白质分子从动粒上释救臻坐物AP咨化，细胞从中第十三章细胞周期与细胞分裂期进入后期。保证每条染色体的两条染色单体分离后分别移向细胞的两极，确保细胞经过有丝分裂后染色体数目的恒定，保持了生物遗传的稳定性。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch06_45","kind":"short","q":"说明细胞分裂后期染色单体分离和向两极移动的运动机制。","a":"答在真核生物的细胞分裂过程中，染色质彼此缠结成有特定形状的染色体。当DNA复制时，两份DNA被环状蛋白复合物结合在一起。这两种物质分别环绕两个DNA链，形成一个网络的节点，该网络将两份DNA保持在一起，直到它们接收到让其分开形成不同子细胞的信号。后期促进因子复合物APC主要介导两类蛋白降解：后期抑制因子和有丝分裂周期蛋白。前者维持姐妹染色单体粘连，抑制后期启动；后者的降解意味着有丝分裂即将结束，即染色体开始去凝集，核膜重建。APC可被Cdc20激活。但是，在有丝分裂前期，Cdc20和Mad2蛋白位于染色体的动粒上，在染色体结合有丝分裂纺锤体的微管前将不能从动粒上释放，由于Mad2与Cdc20结合而抑制Cdc20的活性。所以只有所有染色体都与纺锤体微管结合后，Cdc20释放出来作用于APC，APC才有活性，才能启动细胞向后期转换。解释后期染色单体分离和向两极移动的运动机制，有多种假说。目前比较广泛支持的假说是后期A和后期B两个阶段假说。在后期A，动粒微管变短，将染色体逐渐拉向两极。一般认为，动粒微管变短是由于其动粒端解聚所造成的；而这种解聚又是由于动力蛋白沿动粒微管向极部运动的结果。微管动力蛋极部运动。动粒微管的末端随之降解成微管蛋白二聚体，动粒微管变短，动粒和染色单体与两极之间的距离逐渐拉近。当染色单体接近两极，后期A结束，转向后期B。在后期B，极性微管游离端（正极）在ATP提供能量的情况下微管蛋白聚合，使极性微管加长，形成较宽的极性微管重叠压。移动素类蛋白（KRPs）与极性微管重叠区的微管结合，并在来自两极的极性微管之间搭桥。KRPs向微管正极行走，促使来自两极的极性微管在重叠区相互滑动，使重叠区逐渐变得狭窄，两极之间的距离逐渐变长。同时，胞质动力蛋白在星体微管之间搭桥，并向星体微管负极运动，进一步将两极之间的距离拉长。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch06_46","kind":"short","q":"肿瘤干细胞（tumorstemcells）","a":"一般认为来源于恶性干细胞，在肿瘤中有1%~4%的肿瘤细胞具有很强的分裂能力，被称为肿瘤干细胞。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch06_47","kind":"judge","q":"有亮氨酸拉链模式（Leucine-Zippermotif）的jun和fos蛋白质是以多聚体的形式结合DNA的。","a":"错","src":"南京师范大学，2008年","kp":null,"oe":["Jun、Fos确有亮氨酸拉链并能结合DNA，但多聚体表述不准确，易误选对。","Jun/Fos以二聚体（bZIP）形式结合DNA，且Fos需与Jun配对，“多聚体”表述不当。"]},{"id":"jyq_ch06_48","kind":"mcq","q":"细胞周期中，决定一个细胞是分化还是增殖的控制点（R点）位于（）。","o":["A. G期末","B. G2期末","C. M期末","D. G期末"],"a":"A","src":"南京师范大学，2008年","kp":null,"e":"细胞周期的限制点（R点）位于G1期晚期，是决定细胞继续增殖还是退出周期分化的关键调控点。","oe":["正确：R点位于G1期末（晚期），决定细胞走向增殖或分化。","错误：G2期末检查点控制进入M期，不是R点所在。","错误：M期末检查点涉及分裂完成，并非R点。","错误：G0期是细胞静止期，不是R点所在的位置。"]},{"id":"jyq_ch06_49","kind":"mcq","q":"有丝分裂后期的起始需要（）活力驱动。","o":["A. 蛋白酶","B. 核酸酶","C. 蛋白激酶","D. 磷酸酯酶"],"a":"B","src":"中国科学院，2000年","kp":null,"e":"有丝分裂后期起始由后期促进复合物（APC）降解securin、激活分离酶（蛋白酶）驱动，需蛋白酶活力；题给答案B有误，应为A。","oe":["正确：分离酶是蛋白酶，切割黏连蛋白使姐妹染色单体分离，故需蛋白酶活力。","错误：核酸酶降解核酸，与后期染色单体分离无直接关系，题给答案有误。","错误：蛋白激酶MPF驱动G2进入M期，后期起始主要靠蛋白酶。","错误：磷酸酯酶参与MPF失活，但后期起始的直接驱动力是蛋白酶。"],"doubt":1},{"id":"jyq_ch06_50","kind":"short","q":"细胞周期中有哪些主要检验点，各起何作用？","a":"答细胞周期中主要检验点有以下四个：①G/S检验点：在酵母中称为start点，在哺乳动物中称R点。DNA是否损伤？细胞外环境是否适宜？细胞体积是否足够大？②S期检验点：DNA复制是否完成？③G2/M检验点：DNA是否损伤？细胞体积是否足够大？④中-后期检验点：纺锤体组装检验点。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch06_51","kind":"short","q":"干细胞（stemcell）","a":"是一类具有分裂和分化能力的细胞。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch06_52","kind":"short","q":"成纤维细胞（fibroblast）","a":"该细胞是构成纤维性结缔组织的重要成分。观察组织切片，可见这些细胞具有长而扁平的外形，常有不规则的突起。细胞质内含有线粒体、高尔基体、中心体、微脂肪粒等、其他无特殊的分化。细胞核呈椭圆形，有明显的核仁，细胞核染色性差。常与胶原纤维紧密相连，因与胶原纤维的形成有关故称为成纤维细胞。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch06_53","kind":"short","q":"从端粒酶的结构与功能论述其与衰老和癌症的关系。","a":"端粒是染色体末端的一种特殊结构，其中DNA由简单的串联重复序列组成。它们在细胞分裂过程中不能为DNA聚合酶完全复制，因而随着细胞分裂的不断进行而逐渐变短，除非有端粒酶的存在。端粒酶是一种核糖核蛋白酶，由RNA和蛋白质组成。端粒酶RNA是合成端粒DNA的模板，而端粒酶的粒酶的活性，端粒保持约15kb的长度，而在人的体细胞中，由于不存在端粒酶活性，端粒要短得多。在体外培养的成纤维细胞中，端粒长度则随着分裂次数的增加而下降，在此基础上提出的细胞衰老的老。1998年，wright等人将端粒酶基因通过转染引[人了正常的人二倍体细胞，发现表达端粒酶的转染细胞其端粒长度明显增加，分裂旺盛，作为衰老标志的β-半乳糖苷酶活性则明显降低，细胞寿命至少比正常在“有丝分裂钟”学说基础上，如果细胞已经进人衰老期，端粒长度缩小的很短，几乎已经达到极限，细胞理应衰老直至死亡，但如果细胞受到某些外因刺激或自发突变，使自身的端粒酶表达量上调，端粒酶活性升高，则细胞的端粒又可以加长，并维持细胞不衰老，不死亡，这种情况下，该细胞就是发生了癌性突变的细胞，该细胞及其增殖的后代将会发育成一个肿瘤，甚至会恶化形成癌症。有关细胞衰老的分子机制和假说有几种，除了“有丝分裂钟”假说之外，还有氧化损伤理论等。更可能的一种情况是多种机制共同作用导致了细胞衰老而不是单纯一个因素。","src":"南开大学，2009年","kp":null}],"outline":["微管结构(αβ-tubulin)","组装与动态不稳定","MTOC 与极性","马达蛋白(kinesin/dynein)","功能(纺锤体/鞭毛/运输)"],"outlineMap":[3,2,2,6,14],"narrative":"细胞骨架由微管、微丝、中间纤维组成，维持形态、参与运动与运输。微管由 αβ-微管蛋白二聚体首尾相接成原纤维、13 条围成中空管，外径约 24nm、有极性。微管有动态不稳定性（GTP 帽稳定、丢失后骤缩）与踏车现象；MTOC（动物细胞中心体）以 γ-tubulin 成核，决定微管方向。马达蛋白 kinesin 向正端、dynein 向负端运输货物；鞭毛/纤毛以 9+2 轴丝、靠 dynein 滑动转为弯曲。分裂时微管组成纺锤体，通过后期 A（染色体向极）与后期 B（两极分离）完成染色体分配。","preview":{"main":"本章讲细胞骨架的组成与微管：微管的结构与极性、动态不稳定性与踏车、微管组织中心(MTOC)与成核、马达蛋白(kinesin/dynein)，以及微管在物质运输、鞭毛纤毛运动和染色体运动中的功能。","questions":["微管由什么组装、结构上有何特点？三种骨架纤维如何比较？","什么是微管的动态不稳定性和踏车？GTP 帽起什么作用？","微管组织中心如何成核并决定微管方向？","驱动蛋白与动力蛋白在运输和运动中的方向与分工是什么？","微管在染色体运动（纺锤体）中如何起作用？"],"answers":["微管由 αβ-微管蛋白二聚体首尾相接成原纤维、13 条围成中空管；微管24nm中空有极、微丝7nm实心有极、中间纤维10nm实心无极。","动态不稳定性是末端在生长/骤缩间随机切换，GTP 帽稳定微管、丢失后解聚；踏车是正端聚合、负端解聚、长度不变。","MTOC 以 γ-tubulin 环成核，微管负端埋入、正端朝外，决定微管起点与方向（动物细胞中心体）。","kinesin 向微管正端、dynein 向负端运输；鞭毛纤毛靠 dynein 滑动→弯曲。","微管组成纺锤体三类微管，前中期“搜索-捕获”动粒整列，后期A 染色体向极、后期B 两极分离。"]}};